__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lorePack",{enumerable:!0,get:function(){return f}});var s=r(d[0]),o=r(d[1]),t=r(d[2]),n=r(d[3]),c=r(d[4]),l=r(d[5]),p=r(d[6]),u=r(d[7]),h=r(d[8]),w=r(d[9]);const f={entries:{...s.chapters1,...o.chapters2,...t.classes,...n.races,...c.zones1,...l.zones2,...p.instances1,...u.instances2,...h.items,...w.terms},eras:{creation:{title:"Tit\xe3s e Deuses Antigos",when:"Antes da hist\xf3ria registrada"},"ancient-kalimdor":{title:"O imp\xe9rio kaldorei",when:"Dez mil anos ou mais antes do Portal Negro"},"elder-kingdoms":{title:"Os reinos antigos",when:"Cerca de 7.000 a 200 anos antes do Portal Negro"},draenor:{title:"Os orcs de Draenor",when:"As d\xe9cadas anteriores ao Portal Negro"},"first-war":{title:"A Primeira Guerra",when:"A abertura do Portal Negro (ano 0)"},"second-war":{title:"A Segunda Guerra",when:"Alguns anos ap\xf3s o Portal Negro"},interwar:{title:"Entre as guerras",when:"Os anos ap\xf3s a Segunda Guerra"},"third-war":{title:"A Terceira Guerra",when:"Cerca de vinte anos ap\xf3s o Portal Negro"},"new-homes":{title:"Novos lares em Kalimdor",when:"Os anos ap\xf3s a Terceira Guerra"},classic:{title:"A era de World of Warcraft",when:"Ano 25 ap\xf3s o Portal Negro, a \xe9poca de Forever"},beyond:{title:"Depois de Classic",when:"Expans\xf5es posteriores (n\xe3o fazem parte de Forever)"}},categories:{chapter:"A hist\xf3ria de Warcraft",class:"Classes",race:"Ra\xe7as",zone:"Zonas",instance:"Masmorras e raides",item:"Itens lend\xe1rios",term:"Gloss\xe1rio"},notice:"Texto original escrito para o WoW Forever Path. Os fatos foram conferidos com as fontes listadas; as p\xe1ginas do warcraft.wiki.gg (CC BY-SA 4.0) e as publica\xe7\xf5es da Blizzard serviram de refer\xeancia, sem c\xf3pia de texto. World of Warcraft e Blizzard s\xe3o marcas comerciais da Blizzard Entertainment, Inc."}},1576,[1613,1614,1615,1616,1617,1618,1619,1620,1621,1622]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return o}});const o={"chapter:titans-and-old-gods":{title:"Os tit\xe3s e os Deuses Antigos",summary:"Antes de qualquer reino mortal, os tit\xe3s do Pante\xe3o lutaram contra os Deuses Antigos pela alma de um mundo jovem, e Azeroth ainda carrega as cicatrizes.",when:"Antes da hist\xf3ria registrada",body:["Muito antes de os mortais registrarem qualquer coisa, os tit\xe3s percorriam a imensa escurid\xe3o do cosmos: almas-mundo que haviam crescido at\xe9 se tornarem gigantes vivos. Os mais nobres se reuniram no Pante\xe3o e vasculharam as estrelas em busca de almas-mundo adormecidas como as deles. Nas profundezas de Azeroth, sentiram uma de promessa extraordin\xe1ria, mas poderes mais sombrios a haviam encontrado primeiro.","Os senhores do Caos tinham arremessado seus servos, os Deuses Antigos, sobre o jovem mundo. Y'Shaarj, C'Thun, Yogg-Saron e N'Zoth afundaram seus corpos na crosta e ergueram o Imp\xe9rio Negro, tendo como generais os senhores elementais do fogo, da terra, do ar e da \xe1gua. Quando o Pante\xe3o chegou, seus ex\xe9rcitos forjados pelos tit\xe3s destru\xedram as cidadelas do imp\xe9rio. O Alto-pai Aman'Thul arrancou Y'Shaarj do ch\xe3o, mas o golpe abriu uma ferida que fez sangrar a seiva arcana do mundo. Os tit\xe3s entenderam que matar os demais poderia matar a pr\xf3pria Azeroth.","Ent\xe3o os guardi\xf5es escolheram pris\xf5es. C'Thun, Yogg-Saron e N'Zoth foram acorrentados nas profundezas da terra, e os senhores elementais foram banidos para o Plano Elemental, cujos reinos incluem Skywall e as Terras do Fogo. Os guardi\xf5es acalmaram a ferida sangrenta at\xe9 transform\xe1-la em um lago reluzente, a Nascente da Eternidade, moldaram montanhas e mares e deixaram para tr\xe1s c\xe2maras tit\xe2nicas como Uldaman. Depois que um monstruoso protodrag\xe3o chamado Galakrond caiu, o Pante\xe3o elevou cinco grandes drag\xf5es a Aspectos para proteger o mundo e ent\xe3o partiu rumo \xe0s estrelas."]},"chapter:sargeras-and-the-burning-legion":{title:"Sargeras e a Legi\xe3o Ardente",summary:"O maior campe\xe3o do Pante\xe3o perdeu a f\xe9 na cria\xe7\xe3o e ergueu uma cruzada demon\xedaca para queim\xe1-la, e Azeroth se tornou o pr\xeamio que ele mais desejava.",when:"Muito antes dos elfos noturnos",body:["Sargeras era o campe\xe3o do Pante\xe3o, o tit\xe3 que ca\xe7ava dem\xf4nios por todo o cosmos e os trancava em um mundo-pris\xe3o chamado Mardum. Ao longo de eras de guerra, ele descobriu o que os senhores do Caos realmente queriam: corromper uma alma-mundo e gerar um tit\xe3 sombrio s\xf3 deles. Convencido de que a cria\xe7\xe3o tinha falhas sem salva\xe7\xe3o, decidiu que seria mais piedoso queimar tudo.","Ele despeda\xe7ou a pris\xe3o de Mardum e soltou seus dem\xf4nios como as primeiras fileiras da Legi\xe3o Ardente. No mundo de Argus, ofereceu conhecimento e poder aos eredar; seus l\xedderes, Kil'jaeden e Archimonde, aceitaram, enquanto o profeta Velen fugiu com os que recusaram, o povo mais tarde chamado de draeneis. O Pante\xe3o tentou deter seu antigo campe\xe3o e tombou pelas m\xe3os dele.","Da\xed em diante, a Legi\xe3o passou de mundo em mundo, liderada por Sargeras e servida pelos eredar, pelos senhores do medo chamados nathrezim e por incont\xe1veis dem\xf4nios menores. Azeroth importava mais do que a maioria: uma alma-mundo ainda adormecida, j\xe1 marcada pelos Deuses Antigos. Na \xe9poca de World of Warcraft, a Legi\xe3o j\xe1 a havia invadido duas vezes, e seus sussurros moldaram a hist\xf3ria de elfos, orcs e humanos."]},"chapter:rise-of-the-kaldorei":{title:"A ascens\xe3o dos kaldorei",summary:"Os trolls dominaram a antiga Kalimdor at\xe9 que uma tribo atra\xedda pela Nascente da Eternidade se tornou os elfos noturnos, cuja rainha Azshara construiu um imp\xe9rio de magia deslumbrante.",when:"Cerca de 15.000 a 10.000 anos antes do Portal Negro",body:["Nas eras ap\xf3s a partida dos tit\xe3s, Kalimdor era um \xfanico e grande continente. Liderados pelos Zandalari, os trolls travaram uma longa guerra contra os aqir, criaturas semelhantes a insetos, remanescentes dos servos dos Deuses Antigos, e os empurraram para os extremos norte e sul da terra, onde seus descendentes se tornariam os nerubianos e os qiraji. Na vit\xf3ria, os trolls se dividiram em imp\xe9rios rivais, como os dos Gurubashi e dos Amani.","Uma tribo troll escolheu um caminho mais tranquilo. Ela se estabeleceu \xe0s margens da Nascente da Eternidade e, ao longo de gera\xe7\xf5es, o poder da Nascente a transformou: seu povo ficou mais alto e longevo, passou a venerar a deusa lunar Eluna e a chamar a si mesmo de kaldorei, \u201cfilhos das estrelas\u201d. Guiados pelo semideus Cenarius e por outros esp\xedritos ancestrais da natureza, logo ofuscaram seus primos trolls.","Sua maior soberana foi a rainha Azshara, adorada pelo povo e servida pelos Bem-nascidos, uma aristocracia de feiticeiros que extra\xeda cada vez mais poder da Nascente. Seu pal\xe1cio em Zin-Azshari ficava \xe0 margem, e seu imp\xe9rio se espalhou por toda Kalimdor. A fome de magia dos Bem-nascidos, por\xe9m, enviou ondas muito al\xe9m do mundo, e algo vasto na Espiral Et\xe9rea as sentiu."]},"chapter:war-of-the-ancients":{title:"A Guerra dos Antigos",summary:"Azshara abriu caminho para a Legi\xe3o Ardente, e o mundo quase chegou ao fim antes que a Nascente da Eternidade se despeda\xe7asse.",when:"Cerca de 10.000 anos antes do Portal Negro",body:["Sargeras sussurrou para Azshara e seus Bem-nascidos, prometendo um mundo refeito \xe0 imagem deles. Eles acreditaram e, atrav\xe9s da Nascente da Eternidade, abriram um portal para a Legi\xe3o Ardente. Dem\xf4nios liderados por Archimonde e Mannoroth invadiram Kalimdor e come\xe7aram a massacrar os pr\xf3prios kaldorei governados pela rainha.","A resist\xeancia se reuniu em torno de l\xedderes improv\xe1veis: Malfurion Tempesf\xfaria, o primeiro elfo noturno a aprender o druidismo com Cenarius; seu irm\xe3o g\xeameo Illidan, um feiticeiro talentoso; e Tyrande Sussurravento, sacerdotisa de Eluna. Os semideuses da natureza e a maioria das revoadas drac\xf4nicas lutaram ao lado deles. O Aspecto negro Neltharion ofereceu uma arma, a Alma Drag\xf4nica, mas a voltou contra os aliados; essa trai\xe7\xe3o lhe renderia o nome Asa da Morte.","Quando o pr\xf3prio Sargeras tentou atravessar o portal, Malfurion e seus aliados perturbaram o feiti\xe7o dos Bem-nascidos. A Nascente, inst\xe1vel, implodiu, e veio a Grande Cis\xe3o: o mar engoliu Zin-Azshari, Kalimdor se partiu, e uma tempestade chamada Voragem come\xe7ou a girar onde a Nascente estivera. Azshara e sua corte desapareceram sob as ondas, para um dia voltar como os nagas. Do continente \xfanico surgiram as terras hoje conhecidas como Kalimdor, os Reinos do Leste e Nort\xfandria."]},"chapter:the-long-watch-of-hyjal":{title:"A longa vig\xedlia de Hyjal",summary:"Os sobreviventes fizeram crescer uma \xc1rvore do Mundo sobre uma segunda Nascente, aprisionaram Illidan sob a terra e montaram guarda por dez mil anos.",when:"A partir de cerca de 10.000 anos antes do Portal Negro",body:["Os elfos noturnos que escaparam da Cis\xe3o se reuniram no Monte Hyjal. L\xe1 descobriram que Illidan havia levado frascos com a \xe1gua da antiga Nascente e despejado parte dela em um lago na montanha, criando uma nova Nascente da Eternidade. Temendo que ela um dia chamasse a Legi\xe3o de volta, Malfurion e Cenarius aprisionaram Illidan nas Barrow Deeps, uma pris\xe3o sob a terra onde a carcereira Maiev Cantonegro o vigiaria por dez mil anos.","Tr\xeas Aspectos, Alexstrasza, Ysera e Nozdormu, responderam fazendo crescer Nordrassil, a \xc1rvore do Mundo, sobre a nova Nascente. Suas ra\xedzes selaram as \xe1guas, e sua b\xean\xe7\xe3o deu aos elfos noturnos a imortalidade e aos druidas um v\xednculo com o Sonho Esmeralda, onde muitos deles dormiam por s\xe9culos. Tyrande liderava a Irmandade de Eluna e as Sentinelas, que guardavam as florestas enquanto os druidas sonhavam. A magia arcana foi proibida entre os kaldorei.","Nem todos os Bem-nascidos obedeceram. Alguns foram exilados para o outro lado do mar e fundaram Quel'Thalas; outros, os Shen'dralar, esconderam-se na cidade de Eldre'Thalas, no que hoje \xe9 Feralas. Suas ru\xednas s\xe3o conhecidas hoje como Gl\xe1dio Cruel."]},"chapter:exiles-of-quelthalas":{title:"Os exilados de Quel'Thalas",summary:"Bem-nascidos banidos atravessaram o mar, acenderam a Nascente do Sol e constru\xedram um reino \xe9lfico nas florestas do norte de Lordaeron.",when:"Cerca de 6.800 anos antes do Portal Negro",body:["Muito depois da Cis\xe3o, um grupo de Bem-nascidos ainda n\xe3o conseguia abandonar o arcano. Seus feiti\xe7os imprudentes levantaram tempestades sobre Vale Gris, e os elfos noturnos finalmente os baniram. Liderados por Dath'Remar Andassol, os exilados navegaram para o leste atrav\xe9s do Grande Mar e vagaram por anos pelo novo continente em busca de uma terra onde a magia corresse forte.","Cerca de 6.800 anos antes do Portal Negro, encontraram-na no norte de Lordaeron. Dath'Remar despejou um frasco roubado de \xe1gua da Nascente da Eternidade em um lago sobre um nexo de linhas de Ley, e a Nascente do Sol ganhou vida em chamas. Ao redor dela surgiram Quel'Thalas e sua capital, Luaprata. Vivendo sob o sol em vez da lua, os exilados mudaram ao longo dos s\xe9culos e se tornaram os altos elfos, os quel'dorei.","A terra n\xe3o estava vazia. Guardava ru\xednas antigas, sagradas para os trolls Amani, que atacaram os rec\xe9m-chegados em n\xfameros esmagadores. Os elfos os contiveram com magia e ergueram Ban'dinoriel, uma barreira de pedras r\xfanicas que manteve os Amani afastados. Por cerca de quatro mil anos, Quel'Thalas prosperou atr\xe1s dela, enquanto os trolls esperavam por vingan\xe7a."]},"chapter:arathor-and-the-troll-wars":{title:"Arathor e as Guerras Trolls",summary:"As tribos dispersas da humanidade se uniram sob o rei Thoradin, e uma alian\xe7a com os elfos esmagou o Imp\xe9rio Amani ao p\xe9 das Montanhas de Alterac.",when:"Cerca de 2.800 anos antes do Portal Negro",body:["Por mil\xeanios, as tribos humanas dos Reinos do Leste lutaram entre si enquanto saqueadores Amani atacavam do norte. Cerca de 2.800 anos antes do Portal Negro, Thoradin, da tribo Arathi, percebeu que uma humanidade dividida seria destru\xedda. Por meio de casamentos, promessas e conquistas, ele uniu as tribos no reino de Arathor e construiu sua capital, a cidade-fortaleza de Strom, no atual Planalto Arathi.","Os Amani, revigorados com a ajuda dos Zandalari, atacaram Quel'Thalas em n\xfameros enormes. Os elfos recorreram a Arathor. Em troca de soldados humanos, concordaram em ensinar magia a cem humanos escolhidos, os primeiros magos humanos. Juntos, elfos e humanos esmagaram o ex\xe9rcito Amani ao p\xe9 das Montanhas de Alterac, e o fogo dos magos dispersou os trolls de forma t\xe3o completa que seu imp\xe9rio nunca se recuperou.","Em gratid\xe3o, os elfos de Quel'Thalas juraram lealdade \xe0 linhagem dos reis de Arathor. Strom floresceu, e seu povo se espalhou pelo norte. Os Amani se ergueriam muitas outras vezes, e nas Terras Agrestes e no Planalto Arathi tribos de trolls da floresta ainda assombram as ru\xednas daquela antiga guerra."]},"chapter:guardians-and-the-seven-kingdoms":{title:"Os Guardi\xf5es e os Sete Reinos",summary:"A magia humana atraiu dem\xf4nios, ent\xe3o os magos fundaram Dalaran e escolheram Guardi\xf5es para lutar em segredo, enquanto Arathor se dividia em sete reinos.",when:"Os mil\xeanios ap\xf3s as Guerras Trolls",body:["A magia se espalhou por Arathor mais depressa que a sabedoria. Os feiti\xe7os dos magos enfraqueceram as paredes do mundo e atra\xedram a aten\xe7\xe3o de dem\xf4nios, e assim os altos elfos e os magos humanos formaram o Conselho de Tirisfal. Em segredo, o conselho escolhia um \xfanico Guardi\xe3o para portar seu poder combinado e ca\xe7ar os agentes da Legi\xe3o Ardente.","Os magos tamb\xe9m constru\xedram uma cidade pr\xf3pria, Dalaran, onde o Kirin Tor governaria. Enquanto isso, os herdeiros de Arathor se afastaram de Strom, e ao longo dos s\xe9culos o imp\xe9rio se dividiu em sete reinos humanos: Lordaeron, Stromgarde, Gilneas, Alterac, Kul Tiras, Dalaran e, ao sul, Ventobravo, que por muito tempo foi chamado de reino de Azeroth.","A Guardi\xe3 mais famosa foi Aegwynn, que em Nort\xfandria derrubou um avatar do pr\xf3prio Sargeras e selou seu corpo em uma tumba sob o mar. Ela nunca soube que o esp\xedrito do tit\xe3 sombrio havia se infiltrado nela. Quando deu \xe0 luz um filho, Medivh, o esp\xedrito passou para ele, e o \xfaltimo Guardi\xe3o cresceu com um traidor escondido na alma. De sua torre em Karazhan, ele um dia abriria a porta para os orcs."]},"chapter:war-of-the-three-hammers":{title:"A Guerra dos Tr\xeas Martelos",summary:"Os tr\xeas cl\xe3s an\xf5es de Altaforja disputaram o trono, e um thane feiticeiro derrotado invocou Ragnaros, que queimou a terra at\xe9 formar a Montanha Rocha Negra.",when:"Cerca de 230 anos antes do Portal Negro",body:["Sob as neves de Dun Morogh, os an\xf5es escavaram Altaforja, um reino de pedra e of\xedcio cujas ra\xedzes remontavam aos terranos dos tit\xe3s. Tr\xeas cl\xe3s o dividiam em uma conviv\xeancia tensa: os Barbabronze, os Martelo Feroz e os Ferro Negro, apaixonados por feiti\xe7aria. Quando o grande rei Modimus Anvilmar morreu, cerca de 230 anos antes do Portal Negro, a rivalidade deles explodiu em guerra civil.","Os Barbabronze venceram e expulsaram os outros. Os Martelo Feroz constru\xedram Grim Batol a leste, e os Ferro Negro fundaram um reino pr\xf3prio ao sul, nas Montanhas Cristarrubra. O thane feiticeiro Thaurissan n\xe3o conseguiu aceitar a derrota. Atacou os dois rivais ao mesmo tempo, mas seus ex\xe9rcitos foram destro\xe7ados, e sua esposa Modgud tombou em Grim Batol.","Desesperado, Thaurissan buscou um poder maior e invocou Ragnaros, o Senhor do Fogo, um senhor elemental que os tit\xe3s haviam aprisionado. A chegada do Senhor do Fogo matou o thane, rasgou a terra formando a Garganta Abrasadora e as Estepes Ardentes e ergueu a Montanha Rocha Negra, onde os Ferro Negro sobreviventes se tornaram seus escravos. Os Martelo Feroz abandonaram a amaldi\xe7oada Grim Batol rumo \xe0s Terras Agrestes. Seus vizinhos gnomos, cuja cidade de Gnomeregan ficava ali perto, tornaram-se amigos fi\xe9is de Altaforja."]},"chapter:corruption-of-the-orcs":{title:"A corrup\xe7\xe3o dos orcs",summary:"No distante Draenor, Kil'jaeden transformou os cl\xe3s xam\xe2nicos dos orcs em uma Horda sanguin\xe1ria unida pelo sangue demon\xedaco.",when:"As d\xe9cadas anteriores ao Portal Negro",body:["No mundo de Draenor, os orcs viviam em orgulhosos cl\xe3s de ca\xe7adores e xam\xe3s, honrando seus ancestrais e os esp\xedritos dos elementos. Dividiam o mundo, sem muita harmonia, com os draeneis, os eredar que haviam fugido de Argus com Velen. Kil'jaeden nunca deixara de ca\xe7ar esses exilados, e nos orcs viu uma arma.","Disfar\xe7ado como o esp\xedrito da falecida esposa de Ner'zhul, o lorde dem\xf4nio sussurrou ao velho xam\xe3 e o voltou contra os draeneis. Quando Ner'zhul hesitou, Kil'jaeden encontrou um aluno mais disposto em Gul'dan, que fundou o secreto Conselho das Sombras e ensinou aos orcs a magia vil; eles foram os primeiros bruxos. Os elementos se calaram, e a terra verde dos orcs come\xe7ou a morrer.","Em uma grande reuni\xe3o, os chefes dos cl\xe3s beberam o sangue do senhor do abismo Mannoroth, e Grom Grito Infernal, do cl\xe3 Brado Guerreiro, bebeu primeiro. Tomada de f\xfaria demon\xedaca, a Horda unida caiu sobre os draeneis e quase os exterminou. S\xf3 o cl\xe3 Lobo do Gelo, de Durotan, ficou parcialmente \xe0 parte. Terminada a matan\xe7a, Gul'dan precisava de uma nova guerra, e o mestre de Kil'jaeden j\xe1 tinha uma esperando em Azeroth."]},"chapter:the-first-war":{title:"O Portal Negro e a Primeira Guerra",summary:"Medivh ajudou os orcs a abrir o Portal Negro, e a Horda arrasou o reino de Ventobravo.",when:"Ano 0: o Portal Negro se abre",body:["Guiados por um Medivh possu\xeddo, os bruxos de Gul'dan e o Guardi\xe3o abriram uma fenda entre Draenor e Azeroth no Lama\xe7al Negro, o p\xe2ntano que mais tarde definharia at\xe9 se tornar a Barreira do Inferno. Os orcs atravessaram aos montes o que ficou conhecido como o Portal Negro, e seus batedores logo encontraram os campos f\xe9rteis do reino de Azeroth, a atual Ventobravo.","O rei Llane Wrynn e seu campe\xe3o Anduin Lothar resistiram por anos. O pr\xf3prio aprendiz de Medivh, Khadgar, descobriu a trai\xe7\xe3o de seu mestre e, com Lothar e a meio-orc Garona, enfrentou o Guardi\xe3o em Karazhan e o matou. A vit\xf3ria chegou tarde demais. Os bandos de guerra da Horda queimaram o reino de ponta a ponta, e dentro da Horda o astuto Orgrim Martelo da Perdi\xe7\xe3o derrubou M\xe3o Negra e se tornou Chefe Guerreiro.","Garona, presa aos feiti\xe7os de Gul'dan, assassinou o rei Llane, e a cidade de Ventobravo caiu em chamas. Lothar reuniu os sobreviventes, entre eles o jovem filho de Llane, Varian, e os levou atrav\xe9s do mar at\xe9 Lordaeron. Bem a leste, nas Riverglades, uma regi\xe3o que s\xf3 existe em Forever, a Horda arrasou o vilarejo de Sunnyglade e levou seus sobreviventes como escravos."]},"chapter:the-second-war":{title:"A Segunda Guerra",summary:"Os reinos humanos, os elfos, os an\xf5es e os gnomos se uniram na Alian\xe7a de Lordaeron e esmagaram a Horda de Martelo da Perdi\xe7\xe3o no Pico da Rocha Negra.",when:"Cerca de cinco a seis anos ap\xf3s o Portal Negro",body:["O alerta de Lothar levou o rei Terenas Menethil de Lordaeron a reunir os reinos humanos. Eles formaram a Alian\xe7a de Lordaeron, com Lothar como comandante supremo; os an\xf5es de Altaforja, os gnomos e, fi\xe9is ao antigo juramento \xe0 linhagem de Arathor, os altos elfos de Quel'Thalas se juntaram a eles. Para dar esperan\xe7a aos soldados, o arcebispo Alonsus Faol fundou os Cavaleiros da M\xe3o de Prata, os primeiros paladinos, com Uther, o Arauto da Luz, \xe0 frente.","A Horda de Martelo da Perdi\xe7\xe3o tamb\xe9m havia crescido. Ogros, trolls Amani comandados por Zul'jin e sapadores goblins lutavam ao lado dos orcs; o cl\xe3 Dragonmaw usou a Alma Drag\xf4nica de Asa da Morte para escravizar drag\xf5es vermelhos em Grim Batol; Gul'dan ergueu os primeiros cavaleiros da morte. A Horda invadiu Khaz Modan, queimou partes de Quel'Thalas e sitiou a capital de Lordaeron.","No momento decisivo, Gul'dan traiu Martelo da Perdi\xe7\xe3o e zarpou para erguer a Tumba de Sargeras, levando consigo dois cl\xe3s, os Stormreaver e o Martelo do Crep\xfasculo. Enfraquecida, a Horda recuou para a Montanha Rocha Negra. Na batalha no Pico da Rocha Negra, Martelo da Perdi\xe7\xe3o matou Lothar, mas o tenente de Lothar, Turalyon, esmagou a Horda, e Khadgar destruiu o Portal Negro. Os orcs sobreviventes foram confinados em campos de interna\xe7\xe3o. Nas Riverglades de Forever, ogros do Martelo do Crep\xfasculo e orcs Stormreaver que fugiam da Tumba encontraram um novo lar."]}}},1613,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters2",{enumerable:!0,get:function(){return o}});const o={"chapter:beyond-the-dark-portal":{title:"Al\xe9m do Portal Negro",summary:"Ner'zhul reabriu o portal e despeda\xe7ou Draenor, e Kil'jaeden transformou o velho xam\xe3 no Lich Rei.",when:"Pouco depois da Segunda Guerra",body:["Com Gul'dan morto e a Horda aprisionada, o velho Ner'zhul reuniu os orcs que haviam ficado em Draenor. Ele reabriu o Portal Negro e enviou saqueadores a Azeroth para roubar artefatos poderosos, na esperan\xe7a de abrir portais para novos mundos onde seu povo pudesse se refugiar.","A Alian\xe7a respondeu com uma expedi\xe7\xe3o atrav\xe9s do portal sob o comando de Turalyon e Khadgar, \xe0 qual se juntaram a patrulheira Alleria Correventos, o an\xe3o Kurdran Martelo Feroz e o guerreiro Danath Trollbane. Eles combateram a nova Horda por todo Draenor, mas os portais de Ner'zhul j\xe1 estavam despeda\xe7ando o mundo. Para salvar Azeroth, a expedi\xe7\xe3o destruiu o Portal Negro pelo outro lado, prendendo-se nos restos despeda\xe7ados que se tornariam Terral\xe9m.","Ner'zhul escapou por uma de suas fendas, direto para as m\xe3os de Kil'jaeden. O dem\xf4nio arrancou-lhe o corpo, mas manteve seu esp\xedrito, prendeu-o a uma armadura encantada e o selou em um bloco de gelo junto com a l\xe2mina r\xfanica G\xe9lido Lamento. Arremessado aos ermos congelados de Nort\xfandria, o Trono de Gelo tornou-se a sede de um novo poder: o Lich Rei, cuja tarefa era espalhar uma praga de morte-vida e enfraquecer Azeroth para o retorno da Legi\xe3o."]},"chapter:thrall-and-the-new-horde":{title:"Thrall e a nova Horda",summary:"Um orc criado como escravo fugiu de Durnholde, redescobriu o xamanismo e libertou seu povo dos campos de interna\xe7\xe3o.",when:"Os anos anteriores \xe0 Terceira Guerra",body:["Nos campos de interna\xe7\xe3o, os orcs afundaram em uma estranha letargia \xe0 medida que a f\xfaria demon\xedaca os abandonava. Lorde Aedelas Blackmoore, do Forte de Durnholde, no Contraforte de Eira dos Montes, havia encontrado anos antes um beb\xea orc \xf3rf\xe3o e o criara como gladiador e futura arma. Deu ao menino o nome de Thrall, palavra que significa escravo. S\xf3 Taretha Foxton, uma criada, o tratava com bondade, e com a ajuda dela Thrall finalmente escapou.","Livre pela primeira vez, Thrall buscou as lendas de seu pr\xf3prio povo. Grom Grito Infernal mostrou-lhe o que um orc podia ser, o velho Orgrim Martelo da Perdi\xe7\xe3o o fez seu bra\xe7o direito, e entre o cl\xe3 Lobo do Gelo, nas Montanhas de Alterac, o xam\xe3 Drek'Thar o ensinou a falar com os elementos. L\xe1 ele descobriu que era filho de Durotan, o chefe dos Lobo do Gelo.","Thrall, Grom e Martelo da Perdi\xe7\xe3o libertaram um campo ap\xf3s o outro. Martelo da Perdi\xe7\xe3o caiu em batalha e passou a Thrall sua armadura negra e seu martelo, e Thrall se tornou Chefe Guerreiro de uma nova Horda fundada na honra e no xamanismo, n\xe3o no sangue demon\xedaco. Em Durnholde ele derrotou Blackmoore, mas Taretha n\xe3o sobreviveu. Agora Thrall s\xf3 queria uma terra onde seu povo pudesse viver em paz."]},"chapter:the-lich-king-and-the-plague":{title:"O Lich Rei e a praga",summary:"De Nort\xfandria, o Lich Rei estendeu seu alcance para o sul, e o arquimago Kel'Thuzad espalhou uma praga de morte-vida pelos gr\xe3os de Lordaeron.",when:"\xc0s v\xe9speras da Terceira Guerra",body:["Preso no Trono de Gelo, o Lich Rei ainda estendia sua mente por toda Nort\xfandria. Conquistou o reino aracn\xeddeo de Azjol-Nerub, ergueu seu povo como servos e construiu uma fortaleza em torno de seu trono na Coroa de Gelo. Ent\xe3o voltou o olhar para o sul, para os reinos humanos cansados da guerra.","Em Dalaran, o respeitado arquimago Kel'Thuzad ficara obcecado pela necromancia. Quando o Kirin Tor rejeitou seus estudos, ele atendeu ao chamado do Lich Rei, viajou a Nort\xfandria e voltou como seu profeta. Fundou o Culto dos Malditos, prometendo aos pobres de Lordaeron igualdade e vida eterna, e usou seus membros para espalhar uma praga escondida em carregamentos de gr\xe3os.","A praga matava suas v\xedtimas e depois as erguia como mortos-vivos sem mente: o Flagelo. Aldeias do norte de Lordaeron ca\xedram uma ap\xf3s a outra enquanto os reinos discutiam impostos e o custo dos campos de interna\xe7\xe3o. Quando o Kirin Tor e a M\xe3o de Prata entenderam o perigo, a praga j\xe1 tinha se espalhado pelas prov\xedncias do norte de Lordaeron. Senhores do medo da Legi\xe3o Ardente vigiavam a obra do Lich Rei, pois ela deveria abrir caminho para o retorno de seus mestres."]},"chapter:fall-of-lordaeron":{title:"A queda de Lordaeron",summary:"O pr\xedncipe Arthas perseguiu a praga at\xe9 a origem, empunhou G\xe9lido Lamento e voltou para destruir o pr\xf3prio reino, Quel'Thalas e Dalaran.",when:"A Terceira Guerra, cerca de 20 anos ap\xf3s o Portal Negro",body:["O pr\xedncipe Arthas Menethil, jovem paladino da M\xe3o de Prata, partiu com a feiticeira Jaina Proudmoore para deter a praga. Em Stratholme, descobriu que os gr\xe3os da cidade j\xe1 estavam contaminados e ordenou que os habitantes fossem mortos antes que se erguessem como mortos-vivos. Uther e Jaina se recusaram a segui-lo. Arthas perseguiu o senhor do medo Mal'Ganis at\xe9 Nort\xfandria, queimou os pr\xf3prios navios para que seus homens n\xe3o pudessem partir e tomou a l\xe2mina r\xfanica G\xe9lido Lamento. A espada roubou sua alma.","Arthas voltou para casa como cavaleiro da morte do Lich Rei e assassinou o pai, o rei Terenas, na pr\xf3pria sala do trono. O Flagelo varreu Lordaeron. Uther tombou defendendo a urna com as cinzas de Terenas, e Arthas levou seu ex\xe9rcito a Quel'Thalas, rompeu as defesas dos elfos e usou a Nascente do Sol para reerguer Kel'Thuzad como lich. Sylvanas Correventos, general patrulheira de Luaprata, morreu lutando contra ele e foi erguida como banshee.","Kel'Thuzad ent\xe3o invocou o lorde dem\xf4nio Archimonde em Dalaran, e a Legi\xe3o Ardente voltou a Azeroth. Dalaran foi esmagada, e Lordaeron, o maior reino humano, deixou de existir. No norte restaram apenas sobreviventes dispersos, refugiados e fan\xe1ticos, enquanto os mortos-vivos de Arthas dominavam a terra."]},"chapter:battle-for-mount-hyjal":{title:"A batalha pelo Monte Hyjal",summary:"Avisados por um profeta, orcs e humanos navegaram at\xe9 Kalimdor, onde se uniram aos elfos noturnos para deter Archimonde diante da \xc1rvore do Mundo.",when:"O fim da Terceira Guerra",body:["Um profeta misterioso, Medivh retornado da morte, insistiu para que Thrall e Jaina navegassem para o oeste, at\xe9 Kalimdor. A Horda de Thrall desembarcou em suas costas, fez amizade com os taurens de Cairne Casco Sangrento e abriu caminho pelos Sert\xf5es, e Jaina levou refugiados de Lordaeron ao mesmo continente. Nas florestas de Vale Gris, Grom Grito Infernal e seu cl\xe3 Brado Guerreiro beberam sangue demon\xedaco outra vez e mataram o semideus Cenarius.","Thrall e Jaina trabalharam juntos pela primeira vez para salvar Grom. Em um duelo final, Grom matou Mannoroth, libertando os orcs da maldi\xe7\xe3o de sangue ao custo da pr\xf3pria vida. Enquanto isso, Tyrande Sussurravento despertou os druidas e libertou Illidan das Barrow Deeps, esperando que seu poder ajudasse. Em vez disso, ele consumiu o Cr\xe2nio de Gul'dan, tornou-se meio dem\xf4nio e foi banido pelo pr\xf3prio irm\xe3o.","Archimonde marchou sobre Nordrassil para drenar seu poder. Elfos noturnos, humanos e orcs defenderam juntos as encostas do Monte Hyjal, ganhando tempo enquanto Malfurion preparava uma armadilha. Quando o dem\xf4nio alcan\xe7ou a \xe1rvore, milhares de fogos-f\xe1tuos o cercaram e o poder de Nordrassil o despeda\xe7ou. O ex\xe9rcito da Legi\xe3o foi destro\xe7ado, mas a \xc1rvore do Mundo ficou gravemente ferida, e os elfos noturnos perderam a imortalidade que ela lhes dera."]},"chapter:rise-of-the-forsaken":{title:"A ascens\xe3o dos Renegados",summary:"Com o Lich Rei enfraquecido, Sylvanas Correventos se libertou com outros mortos-vivos e reivindicou as ru\xednas de Lordaeron como os Renegados.",when:"Logo ap\xf3s a Terceira Guerra",body:["Ap\xf3s a queda de Archimonde, o dom\xednio do Lich Rei come\xe7ou a fraquejar. Illidan, agora a servi\xe7o de Kil'jaeden, atacou o Trono de Gelo, e Arthas correu para o norte para defender seu mestre. Em Lordaeron, os senhores do medo tentaram tomar o Flagelo para si, e no caos muitos mortos-vivos recuperaram a pr\xf3pria vontade.","Sylvanas Correventos foi a primeira. Com suas banshees e outros mortos-vivos livres, e com o senhor do medo Varimathras for\xe7ado a servi-la, derrotou seus rivais e reivindicou a capital arruinada de Lordaeron. Sob ela ficavam as antigas criptas reais e os esgotos, que se tornaram a Cidade Baixa. Seu povo passou a se chamar os Renegados: n\xe3o mais humanos, rejeitados pelos vivos e livres do Lich Rei.","Arthas chegou \xe0 Coroa de Gelo, colocou o elmo do Lich Rei e fundiu-se a ele no Trono de Gelo, depois silenciou atr\xe1s do gelo. Cercados de inimigos, os Renegados se uniram \xe0 Horda de Thrall como aliados desconfiados, enquanto o Flagelo, a Cruzada Escarlate e o que restava da nobreza de Lordaeron disputavam as Terras Pestilentas. A hist\xf3ria de Forever come\xe7a depois da campanha \u201cForsaken Kingdom\u201d de Warcraft III: Reforged, cujos eventos este guia ainda n\xe3o aborda."],unknowns:["O que acontece na campanha \u201cForsaken Kingdom\u201d de Warcraft III: Reforged, que Forever continua, n\xe3o \xe9 descrito nas fontes que este guia usa."]},"chapter:durotar-and-theramore":{title:"Durotar e Theramore",summary:"Thrall fundou Durotar e Orgrimmar, Jaina construiu Theramore, e os dois mantiveram uma paz fr\xe1gil mesmo quando o pai de Jaina chegou para fazer guerra.",when:"Os anos ap\xf3s a Terceira Guerra",body:["Depois de Hyjal, Thrall levou os orcs a uma terra vermelha e \xe1rida na costa leste de Kalimdor e a chamou de Durotar, em homenagem ao pai. A capital, Orgrimmar, honrava Orgrim Martelo da Perdi\xe7\xe3o. Os taurens de Cairne Casco Sangrento se estabeleceram nos campos de Mulgore, ao redor das mesas do Penhasco do Trov\xe3o, e os trolls Lan\xe7anegra de Vol'jin, que Thrall resgatara em sua viagem para o oeste, fizeram seu lar nas Ilhas do Eco, ao largo da costa de Durotar.","Jaina Proudmoore fundou Theramore em uma ilha do P\xe2ntano Vadeoso para os sobreviventes humanos que trouxera de Lordaeron. Ela e Thrall haviam lutado lado a lado em Hyjal e concordaram em manter a paz. Essa paz foi posta \xe0 prova quando o pai dela, o gr\xe3o-almirante Daelin Proudmoore de Kul Tiras, chegou com sua frota, decidido a destruir os orcs.","Daelin atacou a costa de Durotar. Rexxar, um andarilho meio-ogro dos Mok'Nathal que se tornou o campe\xe3o da Horda, uniu orcs, trolls e taurens contra ele, e Jaina, dividida entre seu povo e seu pai, permitiu que a Horda atacasse as tropas dele em Theramore. Daelin morreu na batalha. Jaina o pranteou, mas manteve sua palavra, e a tr\xe9gua fr\xe1gil entre Theramore e Orgrimmar tornou-se uma das poucas pontes entre a Alian\xe7a e a Horda."]},"chapter:stormwind-in-shadow":{title:"Ventobravo nas sombras",summary:"A reconstru\xedda Ventobravo enfrenta uma guilda de pedreiros tra\xedda, um rei desaparecido e um drag\xe3o escondido na corte, enquanto os gnomos perderam sua cidade.",when:"Ano 25 ap\xf3s o Portal Negro",body:["Depois da Segunda Guerra, a Guilda dos Pedreiros, liderada por Edwin VanCleef, reconstruiu a cidade de Ventobravo a partir das cinzas. Quando o trabalho terminou, a C\xe2mara dos Nobres se recusou a pag\xe1-los. Os pedreiros se revoltaram, foram expulsos e se tornaram a Irmandade D\xe9fias, que agora ataca o Cerro Oeste a partir de minas escondidas e conspira contra a coroa.","O rei Varian Wrynn, o menino que Lothar um dia salvou, desapareceu a caminho de uma reuni\xe3o diplom\xe1tica em Theramore; dizem os boatos que os D\xe9fias o capturaram e o mant\xeam na Ilha de Alcaz. Seu jovem filho Anduin foi coroado, com o Gr\xe3o-lorde Bolvar Fordragon como regente. Na corte, uma nobre graciosa, Lady Katrana Prestor, ganhou grande influ\xeancia. Na verdade, ela era Onyxia, filha de Asa da Morte, conduzindo o reino em sil\xeancio rumo \xe0 ru\xedna.","A Alian\xe7a mudou. Lordaeron est\xe1 perdida, e os elfos noturnos se juntaram \xe0 Alian\xe7a depois de Hyjal. Em Dun Morogh, troggs brotaram das profundezas e invadiram Gnomeregan; a tentativa desesperada dos gnomos de expuls\xe1-los com radia\xe7\xe3o envenenou a pr\xf3pria cidade, e o Gr\xe3o-faz-tudo Mekkatorque levou os sobreviventes a se abrigar em Altaforja. L\xe1 reina o rei Magni Barbabronze, cuja Liga dos Exploradores escava o mundo inteiro em busca dos segredos dos tit\xe3s."]},"chapter:fire-beneath-blackrock":{title:"Fogo sob a Rocha Negra",summary:"Na Montanha Rocha Negra, os an\xf5es Ferro Negro servem Ragnaros enquanto os orcs de Nefarian ocupam o pico acima, e Onyxia guarda sua ninhada no P\xe2ntano Vadeoso.",when:"Ano 25 ap\xf3s o Portal Negro",body:["Dois s\xe9culos ap\xf3s o erro de Thaurissan, seus descendentes ainda governam sob a Montanha Rocha Negra. O imperador Dagran Thaurissan mant\xe9m sua corte em Shadowforge, a cidade dos Ferro Negro nas profundezas do Abismo Rocha Negra, enquanto Ragnaros arde mais abaixo, no N\xfacleo Derretido, e os an\xf5es trabalham para ele. A princesa Moira Barbabronze, filha do rei Magni, chegou \xe0 montanha como prisioneira e ficou como esposa do imperador, para a f\xfaria do pai.","Os sal\xf5es superiores pertencem \xe0 revoada negra. Nefarian, filho de Asa da Morte, governa o Covil Asa Negra sob o disfarce de Lorde Victor Nefarius e comanda os orcs Rocha Negra que nunca se uniram a Thrall, liderados pelo Chefe Guerreiro Rend M\xe3o Negra no Pico da Rocha Negra. Fogo e sombra travam uma guerra fria dentro da mesma montanha, e as Estepes Ardentes e a Garganta Abrasadora sofrem com isso.","A irm\xe3 de Nefarian, Onyxia, a falsa Lady Prestor, mant\xe9m seu covil no P\xe2ntano Vadeoso, onde guarda sua ninhada. Para alcan\xe7\xe1-la \xe9 preciso o Drakefire Amulet, obtido em uma longa s\xe9rie de miss\xf5es de cada fac\xe7\xe3o que passa pelo Pico da Rocha Negra. Em Forever, o Covil da Onyxia \xe9 uma das tr\xeas raides que abrem em 9 de dezembro, ao lado de duas novas raides no Monte Hyjal."]},"chapter:plaguelands-and-the-scarlet-crusade":{title:"As Terras Pestilentas e a Cruzada Escarlate",summary:"O Flagelo de Kel'Thuzad domina o norte, fan\xe1ticos da Cruzada Escarlate combatem mortos-vivos e vivos igualmente, e algumas ordens firmes resistem.",when:"Ano 25 ap\xf3s o Portal Negro",body:["O cora\xe7\xe3o de Lordaeron agora s\xe3o as Terras Pestilentas. Kel'Thuzad comanda o Flagelo ali a partir da necr\xf3pole flutuante de Naxxramas, o Bar\xe3o Rivendare governa os mortos-vivos na arruinada Stratholme, e na antiga escola da fam\xedlia Barov, Scholomance, o Culto dos Malditos treina novos necromantes.","Sobreviventes da M\xe3o de Prata se reagruparam como a Cruzada Escarlate, jurando queimar a praga da terra. Seu Gr\xe3o-cruzado, Saidan Dathrohan, \xe9 secretamente o senhor do medo Balnazzar, e a Cruzada ficou t\xe3o fan\xe1tica que mata qualquer forasteiro que suspeite estar contaminado. Entre suas fortalezas est\xe3o o Monast\xe9rio Escarlate nas Clareiras de Tirisfal, Hearthglen, a M\xe3o de Tyr e um basti\xe3o em Stratholme. At\xe9 seus her\xf3is carregam hist\xf3rias mais sombrias: Renault Mograine traiu o pai, Alexandros, o Ashbringer, e o levou \xe0 morte.","Nem todo paladino se tornou fan\xe1tico. Os que recusaram a crueldade da Cruzada formaram a Aurora Arg\xeantea, que trabalha com qualquer um que lute contra o Flagelo, a partir da Capela Esperan\xe7a da Luz. O paladino exilado Tirion Fordring vive como eremita perto de Hearthglen, e os Renegados avan\xe7am para o norte a partir de Tirisfal. O destino de Lordaeron ainda n\xe3o est\xe1 decidido."]},"chapter:azeroth-in-year-twenty-five":{title:"Azeroth no ano 25",summary:"O mundo do primeiro ano de World of Warcraft, onde se passa a hist\xf3ria de Forever: uma paz fr\xe1gil, velhas amea\xe7as despertando e lugares novos no mapa.",when:"Ano 25: a \xe9poca de Forever",body:["Vinte e cinco anos depois que o Portal Negro se abriu pela primeira vez, Azeroth \xe9 um mundo de sobreviventes. A Alian\xe7a de Ventobravo, Altaforja, dos gnomos e dos elfos noturnos enfrenta uma Horda de orcs, trolls, taurens e Renegados, e nenhum lado confia no outro. Velhos inimigos despertam nas bordas do mapa: servos do Deus Antigo C'Thun em Silithus, sacerdotes do deus do sangue Hakkar nas ru\xednas trolls do sul e a corrup\xe7\xe3o do Pesadelo Esmeralda, que se infiltra nos sonhos dos druidas.","World of Warcraft: Forever se passa exatamente neste momento. A Blizzard o mant\xe9m ali indefinidamente, depois da campanha \u201cForsaken Kingdom\u201d de Warcraft III: Reforged e antes de The Burning Crusade, e afirma que sua hist\xf3ria n\xe3o compartilha a continuidade do World of Warcraft atual. Forever acrescenta lugares que o jogo original nunca teve: as Riverglades, a leste dos Ermos, onde Farholde Keep resiste ao Martelo do Crep\xfasculo; uma Dalaran em restaura\xe7\xe3o cuja barreira de oculta\xe7\xe3o caiu; e masmorras que v\xe3o das tumbas reais do Hall of Thanes \xe0 instala\xe7\xe3o tit\xe2nica de Shaper's Terrace.","Forever tamb\xe9m abre um novo povo aos jogadores: os Skyborne de Zephras Isle, uma ilha que flutua em Skywall, o Plano Elemental do Ar. Seus elementais do ar desapareceram h\xe1 s\xe9culos, e a magia que mant\xe9m a ilha no c\xe9u est\xe1 se esvaindo; sua High Order serve a Alian\xe7a, e seus Windshapers, a Horda. O fim dessas hist\xf3rias ainda est\xe1 sendo escrito. A Blizzard anunciou novas raides, masmorras e uma s\xe9rie de miss\xf5es lend\xe1ria para 2027, e as raides do Monte Hyjal abrem em 9 de dezembro."]},"chapter:after-classic":{title:"Ep\xedlogo: depois de Classic",summary:"Na linha do tempo original, a hist\xf3ria seguiu por Terral\xe9m, Nort\xfandria e al\xe9m; Forever fica no ano 25 e conta a sua pr\xf3pria.",when:"Expans\xf5es posteriores (n\xe3o fazem parte de Forever)",body:["Na linha do tempo original de World of Warcraft, a hist\xf3ria continuou avan\xe7ando. O Portal Negro se reabriu, e The Burning Crusade levou os aventureiros a Terral\xe9m, onde Illidan e Kael'thas Andassol ca\xedram. Em Wrath of the Lich King, a Alian\xe7a e a Horda marcharam sobre Nort\xfandria, e Arthas foi derrotado no alto da Cidadela da Coroa de Gelo. Em Cataclysm, Asa da Morte irrompeu das profundezas e despeda\xe7ou a face do mundo antes que os Aspectos e seus aliados mortais o derrubassem.","As expans\xf5es seguintes levaram a saga a Pand\xe1ria, a um Draenor alternativo, \xe0 derrota final da Legi\xe3o Ardente em Argus, \xe0 guerra aberta entre as fac\xe7\xf5es, aos reinos dos mortos, \xe0s Ilhas do Drag\xe3o e \xe0 longa luta em torno da pr\xf3pria alma-mundo de Azeroth. Muitos lugares deste guia mudaram ao longo do caminho a ponto de ficarem irreconhec\xedveis.","World of Warcraft: Forever n\xe3o segue nenhum desses caminhos. Ele fica no ano 25, em uma \u201cbolha temporal\u201d fora da continuidade do jogo atual, e constr\xf3i seu futuro sobre as bases do mundo original. O roteiro da Blizzard promete para 2027 novas raides, masmorras, miss\xf5es e uma raide ic\xf4nica renovada, de modo que os pr\xf3ximos cap\xedtulos desta hist\xf3ria ser\xe3o s\xf3 de Forever."]}}},1614,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"classes",{enumerable:!0,get:function(){return o}});const o={"class:mage":{title:"Mago",summary:"Herdeiros dos Bem-nascidos e dos primeiros magos humanos, os magos dobram o poder arcano bruto, e cada era da hist\xf3ria gira em torno de um deles.",body:["Os magos manejam o arcano, a magia bruta da ordem que antes brotava da Nascente da Eternidade. Os Bem-nascidos dos elfos noturnos foram os primeiros grandes feiticeiros, e seus descendentes exilados, os altos elfos de Quel'Thalas, ensinaram a arte a cem humanos durante as Guerras Trolls. Esses primeiros magos humanos fundaram depois Dalaran, onde o Kirin Tor ainda guarda os segredos da feiti\xe7aria.","Cada era da hist\xf3ria gira em torno de um mago: Medivh, o \xfaltimo Guardi\xe3o; seu aprendiz Khadgar, que destruiu o Portal Negro; o arquimago Antonidas, que morreu defendendo Dalaran; e Jaina Proudmoore, que hoje governa Theramore. No ano 25, novos alunos treinam no Distrito dos Magos de Ventobravo e no Bairro da Magia da Cidade Baixa, e magos gnomos e trolls h\xe1 muito est\xe3o ao lado de humanos e Renegados. Forever abre esse caminho aos orcs, cujos conjuradores antes s\xf3 conheciam o xamanismo e a magia vil, e \xe0 High Order, os \xfanicos Skyborne que podem se tornar magos."]},"class:warrior":{title:"Guerreiro",summary:"Todo povo de Azeroth tem seus guerreiros, e boa parte da hist\xf3ria do mundo foi escrita com o a\xe7o deles.",body:["Todo povo de Azeroth tem seus guerreiros, e boa parte de sua hist\xf3ria foi escrita com o a\xe7o deles. Os soldados de Arathor defenderam a Muralha de Thoradin contra os Amani; thanes an\xf5es lutaram por Altaforja na Guerra dos Tr\xeas Martelos; os cl\xe3s orcs viviam da for\xe7a de seus campe\xf5es muito antes de a Horda ser forjada. Os guerreiros confiam no treinamento, na armadura e na f\xfaria da batalha, n\xe3o em feiti\xe7os.","Seus her\xf3is enchem as cr\xf4nicas: Anduin Lothar, o Le\xe3o de Azeroth, que liderou a Alian\xe7a at\xe9 tombar no Pico da Rocha Negra; Grom Grito Infernal, cujo sacrif\xedcio no Monte Hyjal libertou os orcs do sangue demon\xedaco; e Danath Trollbane, que ficou em Draenor com a expedi\xe7\xe3o da Alian\xe7a. No ano 25, guerreiros servem sob todas as bandeiras, dos guardas de Ventobravo aos soldados de Orgrimmar, e todas as ra\xe7as jog\xe1veis podem pegar em armas. Forever acrescenta \xe0s suas fileiras os Skyborne das duas ordens."]},"class:paladin":{title:"Paladino",summary:"Guerreiros sagrados nascidos na Segunda Guerra, os paladinos da M\xe3o de Prata foram destro\xe7ados por um dos seus e hoje lutam sob novas bandeiras.",body:["Os paladinos s\xe3o guerreiros-sacerdotes da Luz Sagrada. O arcebispo Alonsus Faol fundou sua ordem, os Cavaleiros da M\xe3o de Prata, durante a Segunda Guerra, para dar \xe0 Alian\xe7a campe\xf5es capazes de curar e tamb\xe9m de lutar. Uther, o Arauto da Luz, foi o primeiro deles, e Turalyon, Tirion Fordring e o pr\xedncipe Arthas Menethil fizeram o juramento.","A ordem foi destro\xe7ada por um dos seus. Arthas assassinou Uther e ajudou a destruir Lordaeron, e os sobreviventes da M\xe3o de Prata se dispersaram: de um lado, os fan\xe1ticos da Cruzada Escarlate; do outro, a Aurora Arg\xeantea e o exilado Tirion. Os an\xf5es de Altaforja tamb\xe9m levam a Luz para a batalha. A mudan\xe7a mais surpreendente de Forever \xe9 que os Renegados agora tamb\xe9m podem ser paladinos, embora as fontes usadas aqui ainda n\xe3o expliquem como mortos-vivos passaram a empunhar a Luz."],unknowns:["As fontes que este guia usa n\xe3o explicam como os paladinos Renegados passaram a empunhar a Luz em Forever."]},"class:hunter":{title:"Ca\xe7ador",summary:"Patrulheiros, fuzileiros e mestres das feras, os ca\xe7adores vivem do arco, da arma de fogo e do v\xednculo com um animal leal.",body:["Os ca\xe7adores vivem do arco, da arma de fogo e do v\xednculo com uma fera. Os patrulheiros de Quel'Thalas, liderados por gera\xe7\xf5es pela fam\xedlia Correventos, guardavam as florestas \xe9lficas; fuzileiros an\xf5es e os cavaleiros de grifo Martelo Feroz lutaram na Segunda Guerra; as Sentinelas elfas noturnas e os ca\xe7adores de cabe\xe7as trolls percorrem as matas de Kalimdor e da Selva do Espinha\xe7o.","Alguns dos sobreviventes mais teimosos da hist\xf3ria s\xe3o ca\xe7adores. Alleria Correventos atravessou o Portal Negro e nunca voltou, sua irm\xe3 Sylvanas lutou contra Arthas at\xe9 o \xfaltimo suspiro, e o mestre das feras Rexxar se tornou o campe\xe3o da Horda contra Daelin Proudmoore. Em Forever, os humanos tamb\xe9m podem seguir esse chamado, e as duas ordens Skyborne contam com ca\xe7adores entre seu povo."]},"class:rogue":{title:"Ladino",summary:"Espi\xf5es, ladr\xf5es e assassinos, os ladinos agem onde a honra hesitaria, e algumas de suas guildas moldaram a hist\xf3ria em sil\xeancio.",body:["Os ladinos agem onde a honra hesitaria. H\xe1 ladr\xf5es, espi\xf5es e assassinos em toda cidade, mas algumas de suas organiza\xe7\xf5es moldam a hist\xf3ria: o servi\xe7o de intelig\xeancia de Ventobravo, o SI:7, comandado por Mathias Shaw; os assassinos de Ravenholdt, escondidos nas Montanhas de Alterac; o Sindicato, nascido da nobreza desonrada de Alterac; e a Irmandade D\xe9fias, que assombra o Cerro Oeste.","A ladina mais famosa das primeiras guerras foi Garona Halforcen, a espi\xe3 meio-orc cuja l\xe2mina matou o rei Llane. No ano 25, instrutores de ladinos ensinam na Cidade Velha de Ventobravo e no Bairro dos Ladinos da Cidade Baixa, e todas as ra\xe7as jog\xe1veis, exceto os taurens, podem aprender o of\xedcio. Forever acrescenta \xe0s sombras os Skyborne das duas ordens."]},"class:priest":{title:"Sacerdote",summary:"Os sacerdotes servem \xe0 Luz Sagrada, \xe0 deusa lunar Eluna ou a poderes mais antigos e sombrios, curando aliados e, quando preciso, aniquilando inimigos.",body:["Os sacerdotes servem \xe0 f\xe9 de muitas formas. A Igreja da Luz Sagrada dos humanos, centrada na Catedral da Luz de Ventobravo e outrora liderada pelo arcebispo Alonsus Faol, ensina que a Luz vive na virtude, e n\xe3o em um \xfanico deus, e os an\xf5es tamb\xe9m a abra\xe7aram. As sacerdotisas elfas noturnas servem \xe0 deusa lunar Eluna em uma irmandade que Tyrande Sussurravento lidera desde a Guerra dos Antigos.","Outros seguem caminhos mais sombrios. Os sacerdotes Renegados mant\xeam uma f\xe9 sombria pr\xf3pria, os sacerdotes trolls honram os loas de seus ancestrais, e a magia das sombras faz parte do of\xedcio de muitos sacerdotes. Em Forever, os gnomos, h\xe1 muito conhecidos como um povo de engenheiros, podem ser sacerdotes pela primeira vez, e a Blizzard lhes deu feiti\xe7os raciais de sacerdote pr\xf3prios."]},"class:shaman":{title:"Xam\xe3",summary:"Os xam\xe3s pedem ajuda aos esp\xedritos da terra, do fogo, da \xe1gua e do ar; perdida para os orcs por uma gera\xe7\xe3o, a tradi\xe7\xe3o foi restaurada por Thrall.",body:["Os xam\xe3s falam com os esp\xedritos da terra, do fogo, da \xe1gua e do ar, e pedem em vez de ordenar. Em Draenor, os xam\xe3s orcs guiavam seu povo at\xe9 que a corrup\xe7\xe3o de Ner'zhul os substituiu por bruxos, e por uma gera\xe7\xe3o os elementos simplesmente deixaram de responder aos orcs. Thrall restaurou a tradi\xe7\xe3o, ensinado por Drek'Thar dos Lobo do Gelo, e reconstruiu a Horda em torno dela.","Os taurens de Mulgore e os trolls Lan\xe7anegra mant\xeam seus pr\xf3prios costumes xam\xe2nicos, e Thrall ainda lidera os xam\xe3s de Orgrimmar. Forever acrescenta dois rec\xe9m-chegados: os an\xf5es, que n\xe3o tinham xam\xe3s no jogo original, e os Skyborne Windshapers de Zephras Isle, cuja ilha flutua em Skywall, o Plano Elemental do Ar."],unknowns:["As fontes que este guia usa n\xe3o explicam como os an\xf5es passaram ao xamanismo em Forever."]},"class:warlock":{title:"Bruxo",summary:"Mestres da magia vil e de dem\xf4nios subjugados, os bruxos chegaram a Azeroth com a Horda e andam numa linha estreita entre o poder e a ru\xedna.",body:["Os bruxos tiram seu poder da magia vil e submetem dem\xf4nios \xe0 sua vontade. A arte chegou a Azeroth com a Horda: Kil'jaeden a ensinou a Gul'dan, cujo Conselho das Sombras transformou os xam\xe3s orcs em bruxos e drenou a vida de Draenor para alimentar seus feiti\xe7os. Os cavaleiros da morte e a maldi\xe7\xe3o do sangue demon\xedaco estiveram entre seus frutos mais sombrios.","Nem todo bruxo serve \xe0 Legi\xe3o. Bruxos humanos se re\xfanem em segredo sob a taverna Slaughtered Lamb, em Ventobravo, gnomos e Renegados estudam a arte, e a Horda de Thrall tolera com desconfian\xe7a seus bruxos orcs. Todo bruxo anda na mesma corda bamba: o poder \xe9 real, e o risco de ser consumido por ele tamb\xe9m. Em Forever, os trolls tamb\xe9m podem se tornar bruxos."]},"class:druid":{title:"Druida",summary:"Guardi\xf5es metamorfos da natureza, ensinados primeiro pelo semideus Cenarius, os druidas mant\xeam o equil\xedbrio do mundo, da Clareira da Lua ao Sonho Esmeralda.",body:["Os druidas guardam o equil\xedbrio da natureza e podem assumir a forma de feras. Malfurion Tempesf\xfaria aprendeu a arte com o semideus Cenarius e se tornou o primeiro druida; seus seguidores dormiram por s\xe9culos no Sonho Esmeralda enquanto as Sentinelas vigiavam as florestas dos elfos noturnos. O C\xedrculo Cenariano, sediado na sagrada Clareira da Lua, hoje re\xfane druidas de todas as ra\xe7as.","Depois da Terceira Guerra, Malfurion ensinou as artes dru\xeddicas aos taurens, e Hamuul Totem R\xfanico se tornou o primeiro druida tauren. No ano 25, os druidas enfrentam preocupa\xe7\xf5es graves: a \xc1rvore do Mundo Nordrassil est\xe1 ferida, Teldrassil cresceu sem a b\xean\xe7\xe3o dos Aspectos e um pesadelo se espalha pelo Sonho Esmeralda. Em Forever, as duas ordens Skyborne contam com druidas entre seu povo."]}}},1615,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"races",{enumerable:!0,get:function(){return o}});const o={"race:human":{title:"Humanos",summary:"Herdeiros de Arathor e a espinha dorsal da Alian\xe7a, os humanos pagaram por todas as guerras da hist\xf3ria de Azeroth e ainda assim reconstroem.",body:["Os humanos descendem das tribos que o rei Thoradin uniu em Arathor quase tr\xeas mil anos antes do Portal Negro. Os herdeiros de Arathor fundaram os sete reinos humanos, os elfos ensinaram seus primeiros magos, e sua f\xe9 na Luz Sagrada deu origem, mais tarde, aos paladinos. A humanidade carregou a Alian\xe7a pela Primeira, Segunda e Terceira Guerras e pagou caro por isso: Ventobravo ardeu uma vez, e Lordaeron caiu diante do Flagelo.","No ano 25, Ventobravo \xe9 o cora\xe7\xe3o do poder humano, reconstru\xedda em pedra branca, mas perturbada pelos D\xe9fias, pelo desaparecimento do rei Varian e por uma corte sob o feiti\xe7o de Lady Prestor. Os novos humanos come\xe7am na Abadia de Vila Norte, na Floresta de Elwynn. Forever permite que humanos se tornem ca\xe7adores, uma voca\xe7\xe3o que o jogo original reservava a outras ra\xe7as."]},"race:gnome":{title:"Gnomos",summary:"Engenhosos inventores cujos ancestrais eram m\xe1quinas forjadas pelos tit\xe3s, os gnomos perderam sua cidade de Gnomeregan e vivem exilados em Altaforja.",body:["Os gnomos s\xe3o pequenos na estatura e enormes na engenhosidade. Seus ancestrais, os mecagnomos, eram m\xe1quinas forjadas pelos tit\xe3s, mais tarde atingidas pela maldi\xe7\xe3o da carne, que as transformou em seres vivos. Em Dun Morogh, constru\xedram Gnomeregan, uma cidade de engrenagens e vapor, e tornaram-se firmes aliados dos an\xf5es da vizinha Altaforja, ao lado de quem lutaram na Segunda Guerra.","Essa cidade est\xe1 perdida. Troggs brotaram das profundezas, e o conselho do Mekgineer Sicco Thermaplugg de inundar Gnomeregan com radia\xe7\xe3o acabou envenenando a cidade; muitos gnomos morreram, e alguns sobreviventes se tornaram gnomos leprosos deformados. O Gr\xe3o-faz-tudo Gelbin Mekkatorque levou os demais para o ex\xedlio em Altaforja, enquanto Thermaplugg governa as ru\xednas. Forever abre o sacerd\xf3cio aos gnomos pela primeira vez."]},"race:night-elf":{title:"Elfos Noturnos",summary:"Os antigos kaldorei vigiaram Kalimdor por dez mil anos; agora mortais, plantaram uma nova \xc1rvore do Mundo e se uniram \xe0 Alian\xe7a.",body:["Os elfos noturnos, ou kaldorei, s\xe3o o mais antigo dos povos jog\xe1veis. Descendentes de trolls transformados pela Nascente da Eternidade, constru\xedram um imp\xe9rio de magia, sobreviveram \xe0 Guerra dos Antigos e passaram dez mil anos como um povo recluso de druidas e Sentinelas \xe0 sombra do Monte Hyjal. A magia arcana continua proibida entre eles.","A Terceira Guerra lhes custou a imortalidade, quando Nordrassil foi ferida para destruir Archimonde. Com Malfurion perdido no Sonho Esmeralda, o arquidruida Fandral Staghelm fez crescer uma nova \xc1rvore do Mundo, Teldrassil, ao largo da Costa Negra, e a capital Darnassus se ergueu em seus galhos. Sob o comando de Tyrande Sussurravento, os elfos noturnos se uniram \xe0 Alian\xe7a. Os novos elfos noturnos come\xe7am entre as clareiras de Teldrassil."]},"race:dwarf":{title:"An\xf5es",summary:"Filhos dos terranos dos tit\xe3s, os an\xf5es de Altaforja s\xe3o aliados teimosos, exploradores incans\xe1veis e guardi\xf5es de uma heran\xe7a dividida.",body:["Os an\xf5es s\xe3o teimosos, calorosos e nascidos da pedra: seus ancestrais eram os terranos, guardi\xf5es forjados pelos tit\xe3s e transformados pela maldi\xe7\xe3o da carne. Altaforja, escavada numa montanha de Dun Morogh, \xe9 sua capital h\xe1 eras. A Guerra dos Tr\xeas Martelos dividiu os cl\xe3s: os Barbabronze ficaram com a cidade, os Martelo Feroz se estabeleceram nas Terras Agrestes e os Ferro Negro ca\xedram a servi\xe7o de Ragnaros.","Sob o rei Magni Barbabronze, os an\xf5es lutaram em todas as guerras da Alian\xe7a, e a Liga dos Exploradores, na qual seu irm\xe3o Brann \xe9 uma figura de destaque, escava ru\xednas tit\xe2nicas como Uldaman em busca da origem dos an\xf5es. Moira, filha de Magni, tornou-se esposa do imperador dos Ferro Negro, uma ferida que o rei leva para o lado pessoal. Forever acrescenta o Hall of Thanes sob Altaforja, o lugar de descanso dos monarcas an\xf5es, agora invadido por intrusos que se acredita serem Ferro Negro, e os an\xf5es podem seguir o caminho do xam\xe3."]},"race:skyborne-high-order":{title:"Skyborne: High Order",body:["Os Skyborne s\xe3o o novo povo jog\xe1vel de World of Warcraft: Forever, e a High Order \xe9 o ramo que est\xe1 ao lado da Alian\xe7a. Seu lar \xe9 Zephras Isle, uma ilha que flutua em Skywall, o Plano Elemental do Ar; ela \xe9 governada pela Gr\xe3-anci\xe3 Talaanis Shadowsong, e seu principal povoado \xe9 a cidade de Valanaar. Os elementais do ar que antes viviam na ilha com os Skyborne desapareceram h\xe1 s\xe9culos, a magia que a sustenta est\xe1 se esvaindo, e o contato com as ilhas irm\xe3s de Anvilas e Siroccas se perdeu enquanto refugiados fogem para Zephras.","Os aventureiros da High Order deixam a ilha de aeronave, de Valanaar at\xe9 Dalaran, nas Montanhas de Alterac. Podem ser guerreiros, ca\xe7adores, ladinos, druidas ou magos, e s\xe3o os \xfanicos Skyborne que estudam o arcano. Seus dons refletem seu lar: descem planando ao vento, agem com acelera\xe7\xe3o ampliada, golpeiam elementais com mais for\xe7a e leem as linhas de Ley pr\xf3ximas para recuperar vida e mana. Para jogar com eles, \xe9 preciso o Skyborne Heroic ou Epic Pack, opcional."]},"race:skyborne-windshaper":{title:"Skyborne: Windshapers",body:["Os Windshapers s\xe3o os Skyborne que est\xe3o ao lado da Horda. Como a High Order, eles v\xeam de Zephras Isle, em Skywall, o Plano Elemental do Ar, uma ilha cujos elementais do ar desapareceram h\xe1 s\xe9culos e cuja magia de sustenta\xe7\xe3o est\xe1 falhando aos poucos. \xc0 medida que ilhas como Anvilas e Siroccas silenciam, refugiados se amontoam em Zephras, e at\xe9 Zephras come\xe7ou a se desfazer.","Os Windshapers deixam Valanaar de aeronave rumo ao Skywatcher Plateau, em Mulgore. Podem ser guerreiros, ca\xe7adores, ladinos, druidas ou xam\xe3s, e s\xe3o os \xfanicos Skyborne que seguem o caminho do xam\xe3. Planam ao vento, lutam com acelera\xe7\xe3o ampliada e golpeiam elementais com mais for\xe7a, e seu pr\xf3prio dom, Skysight, acelera suas viagens e dura muito mais perto de uma converg\xeancia elemental. Como a High Order, exigem o Skyborne Heroic ou Epic Pack, opcional."]},"race:orc":{title:"Orcs",summary:"Antes escravizados pelo sangue demon\xedaco, os orcs foram libertados por Thrall e agora reconstroem sua honra na terra vermelha de Durotar.",body:["Os orcs chegaram a Azeroth vindos de Draenor como a Horda, movidos pelo sangue demon\xedaco e pelos bruxos de Gul'dan. Derrotados na Segunda Guerra, definharam em campos de interna\xe7\xe3o at\xe9 que Thrall, filho do chefe Lobo do Gelo Durotan, os libertou e restaurou os costumes xam\xe2nicos de seus ancestrais.","Ap\xf3s a Terceira Guerra, Thrall levou seu povo a Kalimdor e fundou Durotar e sua capital, Orgrimmar, de onde o Chefe Guerreiro hoje governa uma Horda compartilhada com os taurens, os trolls Lan\xe7anegra e os Renegados. Os orcs s\xe3o orgulhosos, diretos e ferozmente leais, mas seu passado sangrento persiste nos cultistas da L\xe2mina Ardente em Durotar e no cl\xe3 Rocha Negra, que nunca se uniu a Thrall. Os novos orcs come\xe7am no Vale das Prova\xe7\xf5es. Em Forever, os orcs tamb\xe9m podem ser magos."]},"race:tauren":{title:"Taurens",summary:"Gigantes gentis das plan\xedcies que honram a M\xe3e Terra, os taurens encontraram um lar em Mulgore e se uniram \xe0 Horda por gratid\xe3o.",body:["Os taurens s\xe3o n\xf4mades pac\xedficos e imponentes que honram a M\xe3e Terra e percorrem as plan\xedcies de Kalimdor h\xe1 eras. Nos anos da Terceira Guerra, eram acossados pelos centauros, at\xe9 que a Horda de Thrall, rec\xe9m-chegada, ajudou o povo de Cairne Casco Sangrento a alcan\xe7ar a seguran\xe7a de Mulgore.","Cairne uniu muitas tribos dispersas e fundou o Penhasco do Trov\xe3o sobre grandes mesas acima dos campos de Mulgore, e os taurens se uniram \xe0 Horda por gratid\xe3o e respeito. Seus druidas aprenderam com o pr\xf3prio Malfurion Tempesf\xfaria, e seus xam\xe3s e ca\xe7adores mant\xeam vivas antigas tradi\xe7\xf5es. Tribos rivais como os Grimtotem, que se ressentem da alian\xe7a com os orcs, continuam sendo uma preocupa\xe7\xe3o constante. Os jovens taurens come\xe7am no Acampamento Narache, em Mulgore."]},"race:troll":{title:"Trolls",summary:"Herdeiros de imp\xe9rios ca\xeddos, a maioria dos trolls ainda odeia as outras ra\xe7as; j\xe1 a tribo Lan\xe7anegra jurou lealdade a Thrall e \xe0 Horda.",body:["Os trolls j\xe1 governaram vastos imp\xe9rios: os Gurubashi nas selvas do sul, os Amani nas florestas do norte e os Zandalari, que se dizem os primeiros de todos os trolls. As guerras contra os elfos noturnos, os altos elfos e os humanos destro\xe7aram esses imp\xe9rios, e a maioria das tribos ainda alimenta velhos \xf3dios e reza aos loas, os deuses espirituais de seus ancestrais.","A tribo Lan\xe7anegra \xe9 diferente. Expulsos da Selva do Espinha\xe7o por tribos rivais, os Lan\xe7anegra lutavam por sua ilha natal quando a frota de Thrall, castigada pela tempestade, chegou; seu chefe Sen'jin morreu ali, e seu filho Vol'jin jurou a tribo \xe0 Horda. Eles se estabeleceram nas Ilhas do Eco, ao largo de Durotar, mas a magia sombria do mandingueiro Zalazane os empurrou para a Vila Sen'jin, no continente. Em Forever, os Darkspear Raiders tamb\xe9m disputam as Darkspear Islands, ao largo do P\xe2ntano Vadeoso, e os trolls podem ser bruxos."]},"race:undead":{title:"Mortos-vivos",summary:"V\xedtimas da praga reerguidas que se libertaram do Lich Rei, os Renegados governam a Cidade Baixa sob as ru\xednas de Lordaeron e n\xe3o confiam em ningu\xe9m.",body:["Os Renegados eram cidad\xe3os de Lordaeron, mortos pela praga e erguidos pelo Flagelo, que recuperaram o livre-arb\xedtrio quando o poder do Lich Rei fraquejou. Liderados pela rainha banshee Sylvanas Correventos, eles reivindicaram as ru\xednas da capital de Lordaeron e fizeram da Cidade Baixa, sob elas, seu lar. Suas terras, as Clareiras de Tirisfal e a Floresta de Pinhaprata, s\xe3o disputadas pelo Flagelo e pela Cruzada Escarlate.","Os Renegados se uniram \xe0 Horda como aliados por necessidade; poucos vivos confiam neles, e o trabalho secreto da Real Sociedade de Botic\xe1rios em uma nova praga d\xe1 a seus parceiros bons motivos para isso. Os novos Renegados se erguem em Deathknell, nas Clareiras de Tirisfal. Forever acrescenta a masmorra Ruins of Lordaeron, onde os Renegados trabalham para retomar a cidade despeda\xe7ada acima da Cidade Baixa, e permite paladinos Renegados, uma combina\xe7\xe3o que as fontes usadas aqui ainda n\xe3o explicam."],unknowns:["As fontes que este guia usa n\xe3o explicam como surgiram os paladinos Renegados em Forever."]}}},1616,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones1",{enumerable:!0,get:function(){return o}});const o={"zone:dun-morogh":{title:"Dun Morogh",summary:"Vales nevados em torno de Altaforja, lar dos an\xf5es e dos gnomos que perderam sua cidade.",body:["Cercada pelos picos de Khaz Modan, Dun Morogh \xe9 uma terra de campos de neve, lagos congelados e torres de vigia an\xe3s. Seu cora\xe7\xe3o \xe9 Altaforja, a cidade da montanha do cl\xe3 Barbabronze sob o rei Magni, enquanto jovens an\xf5es e gnomos pegam em armas pela primeira vez no abrigado vale de Coldridge e em torno da vila cervejeira de Kharanos. Trolls Frostmane e troggs escavadores atormentam os vales.","A oeste fica Gnomeregan, a maravilha da engenharia gn\xf4mica, perdida quando os troggs brotaram das profundezas e a desesperada enxurrada de radia\xe7\xe3o lan\xe7ada pelos defensores envenenou a cidade. Seus sobreviventes vivem agora como h\xf3spedes em Altaforja. Em Forever, as tumbas reais do Hall of Thanes, sob a cidade, foram arrombadas, e h\xe1 suspeita de invasores Ferro Negro."]},"zone:durotar":{title:"Durotar",summary:"A \xe1spera costa vermelha que Thrall batizou em homenagem ao pai e onde os orcs constru\xedram Orgrimmar.",body:["Quando Thrall levou a Horda a Kalimdor, reivindicou esta faixa de costa leste rachada pelo sol e a chamou de Durotar, em homenagem ao pai, Durotan. Sua terra vermelha e seus c\xe2nions pedregosos lembravam Draenor aos orcs. Eles expulsaram os javatuscos da regi\xe3o e ergueram Orgrimmar, batizada em honra de Orgrim Martelo da Perdi\xe7\xe3o, numa depress\xe3o montanhosa ao norte.","Jovens orcs e trolls provam seu valor no Vale das Prova\xe7\xf5es antes de seguir para Monte Navalha. Na costa, os trolls Lan\xe7anegra ocupam a Vila Sen'jin desde que o mandingueiro Zalazane escravizou os seus nas Ilhas do Eco, e soldados kul tirenses resistem na Bastilha Tiragarde. Cultistas da L\xe2mina Ardente espreitam nas colinas, e seu culto irm\xe3o, a Searing Blade, esconde-se nas Cavernas \xcdgneas, sob a capital."]},"zone:elwynn-forest":{title:"Floresta de Elwynn",summary:"O verde cora\xe7\xe3o do reino de Ventobravo, onde muitos her\xf3is humanos d\xe3o os primeiros passos.",body:["A Floresta de Elwynn \xe9 o cora\xe7\xe3o tranquilo do reino de Ventobravo: bosques de carvalho, fazendas e lagos em torno das muralhas brancas da cidade de Ventobravo, reconstru\xedda depois que a Horda a arrasou na Primeira Guerra. Os novi\xe7os treinam na Abadia de Vila Norte, e os viajantes descansam na Estalagem Orgulho do Le\xe3o, em Vila d'Ouro.","A paz \xe9 mais fr\xe1gil do que parece. Kobolds tomaram as minas, gnolls Riverpaw atacam as fazendas do oeste, murlocs lotam os lagos e bandidos D\xe9fias se espalham a partir do vizinho Cerro Oeste. Dentro da pr\xf3pria capital, o C\xe1rcere caiu nas m\xe3os de um motim de prisioneiros D\xe9fias."]},"zone:mulgore":{title:"Mulgore",summary:"As plan\xedcies varridas pelo vento dos taurens, coroadas pelas mesas do Penhasco do Trov\xe3o.",body:["Mulgore \xe9 a pradaria ancestral dos taurens, uma bacia verde de plan\xedcies e mesas cercada por montanhas, com uma \xfanica passagem a leste, para os Sert\xf5es. Por gera\xe7\xf5es, os taurens n\xf4mades foram acossados por centauros, at\xe9 que a Horda de Thrall ajudou o Gr\xe3o-chefe Cairne Casco Sangrento a levar seu povo para casa. Ali ergueram seus primeiros povoados duradouros: a Aldeia Casco Sangrento e a capital, o Penhasco do Trov\xe3o, constru\xedda no alto de mesas imponentes ligadas por pontes de corda.","Os jovens taurens treinam no Acampamento Narache, no Red Cloud Mesa, enquanto gnolls, javatuscos e prospectores da Venture Company perturbam as plan\xedcies. Em Forever, os Skyborne da Horda chegam de aeronave de Zephras Isle ao Skywatcher Plateau."]},"zone:teldrassil":{title:"Teldrassil",summary:"A nova \xc1rvore do Mundo dos elfos noturnos, ao largo da costa norte de Kalimdor, com Darnassus em seus galhos.",body:["Depois que a Terceira Guerra lhes custou a imortalidade, os druidas elfos noturnos fizeram crescer uma nova \xc1rvore do Mundo ao largo da costa norte de Kalimdor. Deram-lhe o nome de Teldrassil, \u201ccoroa da terra\u201d, e constru\xedram Darnassus em seus galhos, uma cidade de templos banhados pelo luar onde a Suma Sacerdotisa Tyrande Sussurravento guia seu povo.","A \xe1rvore foi plantada sem a b\xean\xe7\xe3o dos Aspectos Drag\xf4nicos, e seu crescimento n\xe3o foi limpo. A corrup\xe7\xe3o se infiltrou em sua fauna e tornou selvagens os furbolgs Gnarlpine. Os novi\xe7os elfos noturnos come\xe7am em Shadowglen, e barcos da Vila Rut'theran, junto \xe0s ra\xedzes, ligam a ilha \xe0 Costa Negra."]},"zone:tirisfal-glades":{title:"Clareiras de Tirisfal",summary:"Clareiras sombrias em torno das ru\xednas da capital de Lordaeron, hoje o cora\xe7\xe3o dos Renegados.",body:["As Clareiras de Tirisfal abrigavam a capital de Lordaeron, e o Conselho de Tirisfal, a ordem que escolhia os Guardi\xf5es, tirou seu nome das reuni\xf5es secretas nestas colinas tranquilas. A praga e a queda do reino deixaram a terra sob um c\xe9u verde e doentio. Sob o pal\xe1cio destru\xeddo, os Renegados de Sylvanas Correventos fizeram da Cidade Baixa o seu lar; seus mortos rec\xe9m-erguidos despertam em Deathknell e se re\xfanem no vilarejo de Brill.","Inimigos pressionam de todos os lados: restos do Flagelo assombram as fazendas, e os fan\xe1ticos da Cruzada Escarlate ocupam o Monast\xe9rio Escarlate, a nordeste. Em Forever, os Renegados tentam retomar a cidade despeda\xe7ada acima deles, onde dizem que um necromante re\xfane poder nas Ruins of Lordaeron."]},"zone:zephras-isle":{title:"Zephras Isle",summary:"Uma ilha voadora em Skywall, o Plano Elemental do Ar, e a zona inicial dos Skyborne de Forever.",body:["Zephras Isle \xe9 a zona inicial dos Skyborne, a ra\xe7a jog\xe1vel nova de World of Warcraft: Forever, desbloqueada com o Skyborne Heroic ou Epic Pack opcional. A ilha flutua em Skywall, o Plano Elemental do Ar, onde os Skyborne a dividiam com elementais do ar. Esses elementais desapareceram h\xe1 v\xe1rios s\xe9culos, e a magia que mant\xe9m a ilha no c\xe9u vem enfraquecendo desde ent\xe3o. Com eles se perdeu o contato com as outras ilhas Skyborne, Anvilas e Siroccas.","Agora essas ilhas est\xe3o desmoronando, refugiados fogem para Zephras, e a pr\xf3pria Zephras come\xe7ou a se partir. A Gr\xe3-anci\xe3 Talaanis Shadowsong governa da cidade de Valanaar, cujas docas a\xe9reas enviam aeronaves a Dalaran, nas Montanhas de Alterac, para a Alian\xe7a, e ao Skywatcher Plateau, em Mulgore, para a Horda."],unknowns:["As fontes que este guia usa n\xe3o explicam por que os elementais do ar desapareceram.","As fontes deste guia ainda n\xe3o tratam da origem profunda dos Skyborne e de suas ordens.","Os antigos governantes da ilha, os Shal\u2019nan, s\xe3o apenas citados, n\xe3o descritos."]},"zone:darkshore":{title:"Costa Negra",summary:"Uma costa nebulosa e cheia de ru\xednas, que os elfos noturnos vigiam a partir do porto de Auberdine.",body:["A Costa Negra \xe9 uma longa faixa da costa noroeste de Kalimdor, escurecida pela chuva e salpicada de ru\xednas em desmoronamento de cidades kaldorei anteriores \xe0 Grande Cis\xe3o. Os elfos noturnos a reivindicam como parte de seu novo reino, e as Sentinelas patrulham a estrada que segue para o sul, do porto de Auberdine at\xe9 Vale Gris.","O perigo espreita fora da estrada: fantasmas vagam pelas velhas ru\xednas, nagas e murlocs rondam as praias, furbolgs se tornam selvagens nas matas, e cultistas do Martelo do Crep\xfasculo e do Dark Strand se escondem nas colinas. Os navios de Auberdine partem para Teldrassil, para o Porto de Menethil e, em Forever, para Ventobravo; uma nova rota de Forever tamb\xe9m chega de Costa Sul."]},"zone:loch-modan":{title:"Loch Modan",summary:"Um vale an\xe3o nas terras altas cujo grande lago \xe9 contido pelo Stonewrought Dam.",body:["A leste de Dun Morogh fica Loch Modan, um vale fresco nas terras altas, de pinheiros e b\xe9tulas, em torno de um grande lago contido pelo Stonewrought Dam, uma das maravilhas da engenharia an\xe3. Poucos se lembram de que um arquiteto Ferro Negro a projetou. O povoado de Thelsamar guarda a estrada, e a Esta\xe7\xe3o Algaz vigia a passagem ao norte, rumo ao Pantanal.","O vale se lembra da Segunda Guerra, quando a Horda o tomou antes que os an\xf5es de Altaforja a fizessem recuar. Hoje o perigo vem de baixo: escava\xe7\xf5es como a de Ironband despertaram troggs das profundezas, ogros Mo'grosh dominam as colinas, e an\xf5es Ferro Negro atacam a pr\xf3pria represa."]},"zone:silverpine-forest":{title:"Floresta de Pinhaprata",summary:"Uma floresta de pinheiros assombrada na costa oeste de Lordaeron, disputada por Renegados, worgens e os \xfaltimos humanos da regi\xe3o.",body:["A Floresta de Pinhaprata acompanha a costa oeste acidentada de Lordaeron, com seus pinheiros de casca prateada agora doentes e envoltos em n\xe9voa. Os Renegados dominam o norte a partir do Sepulcro, enquanto sobreviventes humanos e magos enviados por Dalaran se agarram a Ambermill e ao sul. Mais al\xe9m, Gilneas se isolou atr\xe1s da Muralha de Greymane.","A sombra mais profunda da floresta \xe9 a Bastilha da Presa Negra, antigo castelo do Bar\xe3o Silverlaine. Durante a Terceira Guerra, o arquimago dalarano Arugal invocou worgens para combater o Flagelo, perdeu o controle sobre eles e enlouqueceu; agora chama as feras de seus filhos. Sua maldi\xe7\xe3o alcan\xe7ou a vizinha Pyrewood, cujos moradores se transformam em worgens quando a noite cai."]},"zone:westfall":{title:"Cerro Oeste",summary:"O celeiro abandonado de Ventobravo, hoje territ\xf3rio da Irmandade D\xe9fias.",body:["O Cerro Oeste foi um dia o celeiro de Ventobravo, uma costa de campos dourados e moinhos de vento. Desde a Segunda Guerra, grande parte dele est\xe1 abandonada, e o reino n\xe3o teve dinheiro nem soldados de sobra. A Irmandade D\xe9fias ocupou esse vazio: os pedreiros que reconstru\xedram Ventobravo e se tornaram fora da lei depois que os nobres se recusaram a pag\xe1-los, liderados por Edwin VanCleef.","Os D\xe9fias dominam o vilarejo em ru\xednas de Arroio da Lua e escondem um estaleiro nas Minas Mortas, logo abaixo, enquanto gnolls e golens de colheita descontrolados atacam as fazendas que restam. S\xf3 a Mil\xedcia do Povo, reunida por Gryan Stoutmantle no Morro da Sentinela, ainda os enfrenta."]},"zone:barrens":{title:"Sert\xf5es",summary:"Uma vasta savana no cora\xe7\xe3o de Kalimdor, cortada pela Estrada do Ouro e dominada sobretudo pela Horda.",body:["Os Sert\xf5es s\xe3o uma imensa savana de \xe1rvores espinhosas, o\xe1sis e leitos de rio secos no cora\xe7\xe3o de Kalimdor. Cidades dos elfos noturnos existiam aqui antes da Grande Cis\xe3o; hoje a Horda domina a regi\xe3o a partir da Encruzilhada e do Acampamento Taurajo, os goblins da Vila Catraca negociam por mar com Angra do Butim, e soldados da Alian\xe7a vigiam a partir de Northwatch Hold. Em Forever, a Durotar Supply and Logistics negocia a partir de um acampamento a oeste da Encruzilhada.","Centauros Kolkar, javatuscos e harpias atacam viajantes ao longo da Estrada do Ouro. Debaixo da terra h\xe1 tr\xeas antigas feridas: a Caverna Ululante, onde o sonho de um druida virou pesadelo, e as tocas espinhosas de Razorfen Kraul e Razorfen Downs, sagradas para os javatuscos."]},"zone:redridge-mountains":{title:"Montanhas Cristarrubra",summary:"Colinas vermelhas e um lago tranquilo a leste de Elwynn, onde Vila Pl\xe1cida resiste a gnolls e orcs Rocha Negra.",body:["A leste de Elwynn erguem-se as Montanhas Cristarrubra, uma terra de pedra vermelha, olmos altos e rios agitados que envia madeira, peixe e gr\xe3os a Ventobravo. Seu povoado principal, Vila Pl\xe1cida, fica \xe0s margens do Lake Everstill, e a encruzilhada de Three Corners o liga a Elwynn e \xe0 Floresta do Crep\xfasculo.","A paz aqui \xe9 fr\xe1gil. Os gnolls de Cristarrubra atacam as fazendas, e orcs Rocha Negra vindos das Estepes Ardentes tomaram Stonewatch Keep e acampam no Render's Valley. H\xe1 muito tempo, os an\xf5es Ferro Negro constru\xedram um reino nestas montanhas, at\xe9 que a invoca\xe7\xe3o de Ragnaros por Thaurissan queimou as terras ao norte. Em Forever, a Azeroth Commerce Authority negocia em Three Corners, e passagens levam a leste, \xe0s Riverglades."]},"zone:stonetalon-mountains":{title:"Stonetalon Mountains",summary:"Picos acidentados a oeste dos Sert\xf5es, sagrados para elfos noturnos e taurens e marcados pelo desmatamento dos goblins.",body:["As Stonetalon Mountains se erguem a oeste dos Sert\xf5es, lar ancestral das harpias, embora seus bandos tenham se espalhado muito al\xe9m dali. O pico mais alto, o Stonetalon Peak, \xe9 sagrado tanto para os elfos noturnos quanto para os taurens; os elfos noturnos mant\xeam um t\xfamulo e uma clareira perto do cume, os taurens ocupam o Sun Rock Retreat nas alturas centrais, e os trolls Lan\xe7anegra acampam em Malaka'jin.","Quem mais prejudicou a regi\xe3o foi a Venture Company: seus goblins devastaram quase todas as \xe1rvores do Windshear Crag, sufocando o ar com fuligem e sujando a \xe1gua com \xf3leo. Taurens Grimtotem, kobolds e as feras perigosas do Charred Vale n\xe3o tornam as estradas mais seguras."]},"zone:ashenvale":{title:"Vale Gris",summary:"A floresta ancestral dos elfos noturnos, onde come\xe7ou a guerra com a Horda por sua madeira.",body:["Vale Gris \xe9 a floresta ancestral dos elfos noturnos, uma mata profunda de sombras violeta e \xe1rvores antiqu\xedssimas que se estende do Zoram Strand at\xe9 as fronteiras dos Sert\xf5es. Os kaldorei ocupam Astranaar e uma s\xe9rie de postos avan\xe7ados, e as Sentinelas guardam seus bosques com ferocidade.","Durante a Terceira Guerra, os orcs Brado Guerreiro de Grom Grito Infernal avan\xe7aram sobre estas matas, beberam de novo o sangue demon\xedaco e mataram o semideus Cenarius; Grom morreu depois ao matar o senhor do abismo Mannoroth, no lugar hoje chamado Demon Fall Canyon. Os orcs ainda derrubam \xe1rvores no leste a partir do Splintertree Post e dos acampamentos Brado Guerreiro, e a velha rixa continua acesa. S\xe1tiros assombram as ru\xednas, e na costa ficam as Profundezas Negras, um templo de Eluna submerso."]},"zone:duskwood":{title:"Floresta do Crep\xfasculo",summary:"Um canto outrora luminoso de Elwynn engolido por uma noite sem fim, mantido pelos teimosos moradores de Vila Sombria.",body:["A Floresta do Crep\xfasculo era a parte sul da Floresta de Elwynn, lar dos povoados hoje chamados Vila Sombria e Raven Hill. Ent\xe3o caiu uma sombra que nunca se dissipou, ligada ao destino da foice de Eluna dos elfos noturnos. Sob o crep\xfasculo sem fim, as \xe1rvores ficaram retorcidas, e worgens, mortos-vivos e ogros vindos da Trilha do Vento Morto passaram a rondar.","Ventobravo praticamente deixou a regi\xe3o \xe0 pr\xf3pria sorte. A Vig\xedlia Noturna de Vila Sombria guarda a estrada principal, o cemit\xe9rio de Raven Hill se enche de mortos inquietos, e no fundo da floresta o Twilight Grove abriga uma grande \xe1rvore e um portal para o Sonho Esmeralda."]},"zone:wetlands":{title:"Pantanal",summary:"Brejos cinzentos e encharcados de chuva que guardam a estrada entre Khaz Modan e Lordaeron.",body:["O Pantanal \xe9 um brejo frio e coberto de n\xe9voa entre as montanhas de Khaz Modan e o mar. Fortalezas an\xe3s ocupavam a regi\xe3o no passado; a guerra destruiu a maioria delas. O Porto de Menethil \xe9 aqui a \xe2ncora da Alian\xe7a, um porto cujos navios seguem para Theramore e, em Forever, at\xe9 Costa Sul. Os viajantes chegam pela sitiada Dun Algaz ou pela danificada Ponte Thandol.","A leste ergue-se Grim Batol, a cidade amaldi\xe7oada dos Martelo Feroz onde o cl\xe3 Dragonmaw manteve os drag\xf5es vermelhos cativos durante a Segunda Guerra; renegados Dragonmaw ainda vagam pelo brejo, e an\xf5es Ferro Negro ocupam Dun Modr. Em Forever, uma n\xe9voa estranha e clar\xf5es de luz sobre o Whelgar's Excavation Site levam a uma masmorra de construtos dos tit\xe3s."]},"zone:hillsbrad-foothills":{title:"Contraforte de Eira dos Montes",summary:"Colinas verdes onde Costa Sul e a Serraria Tarren se encaram perto das ru\xednas de Durnholde.",body:["As colinas verdes e f\xe9rteis de Eira dos Montes ficam logo ao sul do antigo reino de Alterac. Dois povoados se enfrentam ali: Costa Sul, da Alian\xe7a, no litoral, e o posto dos Renegados na Serraria Tarren, nas colinas, e a rixa entre eles mant\xe9m os campos ensanguentados. Murlocs e o Sindicato agravam a situa\xe7\xe3o.","Numa eleva\xe7\xe3o a leste fica o Forte de Durnholde, antigo quartel-general dos campos de interna\xe7\xe3o dos orcs, onde Lorde Aedelas Blackmoore criou o jovem Thrall como gladiador antes que ele fugisse para libertar seu povo; hoje o Sindicato ocupa suas ru\xednas. Em Forever, as miss\xf5es que abrem o caminho para a City of Dalaran come\xe7am nos dois povoados, e navios atracam em Costa Sul."]},"zone:thousand-needles":{title:"Mil Agulhas",summary:"Um c\xe2nion de agulhas de pedra e salinas, onde taurens, centauros e goblins f\xe3s de corrida dividem um terreno inst\xe1vel.",body:["Mil Agulhas \xe9 um vasto c\xe2nion seco de mesas de pedra imponentes no sul de Kalimdor, alcan\xe7ado a partir dos Sert\xf5es pelo Grande Elevador. Os taurens do Freewind Post vivem no alto das mesas, enquanto os Grimtotem, um cl\xe3 tauren hostil a Cairne Casco Sangrento, ocupam o Darkcloud Pinnacle. Centauros Galak percorrem o fundo do c\xe2nion, e harpias fazem ninhos entre as agulhas.","A leste, o c\xe2nion se abre para os Shimmering Flats, uma salina ofuscante onde engenheiros goblins e gnomos fazem suas m\xe1quinas correr na Mirage Raceway."]},"zone:alterac-mountains":{title:"Montanhas de Alterac",summary:"O reino partido de Alterac e as ru\xednas protegidas de Dalaran, disputados por ogros e pelo Sindicato.",body:["As Montanhas de Alterac foram o reino de Alterac, cujo senhor, Aiden Perenolde, traiu a Alian\xe7a em favor da Horda na Segunda Guerra. O reino foi dissolvido; hoje, ogros Crushridge se instalam nas ru\xednas da cidade de Alterac, e o Sindicato de Aliden Perenolde, herdeiro da casa desonrada, governa Strahnbrad. Os ladinos de Ravenholdt guardam seus pr\xf3prios segredos nas colinas.","\xc0s margens do Lago Lordamere ficam os restos de Dalaran, a cidade dos magos que Archimonde destruiu na Terceira Guerra. O Kirin Tor vem reconstruindo a cidade atr\xe1s de uma barreira m\xe1gica. Em Forever essa barreira caiu e a cidade transborda de caos arcano; \xe9 tamb\xe9m ali que os Skyborne da Alian\xe7a chegam de aeronave vindos de Zephras Isle."]},"zone:arathi-highlands":{title:"Planalto Arathi",summary:"O antigo cora\xe7\xe3o de Arathor, onde Stromgarde jaz em ru\xednas e tr\xeas fac\xe7\xf5es disputam o que restou.",body:["O Planalto Arathi foi o cora\xe7\xe3o de Arathor, o primeiro imp\xe9rio humano, fundado pelo rei Thoradin com capital em Strom. Sua sucessora, Stromgarde, jaz hoje em grande parte em ru\xednas no sudoeste, onde os defensores do pr\xedncipe Galen Trollbane travam uma guerrilha de tr\xeas lados contra o Sindicato e os ogros Boulderfist. A Muralha de Thoradin ainda marca a antiga fronteira a oeste.","A Alian\xe7a se re\xfane em Refuge Pointe. A Horda ocupa Hammerfall, um antigo campo de interna\xe7\xe3o batizado em honra do Chefe Guerreiro Orgrim Martelo da Perdi\xe7\xe3o, que tombou libertando seu povo. Trolls Witherbark assombram as colinas, e a Ponte Thandol liga o planalto ao Pantanal."]},"zone:desolace":{title:"Desola\xe7\xe3o",summary:"Um ermo cinzento coberto de cinzas, cheio de ossos de kodo e de tribos de centauros em guerra.",body:["Desola\xe7\xe3o \xe9 um ermo sombrio de cinza cinzenta, \xe1rvores mortas e cr\xe2nios de kodos antigos, que v\xeam ao Cemit\xe9rio dos Kodos para morrer. As ru\xednas de cidades dos Bem-nascidos, destru\xeddas pela Grande Cis\xe3o, desmoronam por suas colinas, e dem\xf4nios e s\xe1tiros ainda se re\xfanem onde a velha magia persiste.","\xc9 a terra natal dos centauros, nascidos nas cavernas de Maraudon da uni\xe3o de Zaetar, filho de Cenarius, com a princesa da terra Theradras. Suas quatro tribos, os Kolkar, os Gelkis, os Magram e os Maraudine, lutam entre si com a mesma ferocidade com que lutam contra forasteiros. A Alian\xe7a ocupa o Nijel's Point, e a Horda, a Shadowprey Village."]}}},1617,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones2",{enumerable:!0,get:function(){return o}});const o={"zone:stranglethorn-vale":{title:"Selva do Espinha\xe7o",summary:"Uma selva abafada de cidades trolls ca\xeddas, ca\xe7adores, piratas e o porto goblin de Angra do Butim.",body:["A Selva do Espinha\xe7o era o cora\xe7\xe3o dos trolls Gurubashi, cujo imp\xe9rio um dia dominou a selva a partir de Zul'Gurub. Suas cidades de pedra hoje desmoronam sob as trepadeiras, ainda assombradas por trolls da selva, enquanto ogros, nagas e os famosos espinhos estranguladores da regi\xe3o tornam cada trilha perigosa. Ca\xe7adores se re\xfanem na Expedi\xe7\xe3o Nesingwary, a Horda ocupa o Acampamento-base Grom'gol, e rebeldes da Alian\xe7a acampam no norte.","Na ponta sul, os goblins de Angra do Butim administram um porto sem lei ao lado dos piratas dos Blackwater Raiders, e lutadores de todas as ra\xe7as se encontram na velha Arena Gurubashi. Em Forever, antigas ru\xednas trolls emergiram do mar a oeste de Grom'gol: a Drowned City, agora percorrida por trolls e nagas."]},"zone:badlands":{title:"Ermos",summary:"Um deserto rachado de c\xe2nions onde an\xf5es cavam em busca de segredos dos tit\xe3s e a Horda vigia a partir de Kargath.",body:["Os Ermos s\xe3o um deserto rachado e castigado pelo sol, cheio de rochedos e c\xe2nions sinuosos no sul de Khaz Modan. Prospectores de Altaforja vasculham a regi\xe3o atr\xe1s de rel\xedquias dos tit\xe3s, atra\xeddos por Uldaman, uma enorme c\xe2mara enterrada que revelou as primeiras pistas sobre a origem dos an\xf5es como seres de pedra viva. Troggs libertados de um longo sono massacraram a primeira expedi\xe7\xe3o e agora defendem seus sal\xf5es.","An\xf5es Ferro Negro ocupam a Fortaleza Angor, ogros Dustbelcher acampam por todo o ermo, e dracos negros fazem ninhos na Lethlor Ravine. A Horda vigia a partir do posto de Kargath, perto da estrada para a Garganta Abrasadora."]},"zone:dustwallow-marsh":{title:"P\xe2ntano Vadeoso",summary:"Um p\xe2ntano fumegante que esconde Theramore, o covil de Onyxia e a pris\xe3o h\xe1 muito selada da Ilha de Alcaz.",body:["O P\xe2ntano Vadeoso \xe9 um brejo antigo e sempre \xfamido na costa leste de Kalimdor, repleto de crocoliscos, raptores e murlocs. Ao largo de sua costa fica a Ilha Theramore, a cidade-fortaleza que Jaina Proudmoore fundou para os sobreviventes que a seguiram para o oeste; a Horda responde a partir da vila de Brackenwall, na borda do p\xe2ntano. No sul, drag\xf5es negros infestam o Wyrmbog em torno do covil de Onyxia.","H\xe1 muito tempo boatos cercam a Ilha de Alcaz, cuja pris\xe3o teria mantido cativos de alta patente, at\xe9 mesmo o rei Varian Wrynn. Em Forever, suas portas finalmente se abrem e revelam a Irmandade D\xe9fias e nagas em guerra l\xe1 dentro."]},"zone:riverglades":{title:"Riverglades",summary:"Uma terra de rios disputada no sudeste de Khaz Modan, nova em Forever, onde os cavaleiros de Farholde ainda travam uma guerra que Ventobravo deixou para tr\xe1s.",body:["As Riverglades ficam a leste dos Ermos e das Estepes Ardentes e um dia pertenceram ao reino de Ventobravo. Na Primeira Guerra, a Horda saqueou o povoado de Sunnyglade e escravizou seus moradores. Algumas fam\xedlias fugiram e fundaram Windstead, enquanto cavaleiros que libertaram os cativos fundaram Meadowsbrook e depois fortificaram uma ilha costeira com o nome de Farholde. Acreditando que a regi\xe3o estava perdida, Ventobravo voltou-se para outras preocupa\xe7\xf5es.","Perto do fim da Segunda Guerra, ogros do Martelo do Crep\xfasculo e orcs Stormreaver que fugiam da Tumba de Sargeras se refugiaram ali, e anos de ataques terminaram no cerco de Farholde. No ano 25, a Brotherhood of the Horse do Cavaleiro-comandante Demar Brant continua lutando, o Martelo do Crep\xfasculo ocupa as ru\xednas de Sunnyglade, e os ogros Bolder'ok se juntaram \xe0 Horda."],unknowns:["As fontes n\xe3o dizem quem lidera as for\xe7as da Horda em Rog'mar e Bolder'ok.","Que Cho\u2019gall tenha vindo para a regi\xe3o depois da Segunda Guerra \xe9 apenas um boato.","O significado dos c\xe2nticos ouvidos na Krol\u2019dok Stronghold depois do anoitecer continua em aberto."]},"zone:swamp-of-sorrows":{title:"P\xe2ntano das M\xe1goas",summary:"Um brejo salobro onde drag\xf5es verdes guardam o templo submerso de Atal'Hakkar e a Horda ocupa Pedregal.",body:["O P\xe2ntano das M\xe1goas \xe9 um charco estagnado de \xe1rvores-chor\xe3o e \xe1gua salobra no sul dos Reinos do Leste, perto de onde o Portal Negro se abriu pela primeira vez. A Horda aproveitou bem a dist\xe2ncia de Ventobravo: a cidade orc de Pedregal \xe9 sua fortaleza ali. Crocoliscos, feras do p\xe2ntano e um bando de draeneis exilados dividem as \xe1guas turvas.","No cora\xe7\xe3o do p\xe2ntano fica o Templo de Atal'Hakkar, o santu\xe1rio submerso onde sacerdotes Atal'ai tentaram invocar seu deus do sangue, Hakkar. Os drag\xf5es verdes do Aspecto Ysera agora o guardam e avisam que um terror ainda se agita l\xe1 dentro."]},"zone:feralas":{title:"Feralas",summary:"Uma floresta exuberante alimentada pelas chuvas, de \xe1rvores gigantes, ru\xednas tomadas por ogros e a antiga cidade dos Bem-nascidos, Eldre'Thalas.",body:["Feralas \xe9 uma floresta exuberante e encharcada de chuva, de \xe1rvores gigantes, na costa sudoeste de Kalimdor, que j\xe1 fez parte do antigo reino dos elfos noturnos. Sua maior ru\xedna \xe9 Eldre'Thalas, hoje chamada Gl\xe1dio Cruel, onde os Shen'dralar, Bem-nascidos que sobreviveram \xe0 Grande Cis\xe3o, viveram isolados por dez mil anos. Ogros Gordunni tomaram as velhas ru\xednas \xe9lficas e espalharam sua contamina\xe7\xe3o pela regi\xe3o.","As Sentinelas da Feathermoon Stronghold vigiam a costa a partir da Ilha Sardor, enquanto os taurens do Acampamento Mojache ca\xe7am renegados Grimtotem para a Horda. Nagas dominam as ilhas do oeste, colmeias de silit\xeddeos surgiram, e drag\xf5es verdes guardam o Dream Bough, um portal para o Sonho Esmeralda."]},"zone:hinterlands":{title:"Terras Agrestes",summary:"Colinas selvagens do norte, de cavaleiros de grifo e trolls da floresta, lar dos an\xf5es Martelo Feroz em Aerie Peak.",body:["As Terras Agrestes s\xe3o um planalto acidentado e florestado no norte de Lordaeron. Depois da Guerra dos Tr\xeas Martelos, os an\xf5es Martelo Feroz abandonaram a amaldi\xe7oada Grim Batol e se estabeleceram aqui, em Aerie Peak, onde domam os grifos selvagens da regi\xe3o e continuam firmes aliados da Alian\xe7a. Alguns altos elfos ainda mant\xeam a Quel'Danil Lodge.","As colinas pertencem igualmente aos trolls da floresta. A tribo Revantusk ficou do lado da Horda de Thrall, enquanto os Vilebranch governam a grande cidade-templo de Jintha'Alor e os Witherbark espreitam em torno de Shadra'Alor. No norte, a \xe1rvore ancestral Seradane guarda um portal para o Sonho Esmeralda, vigiado por drag\xf5es verdes."]},"zone:tanaris":{title:"Tanaris",summary:"Um mar de dunas governado a partir de Gadgetzan, que esconde as Cavernas do Tempo e a cidade troll de Zul'Farrak.",body:["Tanaris \xe9 um deserto sem fim de dunas e tempestades de areia no sudeste de Kalimdor. Os goblins do Steamwheedle Cartel o administram a partir de Gadgetzan e do Steamwheedle Port, mantendo uma neutralidade fr\xe1gil enquanto bandidos Wastewander, piratas dos Mares do Sul e ogros Dunemaul atacam os viajantes.","O deserto esconde poderes mais antigos. Nas Cavernas do Tempo, a revoada bronze de Nozdormu vigia o curso da hist\xf3ria; bem ao sul ficam as ru\xednas tit\xe2nicas de Uldum; e os trolls da areia de Zul'Farrak guardam sua cidade murada no noroeste. Em Forever, um navio do Steamwheedle Port liga o deserto a Powderfuse Port, nas Riverglades."]},"zone:searing-gorge":{title:"Garganta Abrasadora",summary:"Um fosso calcinado de minas Ferro Negro e trabalho escravo, enegrecido pela invoca\xe7\xe3o de Ragnaros.",body:["A Garganta Abrasadora \xe9 uma terra enegrecida de cinzas e rocha derretida no sul de Khaz Modan. Ela deve suas cicatrizes \xe0 mesma cat\xe1strofe que queimou as Estepes Ardentes: a invoca\xe7\xe3o de Ragnaros pelo thane feiticeiro Thaurissan, que p\xf4s fim \xe0 Guerra dos Tr\xeas Martelos. Hoje os an\xf5es Ferro Negro a dominam e obrigam escravos a extrair min\xe9rio na grande fenda do Caldeir\xe3o.","Nem todo Ferro Negro serve ao Senhor do Fogo. A Irmandade do T\xf3rio, mestres ferreiros que romperam com seu cl\xe3, negocia com forasteiros a partir do Ponto do T\xf3rio. Ao sul se ergue a Montanha Rocha Negra, com o imp\xe9rio Ferro Negro em suas profundezas e o pico, acima, nas m\xe3os de orcs e drag\xf5es negros."]},"zone:azshara":{title:"Azshara",summary:"Uma costa de outono eterno acima das ru\xednas submersas da capital da rainha Azshara.",body:["Azshara \xe9 uma costa despeda\xe7ada de outono eterno no nordeste de Kalimdor, com \xe1rvores ardendo em vermelho e dourado. Ali ficava Zin-Azshari, a maior cidade dos antigos elfos noturnos, at\xe9 que a Grande Cis\xe3o lan\xe7ou a maior parte dela ao mar. Terra\xe7os em ru\xednas ainda se agarram aos penhascos, assombrados por esp\xedritos inquietos dos Bem-nascidos; nagas e s\xe1tiros rondam a costa, e a Alian\xe7a, em Talrendis Point, e a Horda, em Valormok, mant\xeam pequenos acampamentos.","Em Forever, um port\xe3o de Azshara selado h\xe1 muito tempo se abre para Blackmaw Hold, uma grande cidade furbolg cujo cl\xe3 combate uma corrup\xe7\xe3o que se espalha por seus bosques e t\xfaneis. Suas profundezas se ligam \xe0s Barrow Deeps e descem ainda mais."]},"zone:blasted-lands":{title:"Barreira do Inferno",summary:"Um deserto vermelho e arruinado em torno do silencioso Portal Negro, vigiado pelos magos e paladinos da Fortaleza de Nethergarde.",body:["A Barreira do Inferno fazia parte do Lama\xe7al Negro, at\xe9 que a magia que abriu o Portal Negro a deformou num deserto vermelho de argila rachada. O grande portal pelo qual a Horda invadiu pela primeira vez ainda est\xe1 aqui, com sua moldura de pedra escura e silenciosa desde a destrui\xe7\xe3o. A Fortaleza de Nethergarde, uma fortifica\xe7\xe3o de Ventobravo com magos e paladinos, vigia o portal.","Pouca coisa vive no ermo queimado al\xe9m de escorpi\xf5es, basiliscos, ogros Dreadmaul e alguns draeneis exilados. Dem\xf4nios tamb\xe9m permanecem: o senhor da ru\xedna Kazzak re\xfane o que resta da Legi\xe3o Ardente na Tainted Scar."]},"zone:felwood":{title:"Selva Maleva",summary:"Uma floresta outrora encantadora envenenada por dem\xf4nios, onde os furbolgs Timbermaw e os druidas lutam contra a podrid\xe3o.",body:["A Selva Maleva j\xe1 foi um para\xedso de riachos e campinas cuidado pelos elfos noturnos. Na Terceira Guerra, a Legi\xe3o Ardente a contaminou com o poder do Cr\xe2nio de Gul'dan, e a terra nunca se recuperou: seus rios correm verdes de veneno, seus anci\xf5es e ents apodrecem onde est\xe3o, e s\xe1tiros, infernais e o Conselho das Sombras de Jaedenar, que adora dem\xf4nios, assombram suas clareiras.","Elfos noturnos na Talonbranch Glade, a Horda no Bloodvenom Post e os druidas do Emerald Sanctuary tentam conter a corrup\xe7\xe3o. No norte, os Timbermaw, uma das \xfaltimas tribos furbolg ainda n\xe3o corrompidas, guardam os t\xfaneis que levam \xe0 Clareira da Lua e a Hib\xe9rnia."]},"zone:un-goro-crater":{title:"Cratera Un'Goro",summary:"Uma cratera de selva primitiva com dinossauros, elementos vivos e pilares silenciosos dos tit\xe3s.",body:["A Cratera Un'Goro \xe9 uma selva primitiva e fumegante afundada entre os desertos do sul de Kalimdor, um mundo \xe0 parte onde demossauros ca\xe7am, elementais surgem das fontes termais e o Fire Plume Ridge fumega no centro. Exploradores se re\xfanem no Ref\xfagio de Marshal para estudar seus cristais vermelhos, azuis, verdes e amarelos e os misteriosos pilares nas cristas da cratera, que parecem obra dos tit\xe3s.","Silit\xeddeos surgiram no sul, espalhando-se a partir do vizinho Silithus. Em Forever, uma antiga instala\xe7\xe3o dos tit\xe3s bem acima da cratera, Shaper's Terrace, se abre para aventureiros que trazem cristais de poder coletados por toda Un'Goro."]},"zone:burning-steppes":{title:"Estepes Ardentes",summary:"Planaltos sufocados pelas cinzas sob a Montanha Rocha Negra, dominados por orcs Rocha Negra, ogros Fire-Gut e drag\xf5es negros.",body:["As Estepes Ardentes s\xe3o um planalto arruinado de cinzas, lava e pedra fumegante, queimado quando a invoca\xe7\xe3o de Ragnaros por Thaurissan p\xf4s fim \xe0 Guerra dos Tr\xeas Martelos; as ru\xednas da antiga cidade Ferro Negro de Thaurissan ainda est\xe3o de p\xe9 ali. As estepes formam a \xfanica rota terrestre entre Ventobravo e Khaz Modan, mas o reino praticamente as abandonou.","Acima delas se ergue a Montanha Rocha Negra. O Pico da Rocha Negra, a grande fortaleza da Horda na Segunda Guerra, \xe9 dominado por orcs Rocha Negra e drag\xf5es negros sob o comando de Nefarian, enquanto os an\xf5es Ferro Negro governam as profundezas. Ogros Fire-Gut percorrem as plan\xedcies, e s\xf3 resistem o posto da Alian\xe7a na Vig\xedlia de Morgan e o acampamento da Horda em Flame Crest."]},"zone:western-plaguelands":{title:"Terras Pestilentas Ocidentais",summary:"As lavouras devastadas de Lordaeron, onde o Flagelo ocupa Andorhal e a tumba de Uther \xe9 o \xfaltimo solo sagrado.",body:["As Terras Pestilentas Ocidentais j\xe1 estiveram entre as lavouras mais ricas de Lordaeron; hoje uma n\xe9voa cinzenta paira sobre campos doentes e mortos-vivos vagam por fazendas abandonadas. A cidade em ru\xednas de Andorhal, onde o culto de Kel'Thuzad espalhou seus gr\xe3os empestados, \xe9 ali o maior basti\xe3o do Flagelo, e caldeir\xf5es de praga envenenam os campos ao redor. Numa ilha do Lago Darrowmere, Caer Darrow, a fortaleza da fam\xedlia Barov, esconde Scholomance, uma escola de necromancia.","A Cruzada Escarlate luta a partir de Hearthglen, no norte, a Alian\xe7a a partir do Chillwind Camp, e os Renegados ocupam o Baluarte, na fronteira com Tirisfal. A Tumba de Uther, lugar de descanso do Arauto da Luz, \xe9 o \xfanico lugar consagrado de paz."]},"zone:eastern-plaguelands":{title:"Terras Pestilentas Orientais",summary:"O canto mais devastado da Lordaeron ca\xedda, governado pelo Flagelo a partir da cidade queimada de Stratholme.",body:["As Terras Pestilentas Orientais s\xe3o o resto mais devastado do reino de Lordaeron: terra marrom e doente, \xe1rvores inchadas at\xe9 virar fungos gigantes e um ar carregado de n\xe9voa alaranjada. No centro fica Stratholme, a cidade cujos moradores o pr\xedncipe Arthas passou ao fio da espada na Terceira Guerra, hoje dividida entre o Flagelo e a Cruzada Escarlate.","O principal ex\xe9rcito da Cruzada ocupa a M\xe3o de Tyr e combate os mortos-vivos com muito zelo e pouco sucesso, enquanto a Aurora Arg\xeantea acolhe na Capela Esperan\xe7a da Luz qualquer um disposto a ajudar. Cidades-fantasma como Darrowshire e Corin's Crossing marcam batalhas perdidas, e trolls Amani atacam a partir de Zul'Mashar, no norte, para retomar suas terras ancestrais."]},"zone:winterspring":{title:"Hib\xe9rnia",summary:"Um vale nevado nas encostas de Hyjal, dividido entre comerciantes goblins, sabres-do-gelo, drag\xf5es azuis e dem\xf4nios.",body:["Hib\xe9rnia \xe9 um vale de neve quase eterna nas encostas do Monte Hyjal, onde os elfos noturnos come\xe7aram a reconstruir depois da Grande Cis\xe3o. A cidade goblin de Everlook negocia com qualquer um, os elfos noturnos ainda mant\xeam a vila de Starfall, e os treinadores da Frostsaber Rock criam os felinos brancos do vale. Drag\xf5es azuis fazem covil nas cavernas de Mazthoril.","O sul do vale caiu nas m\xe3os de dem\xf4nios na Darkwhisper Gorge, e os furbolgs Winterfall se tornaram selvagens. Em Forever, uma das entradas da raide Barrow Deeps \xe9 alcan\xe7ada passando por Hib\xe9rnia."]},"zone:deadwind-pass":{title:"Trilha do Vento Morto",summary:"Uma passagem morta e a\xe7oitada pelo vento, dominada por Karazhan, a torre do \xfaltimo Guardi\xe3o, Medivh.",body:["A Trilha do Vento Morto \xe9 um c\xe2nion escarpado de \xe1rvores petrificadas e sem folhas entre a Floresta do Crep\xfasculo e o P\xe2ntano das M\xe1goas, por onde um vento lamentoso nunca para de soprar. No centro ergue-se Karazhan, a torre de marfim de Medivh, o \xfaltimo Guardi\xe3o de Tirisfal, cuja possess\xe3o por Sargeras abriu caminho para a Horda. Embora Medivh esteja morto h\xe1 muito tempo, sua torre ainda vaza magia sombria pela regi\xe3o.","Ogros do Vento Morto, dem\xf4nios e esp\xedritos inquietos vagam pela passagem, os t\xfamulos de Morgan's Plot n\xe3o t\xeam descanso, e viajantes sussurram que um novo poder tomou a torre. A maioria atravessa \xe0s pressas."]},"zone:moonglade":{title:"Clareira da Lua",summary:"Um santu\xe1rio dru\xeddico pac\xedfico no norte de Kalimdor, lar do C\xedrculo Cenariano.",body:["A Clareira da Lua \xe9 um vale escondido no norte de Kalimdor, sagrado para os druidas h\xe1 milhares de anos. Malfurion Tempesf\xfaria reuniu druidas ali para fundar o C\xedrculo Cenariano, e o reflexo do vale no Sonho Esmeralda \xe9 o lugar mais sagrado daquele reino. Na cidade de Nighthaven, o guardi\xe3o Remulos, filho de Cenarius, zela pela ordem.","Desde a Terceira Guerra, o C\xedrculo abriu a Clareira da Lua a todos que seguem o caminho dru\xeddico, e taurens e elfos noturnos agora dividem suas margens em paz. Os guardi\xf5es da Clareira da Lua n\xe3o toleram viol\xeancia no santu\xe1rio, e todo ano Nighthaven celebra o Festival da Lua."]},"zone:silithus":{title:"Silithus",summary:"Um deserto castigado pelo sol, cheio de colmeias de insetos, no sudoeste de Kalimdor, onde o C\xedrculo Cenariano vigia os port\xf5es selados de Ahn'Qiraj.",body:["Silithus \xe9 um deserto escaldante no extremo sudoeste de Kalimdor, interrompido apenas pelas colmeias gigantescas dos silit\xeddeos. Desde a Guerra das Areias Movedi\xe7as, os qiraji insetoides est\xe3o selados atr\xe1s da Muralha do Escaravelho erguida pelas revoadas, mas seus enxames de silit\xeddeos continuam se multiplicando.","O C\xedrculo Cenariano vigia a amea\xe7a a partir do Forte Cenariano, enquanto cultistas do Martelo do Crep\xfasculo se re\xfanem em acampamentos pelas dunas com prop\xf3sitos pr\xf3prios. Atr\xe1s da muralha, o templo-fortaleza de Ahn'Qiraj aguarda."]}}},1618,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances1",{enumerable:!0,get:function(){return o}});const o={"instance:hall-of-thanes":{title:"Hall of Thanes",summary:"A cripta real de Altaforja, invadida por intrusos que os an\xf5es suspeitam ser Ferro Negro.",body:["Sob Altaforja fica o Hall of Thanes, onde os an\xf5es sepultam seus monarcas e cuidam dos t\xfamulos com zelo. Sua entrada fica no limiar do High Seat, no cora\xe7\xe3o da cidade: um passeio para a Alian\xe7a, uma invas\xe3o ousada para qualquer grupo da Horda. Agora, intrusos abriram caminho \xe0 for\xe7a at\xe9 os t\xfamulos sagrados. Os an\xf5es suspeitam do cl\xe3 Ferro Negro, e a pedra antiga est\xe1 repleta de sussurros fantasmag\xf3ricos.","A maioria das miss\xf5es \xe9 para a Alian\xe7a e come\xe7a em Kharanos ou nos arredores de Altaforja, embora uma das miss\xf5es l\xe1 dentro seja oferecida por um fantasma neutro. Quatro inimigos barram o caminho: Faldrim Anvilmar, Magmatus, Plunder e Durgen Dirgehammer."],unknowns:["Quem os intrusos realmente s\xe3o; o texto oficial diz apenas que os an\xf5es suspeitam do cl\xe3 Ferro Negro.","O que despertou nos sal\xf5es e a hist\xf3ria por tr\xe1s de cada um dos quatro inimigos."]},"instance:ragefire-chasm":{title:"Cavernas \xcdgneas",summary:"Cavernas vulc\xe2nicas sob Orgrimmar, onde troggs e um culto a servi\xe7o dos dem\xf4nios amea\xe7am a nova capital da Horda.",body:["Um labirinto de cavernas iluminadas pela lava se estende sob Orgrimmar, e a Horda descobriu que sua nova capital n\xe3o tem sossego. Troggs conhecidos como os \xcdgneos subiram dos t\xfaneis profundos, e quando a anci\xe3 tauren Magatha Grimtotem tentou fazer as pazes com eles, encontrou apenas viol\xeancia.","Pior ainda, uma seita chamada Searing Blade, leal ao demon\xedaco Conselho das Sombras, escondeu-se nas cavernas para conspirar contra tudo o que o povo de Thrall construiu. Ela \xe9 liderada por Taragaman the Hungerer, um guarda vil, tendo ao seu lado o bruxo Jergosh the Invoker e o s\xe1tiro Bazzalan. Para muitos jovens her\xf3is da Horda, essas cavernas s\xe3o a primeira masmorra."]},"instance:ruins-of-lordaeron":{title:"Ruins of Lordaeron",summary:"A capital arruinada acima da Cidade Baixa, onde os Renegados retomam seu passado enquanto um necromante re\xfane poder.",body:["Os Renegados est\xe3o tentando retomar a capital arruinada acima de sua Cidade Baixa. Os escombros ainda guardam rel\xedquias de fam\xedlia e lembran\xe7as queridas, mas o Flagelo assombra as ruas destro\xe7adas, e h\xe1 rumores de que um necromante re\xfane poder dentro das muralhas. Aventureiros s\xe3o convocados para ajudar a tornar a cidade segura.","Os grupos da Horda chegam facilmente \xe0 entrada a partir da Cidade Baixa, enquanto os da Alian\xe7a precisam se aventurar em terras da Horda. As duas fac\xe7\xf5es encontram miss\xf5es: as da Horda come\xe7am na Cidade Baixa, na Floresta de Pinhaprata e em Tirisfal; as da Alian\xe7a, dentro das pr\xf3prias ru\xednas. O caminho passa por Witherfang, The Baron, Viktor the Vile, The Abandoned e Bjork at\xe9 o \xfaltimo inimigo, Rath'mael."],unknowns:["Quem \xe9 o necromante e para que serve o poder que ele re\xfane.","Quanto da antiga capital os Renegados pretendem reconstruir."]},"instance:deadmines":{title:"Minas Mortas",summary:"A mina de ouro abandonada do Cerro Oeste, onde a Irmandade D\xe9fias de Edwin VanCleef constr\xf3i em segredo um navio de guerra.",body:["Antes da Primeira Guerra, estes t\xfaneis eram as minas de ouro mais ricas das terras humanas; o saque de Ventobravo pelos orcs as deixou vazias. Agora a Irmandade D\xe9fias fez delas sua fortaleza escondida. Seu l\xedder, Edwin VanCleef, era um mestre pedreiro que ajudou a reconstruir Ventobravo depois da guerra, at\xe9 que os nobres da cidade se recusaram a pagar sua guilda. Tra\xeddos, seus trabalhadores se tornaram foras da lei e se espalharam pelo Cerro Oeste.","O caminho de entrada come\xe7a no vilarejo arruinado de Arroio da Lua. L\xe1 embaixo, goblins como Sneed e Gilnid ajudam os D\xe9fias a terminar um grande navio em uma enseada escondida, guardada por Mr. Smite e pelo Captain Greenskin."]},"instance:wailing-caverns":{title:"Caverna Ululante",summary:"Cavernas sob os Sert\xf5es, onde o sonho de renova\xe7\xe3o do druida Naralex virou um pesadelo.",body:["A Caverna Ululante deve seu nome ao gemido do vento e do vapor que passam pelas fendas da rocha. O druida elfo noturno Naralex a descobriu e esperava ligar suas nascentes subterr\xe2neas ao Sonho Esmeralda, para que a vida verde voltasse a se espalhar pelos Sert\xf5es secos. Mas, enquanto ele meditava, foi o Pesadelo Esmeralda que o dominou.","Preso no sono, Naralex agora derrama essa corrup\xe7\xe3o nas cavernas. Suas criaturas se deformaram em feras aberrantes, e a maioria de seus disc\xedpulos enlouqueceu e se tornou os Druids of the Fang, entre eles Lady Anacondra e os lordes Cobrahn, Pythas e Serpentis. Despertar Naralex significa enfrentar Mutanus, o Devorador."]},"instance:shadowfang-keep":{title:"Bastilha da Presa Negra",summary:"Uma fortaleza assombrada na Floresta de Pinhaprata, onde o arquimago louco Arugal abriga os worgens que ele mesmo libertou.",body:["O Kirin Tor estava perdendo a luta da Terceira Guerra contra o Flagelo, e cada mago que tombava logo se levantava de novo do lado inimigo. O arquimago Arugal ignorou os avisos de seus colegas e buscou ajuda al\xe9m do mundo, convocando os ferozes worgens. Eles dilaceraram os mortos-vivos, depois as pr\xf3prias fileiras de Dalaran, e tomaram a fortaleza do Bar\xe3o Silverlaine, na colina acima de Pyrewood.","A culpa despeda\xe7ou a mente de Arugal. Agora ele chama os homens-lobo de seus filhos e se esconde com eles na fortaleza, rebatizada de Presa Negra e guardada pelo grande lobo Fenrus. O fantasma do bar\xe3o nunca partiu, e os Renegados de Pinhaprata querem o arquimago morto."]},"instance:excavation-site-wetlands":{title:"Excavation Site: Wetlands",summary:"Uma escava\xe7\xe3o acima do Whelgar's Excavation Site abriu um lugar intocado pelo tempo, guardado por construtos dos tit\xe3s perdidos.",body:["Algo despertou nas colinas do Pantanal, perto de Thelgen Rock e Dun Algaz. A n\xe9voa desce pelas encostas acima do Whelgar's Excavation Site, e luzes tremeluzem no horizonte. Al\xe9m da escava\xe7\xe3o, a terra parece intocada pela passagem das eras; m\xe1quinas dos tit\xe3s perdidas e uma fauna feroz guardam segredos que a Liga dos Exploradores est\xe1 ansiosa para revelar.","As miss\xf5es da Alian\xe7a come\xe7am no Porto de Menethil, em Greenwarden's Grove e em Vila Pl\xe1cida; as da Horda, em Orgrimmar e Hammerfall. Saltspine e Shadetooth bloqueiam o caminho at\xe9 o Relic Guardian, cuja derrota rende uma rel\xedquia dos tit\xe3s que inicia uma miss\xe3o para as duas fac\xe7\xf5es."],unknowns:["O que despertou al\xe9m da escava\xe7\xe3o e o que causa a n\xe9voa e as luzes.","Quem construiu o lugar e para que serve a rel\xedquia dos tit\xe3s."]},"instance:stormwind-stockade":{title:"O C\xe1rcere",summary:"A pris\xe3o de Ventobravo, tomada pelos pr\xf3prios detentos em um motim liderado pelos D\xe9fias.",body:["O C\xe1rcere fica no cora\xe7\xe3o da Cidade de Ventobravo e abriga ladr\xf5es, assassinos e presos pol\xedticos. Pouco tempo atr\xe1s, os detentos se rebelaram, revelaram sua lealdade \xe0 Irmandade D\xe9fias e expulsaram os guardas; agora s\xe3o eles que comandam os blocos de celas.","O cabe\xe7a do motim \xe9 Bazil Thredd, um agente D\xe9fias. Entre os prisioneiros est\xe3o o orc Rocha Negra Targorr the Dread, o an\xe3o Ferro Negro Kam Deepfury e o ladr\xe3o de t\xfamulos Dextren Ward. V\xe1rios foram condenados \xe0 morte, mas a burocracia da nobreza vivia adiando as senten\xe7as, e por isso Vila Pl\xe1cida, Vila Sombria e at\xe9 Altaforja enviam discretamente aventureiros para resolver a quest\xe3o."]},"instance:city-of-dalaran":{title:"City of Dalaran",summary:"A cidade do Kirin Tor nas Montanhas de Alterac, onde a barreira que escondia sua restaura\xe7\xe3o caiu e a magia est\xe1 fora de controle.",body:["Por um tempo, uma barreira m\xe1gica escondeu os trabalhos de restaura\xe7\xe3o de Dalaran. Agora esse escudo caiu, e a cidade est\xe1 exposta em pleno caos arcano: feiti\xe7os falham, construtos andam soltos e magia bruta se derrama pelas ruas. O Kirin Tor precisa de ajuda, mas s\xf3 de gente em quem confia.","Os her\xf3is da Alian\xe7a conquistam essa confian\xe7a come\xe7ando com Emissary Jacques, em Costa Sul; os da Horda come\xe7am com Magus Wordeen Voidglare, na Serraria Tarren. Os dois caminhos levam a uma imagem da arquimaga Modera na margem sul do Lago Lordamere, que entrega a Dalaran Sewer Key. A partir dos esgotos, os grupos escolhem a pr\xf3pria rota pela cidade at\xe9 a origem do problema; o \xfaltimo inimigo \xe9 o Shade of the Archmage."],unknowns:["O que causou o tumulto e de quem \xe9 a sombra que \xe9 o \xfaltimo inimigo.","At\xe9 onde avan\xe7ou a restaura\xe7\xe3o de Dalaran."]},"instance:blackfathom-deeps":{title:"Profundezas Negras",summary:"Um templo submerso de Eluna na costa do Vale Gris, hoje um santu\xe1rio onde cultistas cuidam de uma fera dos Deuses Antigos.",body:["Um po\xe7o cercado de escadas no Zoram Strand, no Vale Gris, desce at\xe9 sal\xf5es inundados que um dia formaram um templo de Eluna, a deusa da lua dos elfos noturnos. A Grande Cis\xe3o partiu o santu\xe1rio e o arrastou para o fundo do mar, onde ele dormiu por eras at\xe9 que nagas e s\xe1tiros, famintos pelo poder que ainda persiste ali, vieram explor\xe1-lo.","Hoje o culto do Martelo do Crep\xfasculo adora nas piscinas mais profundas sob o comando de Twilight Lord Kelris, cuidando de Aku'mai, uma fera monstruosa estimada pelos Deuses Antigos. Xam\xe3s da Harmonia Tel\xfarica vieram det\xea-los, sabendo que qualquer chamado aos Deuses Antigos p\xf5e o mundo inteiro em perigo."]},"instance:razorfen-kraul":{title:"Razorfen Kraul",summary:"A toca ancestral dos javatuscos, nascida dos espinhos que brotaram do sangue de um semideus tombado.",body:["Os javatuscos veneram Agamaggan, o grande semideus javali morto na Guerra dos Antigos. Onde seu sangue caiu, trepadeiras gigantes cheias de espinhos irromperam da terra, e o maior emaranhado delas, no extremo sul dos Sert\xf5es, \xe9 o Razorfen, o lugar que os javatuscos honram como seu t\xfamulo.","Razorfen Kraul \xe9 o lar ancestral deles, um labirinto de tocas e t\xfaneis cobertos de espinheiros governado por Charlga Razorflank, a Velha. Sacerdotes da tribo Death's Head j\xe1 percorrem suas passagens, e batedores relatam mortos-vivos se reunindo na regi\xe3o, temendo que o Flagelo tenha voltado os olhos para Kalimdor."]},"instance:gnomeregan":{title:"Gnomeregan",summary:"A capital perdida dos gnomos em Dun Morogh, envenenada por um expurgo radioativo ap\xf3s uma invas\xe3o de troggs e o conselho de um traidor.",body:["Constru\xedda nas profundezas das montanhas de Dun Morogh, Gnomeregan era a maior maravilha da engenharia gn\xf4mica. Ent\xe3o os troggs irromperam das profundezas e a invadiram. O Gr\xe3o-faz-tudo Mekkatorque seguiu o conselho de seu conselheiro, Sicco Thermaplugg, e inundou a cidade de radia\xe7\xe3o para matar os invasores, mas o expurgo matou tamb\xe9m a maioria dos gnomos. Os sobreviventes fugiram para Altaforja.","Foi uma trai\xe7\xe3o. Thermaplugg ficou para tr\xe1s, coroou-se senhor das ru\xednas e agora comanda gnomos leprosos, troggs e m\xe1quinas enlouquecidas como o Electrocutioner 6000 e o Crowd Pummeler 9-60. Os exilados juraram retomar seu lar."]},"instance:scarlet-monastery-graveyard":{title:"Monast\xe9rio Escarlate: Cemit\xe9rio",summary:"As criptas do monast\xe9rio da Cruzada Escarlate, onde seu interrogador trabalha e os mortos se recusam a descansar.",body:["O monast\xe9rio no norte das Clareiras de Tirisfal foi constru\xeddo como casa de estudos para os sacerdotes de Lordaeron. Depois que o Flagelo varreu o reino na Terceira Guerra, os fan\xe1ticos da Cruzada Escarlate o tomaram e fizeram dele seu basti\xe3o. Eles suspeitam que todo n\xe3o humano carrega a praga e recebem os estranhos com l\xe2minas em vez de perguntas.","O Cemit\xe9rio \xe9 a primeira ala que a maioria dos grupos visita. Suas celas pertencem ao Interrogador Vishas, Bloodmage Thalnos espreita entre os t\xfamulos e mortos inquietos como Azshir the Sleepless, Ironspine e o Campe\xe3o Ca\xeddo rondam as criptas."]},"instance:scarlet-monastery-library":{title:"Monast\xe9rio Escarlate: Biblioteca",summary:"O arquivo da Cruzada Escarlate, onde um mestre dos c\xe3es e um arcanista guardam os livros da ordem.",body:["Os sacerdotes de Lordaeron vinham estudar neste monast\xe9rio de Tirisfal. A Cruzada Escarlate, que o tomou depois da Terceira Guerra, manteve os livros, mas perdeu a brandura: seus fan\xe1ticos acreditam que qualquer n\xe3o humano pode estar espalhando a praga e guardam seu arquivo com a mesma ferocidade com que guardam suas muralhas.","O Mestre dos C\xe3es Loksey e seus c\xe3es ca\xe7am intrusos nos sal\xf5es externos, e o Arcanista Doan vigia as estantes internas. Muitos v\xeam pelos pr\xf3prios livros: estudiosos de Altaforja querem um volume sobre a mitologia dos tit\xe3s, enquanto os Renegados buscam a cr\xf4nica dos mortos mantida pela pr\xf3pria Cruzada."]},"instance:drowned-city":{title:"Drowned City",summary:"Antigas ru\xednas trolls que emergiram do mar diante da Selva do Espinha\xe7o, agora percorridas por trolls e nagas.",body:["Diante da Selva do Espinha\xe7o, a oeste de Grom'gol, uma cidade troll que o mar havia engolido voltou \xe0 tona. Ruas em que ningu\xe9m pisava havia eras agora est\xe3o a c\xe9u aberto, trolls e nagas j\xe1 se instalaram nelas, e um navio pirata ali perto parece ter tido um fim muito ruim.","Para entrar, os grupos mergulham e procuram a passagem abaixo da linha d\u2019\xe1gua. L\xe1 dentro, lutam a c\xe9u aberto enquanto o tempo piora: a n\xe9voa vira chuva, e a chuva vira uma tempestade de verdade na batalha final."],unknowns:["Por que a cidade emergiu agora e que povo troll a construiu.","Quem lidera os trolls e nagas l\xe1 dentro; os dados deste guia ainda n\xe3o listam chefes.","O que aconteceu com o navio pirata."]},"instance:scarlet-monastery-armory":{title:"Monast\xe9rio Escarlate: Armaria",summary:"O campo de treinamento e arsenal da Cruzada Escarlate, comandado por seu campe\xe3o Herod.",body:["Atr\xe1s das muralhas do monast\xe9rio nas Clareiras de Tirisfal, a Cruzada Escarlate treina seus soldados. A ordem nasceu da ru\xedna de Lordaeron na Terceira Guerra e acredita que qualquer um que n\xe3o seja humano pode carregar a praga, por isso seus recrutas aprendem a atacar primeiro.","A Armaria abriga os p\xe1tios de treinamento, os alojamentos e os dep\xf3sitos de armas, e seu senhor \xe9 Herod, o Campe\xe3o Escarlate, um brutamontes enorme que brande um machado gigantesco e gira como um redemoinho entre seus atacantes. Derrot\xe1-lo prova que um grupo est\xe1 pronto para a catedral no cora\xe7\xe3o do monast\xe9rio."]},"instance:razorfen-downs":{title:"Razorfen Downs",summary:"Os antigos cemit\xe9rios dos javatuscos, tomados pelo Flagelo sob o lich Amnennar the Coldbringer.",body:["Razorfen Downs cresce dos mesmos espinhos gigantes que o Kraul e \xe9 onde os javatuscos enterram seus mortos. Seus sumos sacerdotes, os Death's Head, mantinham estes campos sagrados. Isso mudou quando o Flagelo chegou a Kalimdor: o lich Amnennar the Coldbringer tomou os sacerdotes da tribo a seu servi\xe7o e encheu os espinheiros de mortos reerguidos.","Javatuscos livres agora lutam para reconquistar sua cidade funer\xe1ria antes que o poder do lich se espalhe pelo resto dos Sert\xf5es. Um grupo precisa abrir caminho por Tuten'kash, Mordresh Fire Eye, Glutton e Plaguemaw the Rotting para chegar ao pr\xf3prio Amnennar."]},"instance:scarlet-monastery-cathedral":{title:"Monast\xe9rio Escarlate: Catedral",summary:"O cora\xe7\xe3o do Monast\xe9rio Escarlate, onde o Comandante Mograine lidera os fi\xe9is e a Alta-inquisidora Cabelalvo ergue os ca\xeddos.",body:["A catedral \xe9 o cora\xe7\xe3o do monast\xe9rio da Cruzada Escarlate nas Clareiras de Tirisfal e a sede de seus l\xedderes ali. O Comandante Escarlate Mograine comanda a fan\xe1tica guarni\xe7\xe3o, mas a verdadeira autoridade pertence \xe0 Alta-inquisidora Cabelalvo, uma sacerdotisa capaz de trazer de volta seu campe\xe3o ca\xeddo para que lute de novo.","A Cruzada nasceu da queda de Lordaeron e ainda v\xea a praga em cada forasteiro. \xc9 aqui que sua convic\xe7\xe3o arde com mais for\xe7a: o comandante luta at\xe9 o fim e, quando tomba, Cabelalvo deixa o presbit\xe9rio para continuar a luta e ergu\xea-lo outra vez."]}}},1619,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances2",{enumerable:!0,get:function(){return o}});const o={"instance:kroldok-stronghold":{title:"Krol'dok Stronghold",summary:"Uma fortaleza ogra nos Riverglades cujos saqueadores sequestram viajantes e de onde sobem c\xe2nticos depois que escurece.",body:["Krol'dok \xe9 a fortaleza ogra dos Riverglades, e sua hist\xf3ria remonta aos anos depois da Segunda Guerra. Quando as for\xe7as da antiga Horda na regi\xe3o sitiaram Farholde Keep, Fern Crimsonleaf se infiltrou no acampamento delas e matou seus l\xedderes. Sem comando, o ex\xe9rcito, maior, perdeu uma batalha custosa para a Brotherhood of the Horse e fugiu de volta para Krol'dok.","Agora seus batedores ogros atacam por todos os Riverglades, levando viajantes e saqueando povoados. A trilha deles termina em uma fortaleza enorme de oficinas, acampamentos e passagens muito vigiadas. Os grupos entram para acabar com os ataques e descobrir o significado dos estranhos c\xe2nticos que sobem da fortaleza depois que escurece."],unknowns:["Quem comanda a fortaleza hoje; os dados deste guia ainda n\xe3o listam chefes.","O que s\xe3o os c\xe2nticos e quem os conduz.","Qual \xe9 a rela\xe7\xe3o desses ogros com o Martelo do Crep\xfasculo e com os ogros Bolder'ok em outras partes dos Riverglades."]},"instance:uldaman":{title:"Uldaman",summary:"Uma c\xe2mara dos tit\xe3s nos Ermos, onde escavadores an\xf5es despertaram os troggs e encontraram pistas sobre suas pr\xf3prias origens.",body:["Uldaman \xe9 uma c\xe2mara que os guardi\xf5es dos tit\xe3s selaram nas profundezas das montanhas de Khaz Modan, no que hoje s\xe3o os Ermos. Ela devia conter os troggs, uma cria\xe7\xe3o antiga que os tit\xe3s consideraram um fracasso. Antes da Terceira Guerra, escavadores de Altaforja invadiram o lugar, e os troggs que eles despertaram massacraram a maior parte da expedi\xe7\xe3o.","Agora a Liga dos Exploradores, saqueadores Ferro Negro e tribos de troggs disputam seus sal\xf5es. L\xe1 no fundo ficam os Discos de Norgannon, registros dos tit\xe3s que revelam que os an\xf5es descendem dos terranos de pele de pedra, guardados por Archaedas, forjado pelos tit\xe3s, que ainda se ergue contra qualquer um que perturbe sua c\xe2mara."]},"instance:zulfarrak":{title:"Zul'Farrak",summary:"A cidade calcinada pelo sol dos trolls Sandfury em Tanaris, onde um deus hidra dorme em um lago sagrado.",body:["Tanaris j\xe1 foi uma selva que fazia parte das terras dos trolls Gurubashi, e Zul'Farrak era uma de suas cidades. Quando a Grande Cis\xe3o transformou a regi\xe3o em deserto, os trolls Farraki que ficaram ali se adaptaram e se tornaram trolls da areia. Hoje a cidade pertence \xe0 tribo Sandfury, temida por sua crueldade e sua magia sombria.","Os aventureiros v\xeam por muitos motivos. Boatos situam as duas metades da espada troll partida Sul'thraze the Lasher dentro de suas muralhas, um bando de mercen\xe1rios em fuga de Gadgetzan entrou l\xe1 por engano e foi capturado, e em um lago sagrado no cora\xe7\xe3o da cidade dorme Gahz'rilla, uma hidra que os Sandfury veneram como semideus e s\xf3 despertam quando t\xeam sacrif\xedcios a oferecer."]},"instance:alcaz-prison":{title:"Alcaz Prison",summary:"Uma pris\xe3o cercada de boatos h\xe1 muito tempo na Ilha de Alcaz, no P\xe2ntano Vadeoso, finalmente aberta, onde D\xe9fias e nagas est\xe3o em guerra.",body:["O P\xe2ntano Vadeoso h\xe1 muito fervilha de conversas sobre a Ilha de Alcaz e os prisioneiros de alta patente que estariam presos l\xe1; alguns boatos chegam a citar o rei Varian Wrynn de Ventobravo. Ningu\xe9m conseguia chegar \xe0 pris\xe3o para descobrir a verdade. Agora seus port\xf5es est\xe3o abertos.","L\xe1 dentro, a Irmandade D\xe9fias e os nagas lutam entre si. Os grupos aproveitam o caos para vasculhar as celas, enfrentar quem as controla e reunir novas pistas sobre um mist\xe9rio que os reinos j\xe1 conhecem bem."],unknowns:["Se o rei Varian Wrynn est\xe1 ou esteve preso aqui; o texto oficial s\xf3 relata boatos.","Quem comanda a pris\xe3o e por que D\xe9fias e nagas est\xe3o lutando.","Que chefes aguardam l\xe1 dentro; os dados deste guia ainda n\xe3o listam nenhum."]},"instance:maraudon":{title:"Maraudon",summary:"Cavernas sagradas dos centauros em Desola\xe7\xe3o, envenenadas pela dor da princesa da terra Theradras.",body:["A lenda conta uma hist\xf3ria sombria sobre o nascimento dos centauros. O pai deles era Zaetar, filho do semideus Cenarius; a m\xe3e, a princesa Theradras, filha do senhor elemental da terra. Os primeiros centauros se voltaram contra Zaetar e o mataram, e dizem que Theradras, de luto, prendeu o esp\xedrito dele dentro de Maraudon, um ato cuja corrup\xe7\xe3o ainda envenena as cavernas.","Os cl\xe3s centauros consideram Maraudon um cemit\xe9rio sagrado, mas fantasmas inquietos de centauros, elementais distorcidos e criaturas vegetais venenosas agora enchem a Wicked Grotto, a Foulspore Cavern e as Earth Song Falls. Celebras, sobrinho de Zaetar, veio libertar o esp\xedrito do tio e acabou sucumbindo ele mesmo \xe0 corrup\xe7\xe3o. L\xe1 no fundo aguarda Theradras."]},"instance:temple-of-atalhakkar":{title:"Templo de Atal'Hakkar",summary:"O Templo Submerso no P\xe2ntano das M\xe1goas, onde sacerdotes Atal'ai ainda tentam invocar seu deus do sangue, Hakkar.",body:["Os Atal'ai eram sacerdotes trolls que queriam trazer ao mundo Hakkar the Soulflayer, o deus do sangue, e a luta para det\xea-los dilacerou o Imp\xe9rio Gurubashi h\xe1 mais de mil anos. Derrotados e expulsos, eles constru\xedram um templo no P\xe2ntano das M\xe1goas para preparar o retorno dele, at\xe9 que o Aspecto Ysera descobriu o plano e o afundou no lodo.","Desde ent\xe3o, drag\xf5es verdes vigiam as ru\xednas submersas, mas os Atal'ai resistiram e ainda rezam a Hakkar sob o comando de Jammal'an, o Profeta. Mais abaixo persiste a Sombra de Eranikus, consorte de Ysera, com a mente obscurecida pelo Pesadelo Esmeralda."]},"instance:blackrock-depths":{title:"Abismo Rocha Negra",summary:"A Shadowforge City, capital dos an\xf5es Ferro Negro nas profundezas da Montanha Rocha Negra, governada pelo Imperador Dagran Thaurissan \xe0 sombra de Ragnaros.",body:["H\xe1 mais de dois s\xe9culos, o feiticeiro-thane Ferro Negro Thaurissan tentou vencer uma guerra perdida com uma invoca\xe7\xe3o desesperada e, em vez disso, trouxe Ragnaros, o Senhor do Fogo. A explos\xe3o ergueu a Montanha Rocha Negra e prendeu seu cl\xe3 \xe0 vontade do Senhor do Fogo. Seus descendentes ainda trabalham para Ragnaros nos t\xfaneis ardentes sob a montanha.","O Abismo Rocha Negra \xe9 o reino deles: uma pris\xe3o, a arena chamada Ring of Law, a taverna Grim Guzzler, a Forja Negra e a pr\xf3pria Shadowforge City. Ali o Imperador Dagran Thaurissan ocupa seu trono ao lado da princesa Moira Barbabronze, cujo pai, o rei Magni de Altaforja, acredita que ela est\xe1 presa ali por um feiti\xe7o."]},"instance:warpwood-quarter":{title:"Warpwood Quarter",summary:"O distrito leste da arruinada Eldre'Thalas, tomado por plantas corrompidas sob o s\xe1tiro Alzzin the Wildshaper.",body:["O Gl\xe1dio Cruel, em Feralas, j\xe1 foi Eldre'Thalas, uma cidade onde os arcanistas mais reservados da rainha Azshara guardavam seu precioso conhecimento. A Grande Cis\xe3o a deixou em ru\xednas, e com o passar das eras ogros, s\xe1tiros e coisas ainda mais estranhas se instalaram em seus distritos.","O Warpwood Quarter, a leste, caiu nas m\xe3os de Alzzin the Wildshaper, um s\xe1tiro que corrompeu o Fruto da Fertilidade, que agora s\xf3 produz trepadeiras vis. Anci\xf5es retorcidos, a\xe7oitadores, dem\xf4nios e s\xe1tiros lhe obedecem, e o distrito inteiro se tornou selvagem. At\xe9 o diabrete travesso Pusillin leva os intrusos a uma divertida persegui\xe7\xe3o por seus sal\xf5es."]},"instance:blackmaw-hold":{title:"Blackmaw Hold",summary:"Uma grande cidade furbolg atr\xe1s de um port\xe3o selado por muito tempo em Azshara, onde o cl\xe3 Blackmaw combate uma corrup\xe7\xe3o que se espalha.",body:["Atr\xe1s de um port\xe3o em Azshara que ficou fechado por muito, muito tempo, fica uma grande cidade dos furbolgs. O cl\xe3 Blackmaw que vive ali combate uma corrup\xe7\xe3o que se infiltra por seus bosques e ao longo dos t\xfaneis sinuosos sob as montanhas.","A fortaleza \xe9 uma longa aventura para grupos no n\xedvel m\xe1ximo, com v\xe1rias rotas e muitos chefes. Dizem que suas regi\xf5es mais profundas escondem um caminho que leva ainda mais para baixo de Azeroth, e o panorama de raides da Blizzard cita Blackmaw Hold como uma das entradas para os Barrow Deeps."],unknowns:["O que \xe9 a corrup\xe7\xe3o e de onde ela vem.","Quem selou o port\xe3o e por qu\xea.","Que chefes aguardam l\xe1 dentro; os dados deste guia ainda n\xe3o listam nenhum."]},"instance:lower-blackrock-spire":{title:"Pico da Rocha Negra Inferior",summary:"Os sal\xf5es inferiores do pico no alto da Montanha Rocha Negra, quartel da Horda Sombria de Rend M\xe3o Negra.",body:["Durante s\xe9culos, o pico que coroa a Montanha Rocha Negra foi um basti\xe3o Ferro Negro. Isso acabou quando Nefarian, filho de Asa da Morte, tomou seus n\xedveis superiores com sua prole drac\xf4nica e se voltou contra os an\xf5es. Ele encontrou um aliado em Rend M\xe3o Negra, um orc que se diz Chefe Guerreiro de uma Horda Sombria que se recusa a seguir Thrall.","O Pico da Rocha Negra Inferior \xe9 o quartel dessa Horda Sombria. Legi\xf5es de orcs Rocha Negra, ogros Spirestone sob o Gr\xe3o-lorde Omokk, trolls Smolderthorn do Ca\xe7ador das Sombras Vosh'gajin e as aranhas em torno de Mother Smolderweb dividem seus sal\xf5es arruinados sob o Suserano Wyrmthalak. A elite e os drag\xf5es aguardam ainda mais acima, no Pico da Rocha Negra Superior."]},"instance:capital-gardens":{title:"Capital Gardens",summary:"O distrito oeste de Eldre'Thalas, onde os \xfaltimos Bem-nascidos dos Shen'dralar se alimentam de um dem\xf4nio enjaulado.",body:["Eldre'Thalas, hoje chamada Gl\xe1dio Cruel, foi constru\xedda para guardar os segredos arcanos da rainha Azshara, e seus guardi\xf5es, os Shen'dralar, sobreviveram \xe0 Grande Cis\xe3o. Privados do poder da Nascente da Eternidade, seu l\xedder, o pr\xedncipe Tortheldrin, mandou erguer cinco pilares para aprisionar o dem\xf4nio Immol'thar, e seu povo extra\xeda a energia dele para continuar imortal.","Com o passar dos s\xe9culos, a pris\xe3o enfraqueceu. Para manter o pr\xf3prio poder, Tortheldrin se voltou contra os outros Shen'dralar e drenou suas for\xe7as. Os Capital Gardens, antes parque e corte dos Bem-nascidos, abrigam agora seus \xfaltimos seguidores leais, \xe1rvores secas, anci\xf5es furiosos e o pr\xf3prio dem\xf4nio enjaulado."]},"instance:scholomance":{title:"Scholomance",summary:"A escola de necromancia de Kel'Thuzad nas criptas sob Caer Darrow, entregue ao Flagelo pela fam\xedlia Barov.",body:["Numa ilha do Lago Darrowmere, nas Terras Pestilentas Ocidentais, ergue-se Caer Darrow, antes a fortaleza da nobre fam\xedlia Barov. Quando o mago Kel'Thuzad reuniu seguidores para seu Culto dos Malditos, prometeu a imortalidade em nome do Lich Rei, e os Barov lhe entregaram sua fortaleza e as criptas. O culto transformou as criptas em Scholomance, uma escola onde necromantes eram treinados para espalhar a praga.","Os Barov tiveram seu desejo realizado da pior maneira e agora assombram os sal\xf5es como mortos-vivos. O lich Ras Frostwhisper governa a escola para o Flagelo, o Mestre Sombrio Gandling \xe9 seu diretor e o Ravenian espreita l\xe1 embaixo, pronto para devorar os alunos fracos."]},"instance:shapers-terrace":{title:"Shaper's Terrace",summary:"Uma antiga instala\xe7\xe3o dos tit\xe3s nas colinas do norte da Cratera Un'Goro, que funciona com cristais de poder coletados por toda a cratera.",body:["Nas alturas do norte da Cratera Un'Goro, uma antiga instala\xe7\xe3o dos tit\xe3s observa uma terra que o tempo parece ter deixado em paz. Dinossauros, po\xe7os de piche, estruturas dos tit\xe3s e cristais brilhantes fazem parte desta expedi\xe7\xe3o, pensada para grupos perto do n\xedvel m\xe1ximo.","Seu enigma vai al\xe9m das muralhas: os grupos coletam cristais de poder pela cratera e os usam em consoles dentro do terra\xe7o, de modo que o que encontram l\xe1 fora molda os desafios l\xe1 dentro."],unknowns:["Quem construiu o terra\xe7o e para que ele servia.","O que os consoles fazem e que chefes aguardam l\xe1 dentro; os dados deste guia ainda n\xe3o listam nenhum."]},"instance:stratholme":{title:"Stratholme",summary:"A ru\xedna em chamas da grande cidade do norte de Lordaeron, dividida entre o Flagelo do Bar\xe3o Rivendare e a Cruzada Escarlate.",body:["Stratholme era a cidade mais orgulhosa do norte de Lordaeron e o ber\xe7o da Ordem da M\xe3o de Prata. Na Terceira Guerra, o pr\xedncipe Arthas passou seus habitantes ao fio da espada em vez de deixar que, tocados pela praga, se erguessem como mortos-vivos, rompendo com seu mentor Uther. O Flagelo se instalou pouco depois, e a cidade arde desde ent\xe3o.","Hoje dois inimigos a dividem. A Cruzada Escarlate ocupa um lado sob o Gr\xe3o-cruzado Dathrohan, sem suspeitar que ele \xe9, na verdade, o senhor do medo Balnazzar disfar\xe7ado. O outro lado pertence ao Flagelo e ao cavaleiro da morte Bar\xe3o Rivendare, um rico propriet\xe1rio de terras de Stratholme e amigo de Kel'Thuzad antes de se juntar ao Culto dos Malditos."]},"instance:gordok-commons":{title:"Gordok Commons",summary:"O distrito norte do Gl\xe1dio Cruel, sede do rei Gordok e de seus ogros, onde quem mata o rei fica com a coroa.",body:["Ogros do cl\xe3 Gordunni tomaram o bairro norte da antiga Eldre'Thalas, a cidade arruinada dos Bem-nascidos hoje chamada Gl\xe1dio Cruel. Seus guerreiros mais fortes, os Gordok, governam a partir dos Commons, e seu rei adota o nome de Rei Gordok.","O costume ogro aqui \xe9 simples: quem mata o rei se torna o novo Rei Gordok. Grupos espertos passam escondidos pelos guardas Mol'dar, Fengus e Slip'kik, por Stomper Kreeg e pelo Capit\xe3o Kromcrush para atacar apenas o rei, e os ogros que sobrevivem tratam os vencedores como seus novos governantes e lhes pagam tributo. Cho'Rush, o Observador, fica ao lado do rei."]},"instance:barrow-deeps":{title:"Barrow Deeps",summary:"Uma raide de dez jogadores na pris\xe3o sob Kalimdor que manteve Illidan Tempesf\xfaria preso por dez mil anos.",body:["Nas profundezas sob Kalimdor, os Barrow Deeps mantiveram Illidan Tempesf\xfaria cativo por dez mil anos. Agora o caminho para seus t\xfaneis est\xe1 aberto, e raides descem para descobrir o que aconteceu com aqueles que ficaram na escurid\xe3o e o que as guardi\xe3s pretendem fazer contra a amea\xe7a que se agita l\xe1 embaixo.","Tr\xeas caminhos levam para dentro, ligados ao Monte Hyjal, \xe0 Hib\xe9rnia e a Blackmaw Hold. Dez jogadores enfrentam oito chefes na descida, da Deepscar Matriarch e de Khalith the Dreadspinner at\xe9 Del'lynar Songwood e, por \xfaltimo, Sonya Darkhallow."],unknowns:["Quem abriu as passagens e qual \xe9 o perigo l\xe1 embaixo.","Quem s\xe3o as guardi\xe3s e quais s\xe3o as hist\xf3rias dos oito chefes."]},"instance:hyjal-summit":{title:"Hyjal Summit",summary:"Uma raide de vinte jogadores no pico do Monte Hyjal, perto da \xc1rvore do Mundo Nordrassil, com treze chefes e muitos caminhos.",body:["Hyjal Summit fica no alto do Monte Hyjal, perto da \xc1rvore do Mundo Nordrassil. Um guardi\xe3o antigo bloqueia o caminho no in\xedcio; depois disso, as raides escolhem as pr\xf3prias rotas pela montanha, entre ru\xednas na superf\xedcie e abaixo dela, combatendo tudo o que amea\xe7a Hyjal at\xe9 que se abra o caminho para as batalhas finais.","Vinte jogadores enfrentam treze chefes, entre eles Bandalar, o Time-Lost Battalion, o Council of Thorns, o Wild King e o Ancient of Decay. O \xfaltimo de todos \xe9 Nythus the Dreambound."],unknowns:["Que for\xe7a amea\xe7a Hyjal; o panorama oficial n\xe3o a nomeia.","Quem \xe9 o guardi\xe3o antigo e quem \xe9 Nythus the Dreambound."]},"instance:onyxias-lair":{title:"Covil da Onyxia",summary:"O covil de Onyxia, m\xe3e da ninhada da revoada negra, no P\xe2ntano Vadeoso; s\xf3 os portadores do Drakefire Amulet podem entrar.",body:["No Wyrmbog do P\xe2ntano Vadeoso, Onyxia, filha de Asa da Morte e irm\xe3 de Nefarian, guarda sua ninhada numa caverna de fogo. Sua arma mais poderosa \xe9 o engano. Em forma humana, como Lady Katrana Prestor, ela sussurra na corte de Ventobravo e trabalha para jogar os reinos mortais uns contra os outros.","Quarenta jogadores a enfrentam numa batalha de chamas em tr\xeas fases, por isso as raides re\xfanem primeiro resist\xeancia ao fogo. Cada membro tamb\xe9m precisa usar o Drakefire Amulet, conquistado por uma longa s\xe9rie de miss\xf5es: a Alian\xe7a, pela fuga do Marechal Windsor do Abismo Rocha Negra e pelo desmascaramento em Ventobravo; a Horda, por Rexxar e pelo draco Emberstrife. As duas terminam com o General Drakkisath no Pico da Rocha Negra Superior."]}}},1620,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"items",{enumerable:!0,get:function(){return o}});const o={"item:demon-soul":{title:"A Alma Drag\xf4nica (Alma Demon\xedaca)",summary:"Um disco dourado forjado por Neltharion para dominar todos os drag\xf5es; ele deu origem a Asa da Morte e, eras depois, acorrentou a revoada vermelha \xe0 Horda.",body:["Antes da Guerra dos Antigos, o Guardi\xe3o da Terra Neltharion mandou seus servos goblins fabricarem um disco dourado de apar\xeancia simples, secretamente impregnado da corrup\xe7\xe3o dos Deuses Antigos. Ele convenceu os outros Aspectos a despejarem nele parte de seu poder para combater a Legi\xe3o Ardente e depois o voltou contra dem\xf4nios e aliados da mesma forma. As energias da Alma Drag\xf4nica dilaceraram seu corpo, e Neltharion se tornou Asa da Morte.","Depois da Grande Cis\xe3o, os Aspectos esconderam o disco nas profundezas do que hoje s\xe3o as Montanhas Cristarrubra. Seguindo as vis\xf5es de Asa da Morte, o cl\xe3 Dragonmaw o recuperou, rebatizou-o de Alma Demon\xedaca e o usou para escravizar Alexstrasza em Grim Batol. Foi ali que ele finalmente se despeda\xe7ou, e os drag\xf5es vermelhos ficaram livres."]},"item:atiesh":{title:"Atiesh, Greatstaff of the Guardian",summary:"O cajado dos Guardi\xf5es de Tirisfal, levado por \xfaltimo por Medivh, depois despeda\xe7ado e ca\xe7ado por Kel'Thuzad.",body:["Atiesh passou de Guardi\xe3o para Guardi\xe3o por gera\xe7\xf5es, terminando em Medivh, o \xfaltimo deles. As lendas dizem que ele brotou de uma \u201csemente de \xf3dio\u201d e concede poder sem fim a quem o empunha; corvos se re\xfanem ao seu redor, e ele pode abrir um caminho at\xe9 Karazhan. Depois da queda de Medivh, o Kirin Tor trancou o cajado em Dalaran, onde todo mago que o tocou teve um fim terr\xedvel.","Quando Archimonde destruiu Dalaran, Atiesh se partiu em dezenas de peda\xe7os que se espalharam por Azeroth, e Kel'Thuzad decidiu reuni-los. No jogo original, as raides arrancavam os fragmentos de sua necr\xf3pole de Naxxramas, mandavam restaurar a estrutura com a ajuda do drag\xe3o bronze Anachronos e depois precisavam purificar o cajado em Stratholme, derrotando o dem\xf4nio aprisionado dentro dele."]},"item:scepter-of-the-shifting-sands":{title:"O Cetro das Areias Movedi\xe7as",summary:"A chave da Muralha do Escaravelho que selava Ahn'Qiraj, despeda\xe7ada por um Fandral Staghelm tomado pela dor.",body:["Quase mil anos antes da Primeira Guerra, os qiraji insetoides jorraram de Ahn'Qiraj, incitados pelo Deus Antigo C'Thun. O arquidruida Fandral Staghelm liderou os elfos noturnos contra eles, mas seu filho Valstann foi abatido diante de seus olhos, e a guerra virou. S\xf3 com a ajuda de quatro revoadas os enxames foram recha\xe7ados e selados atr\xe1s da Muralha do Escaravelho.","A muralha s\xf3 podia ser aberta golpeando o Gongo do Escaravelho com este cetro. Fandral, na f\xfaria de sua dor, o despeda\xe7ou, e os peda\xe7os se espalharam. No jogo original, aventureiros remontaram o cetro, tocaram o gongo e abriram Ahn'Qiraj mais uma vez."]},"item:doomhammer":{title:"Martelo da Perdi\xe7\xe3o",summary:"O martelo de guerra herdado da linhagem Martelo da Perdi\xe7\xe3o, que Orgrim carregou por duas guerras e entregou a Thrall.",body:["Forjado h\xe1 muito tempo em Draenor, o grande martelo de pedra negra passava de pai para filho dentro de uma \xfanica fam\xedlia orc, e sobre ele pairava uma antiga profecia Rocha Negra: o \xfaltimo da linhagem traria aos orcs primeiro a salva\xe7\xe3o e depois a ru\xedna, antes que um estranho erguesse o martelo pela justi\xe7a. Orgrim Martelo da Perdi\xe7\xe3o o empunhou na Primeira e na Segunda Guerra e com ele abateu Anduin Lothar, despeda\xe7ando a l\xe2mina r\xfanica do cavaleiro.","Depois da derrota da Horda, Orgrim escapou do cativeiro e lutou para libertar seu povo dos campos de interna\xe7\xe3o. Mortalmente ferido em uma dessas batalhas, ele deu o martelo a Thrall, que n\xe3o era nem de seu cl\xe3 nem de seu sangue. Thrall o carregou como s\xedmbolo de uma Horda renascida, e a profecia encontrou seu estranho."]},"item:book-of-medivh":{title:"O Livro de Medivh",summary:"O \xfaltimo grim\xf3rio de Medivh que restou, usado duas vezes para rasgar a passagem entre os mundos.",body:["Depois da morte de Medivh, seu grim\xf3rio foi guardado na biblioteca real da Ventobravo reconstru\xedda, at\xe9 que agentes de Alterac o roubaram. Por meio de um acordo entre o rei de Alterac e o cavaleiro da morte da Horda Teron Gorefiend, ele passou aos orcs, e em Draenor Ner'zhul o usou com outras rel\xedquias para abrir novos portais, fendas que despeda\xe7aram seu mundo. Antes da queda do Portal Negro, Khadgar recuperou o livro e o mandou para casa no lombo de um grifo.","O Kirin Tor o selou em um cofre em Dalaran. Durante a Terceira Guerra, Kel'Thuzad arrombou esse cofre e, com o poder do livro, abriu a fenda pela qual Archimonde e a Legi\xe3o Ardente entraram em Azeroth. Depois disso, o livro ficou nas m\xe3os do lich."]},"item:frostmourne":{title:"G\xe9lido Lamento",summary:"A l\xe2mina r\xfanica do Lich Rei, que tomou a alma de Arthas Menethil no gelo de Nort\xfandria.",body:["G\xe9lido Lamento estava ligada \xe0 pris\xe3o do Lich Rei na Coroa de Gelo, e Ner'zhul a expeliu do Trono de Gelo para atrair um campe\xe3o. Ela aguardava, guardada, numa caverna congelada de Nort\xfandria, com um aviso de que seu poder marcaria a alma de quem a empunhasse. O pr\xedncipe Arthas, desesperado para deter a praga, ignorou o aviso e tomou a l\xe2mina enquanto Muradin Barbabronze jazia abatido por um estilha\xe7o de gelo.","A espada devora as almas daqueles que mata. Com ela, Arthas matou o senhor do medo Mal'Ganis, depois o pr\xf3prio pai, o rei Terenas, e seu antigo mentor Uther. No ano 25, ela repousa ao lado do pr\xf3prio Lich Rei. Em hist\xf3rias posteriores, al\xe9m do Classic, Tirion Fordring a despeda\xe7ou com a Ashbringer."]},"item:ashbringer":{title:"Ashbringer",summary:"Uma l\xe2mina sagrada forjada em Altaforja para reduzir os mortos-vivos a cinzas, depois tra\xedda e corrompida nas Terras Pestilentas.",body:["Durante a Segunda Guerra, o Gr\xe3o-lorde Alexandros Mograine, da M\xe3o de Prata, encontrou um cristal sombrio no corpo de um bruxo orc abatido. Quando o Flagelo amea\xe7ou Lordaeron, os l\xedderes da ordem tentaram destru\xed-lo com magia sagrada; em vez disso, o cristal absorveu a Luz e ficou radiante. O rei Magni Barbabronze o forjou como espada sobre a Grande Bigorna de Altaforja, e nas m\xe3os de Mograine a Ashbringer reduzia os mortos-vivos a cinzas.","O senhor do medo Balnazzar e Kel'Thuzad tramaram sua queda. Renault, filho de Mograine, o levou a uma emboscada do Flagelo em Stratholme e o matou com a pr\xf3pria espada, corrompendo-a. No ano 25, Alexandros serve Kel'Thuzad como cavaleiro da morte, enquanto Renault comanda o Monast\xe9rio Escarlate. S\xf3 em hist\xf3rias posteriores a l\xe2mina foi purificada."]},"item:skull-of-guldan":{title:"O Cr\xe2nio de Gul'dan",summary:"O cr\xe2nio do bruxo, uma rel\xedquia demon\xedaca que abriu portais, envenenou o Vale Gris e transformou Illidan.",body:["Gul'dan foi despeda\xe7ado por dem\xf4nios na Tumba de Sargeras, mas seu cr\xe2nio guardou uma lasca de sua mal\xedcia. Ele passou por v\xe1rias m\xe3os orcs at\xe9 que Grom Grito Infernal o levou a Ner'zhul, que o usou para ajudar a reabrir o Portal Negro. Mais tarde, Khadgar o mandou para Dalaran junto com o Livro de Medivh, e o Kirin Tor guardou os dois.","Quando Dalaran caiu na Terceira Guerra, o senhor do medo Tichondrius roubou o cr\xe2nio, e seu poder contaminou as florestas do Vale Gris e da Selva Maleva. Illidan Tempesf\xfaria consumiu sua magia, tornou-se meio dem\xf4nio e matou Tichondrius com esse poder. A casca do cr\xe2nio ficou com Illidan."]},"item:gorehowl":{title:"Gorehowl",summary:"O machado uivante da fam\xedlia Grito Infernal, que derrubou tanto Cenarius quanto Mannoroth.",body:["Gorehowl foi forjado gera\xe7\xf5es antes de Grom Grito Infernal herd\xe1-lo, e uma lenda dos Brado Guerreiro diz que o machado foi temperado com o cora\xe7\xe3o de poderosos gronns. Grom, chefe do cl\xe3 Brado Guerreiro, foi o primeiro a beber o sangue do senhor do abismo Mannoroth, prendendo os orcs \xe0 Legi\xe3o Ardente. No Vale Gris, ele bebeu de novo e, com Gorehowl, matou o semideus Cenarius.","Thrall o libertou das garras do dem\xf4nio, e juntos eles enfrentaram Mannoroth. Grom partiu a arma do senhor do abismo e o matou com um \xfanico golpe, quebrando a maldi\xe7\xe3o sobre seu povo ao custo da pr\xf3pria vida. Depois disso, Thrall guardou o machado em Orgrimmar."]},"item:horn-of-cenarius":{title:"A Trompa de Cenarius",summary:"A trompa do semideus, que despertou os druidas de seu longo sono e chamou os ancestrais dos elfos noturnos em Hyjal.",body:["Depois da queda de Cenarius, sua trompa ficou na Clareira da Lua sob a vigil\xe2ncia de antigos guardi\xf5es. Quando a Legi\xe3o Ardente voltou na Terceira Guerra, a sacerdotisa Tyrande Sussurravento a recuperou e a usou para despertar Malfurion Tempesf\xfaria de seu longo sonho. Malfurion, por sua vez, a fez soar para despertar os druidas adormecidos do Tal\xe3o e da Garra.","No auge da Batalha do Monte Hyjal, Malfurion tocou a trompa mais uma vez. Milhares de esp\xedritos ancestrais responderam e se lan\xe7aram sobre Archimonde, destruindo o senhor demon\xedaco ao p\xe9 da \xc1rvore do Mundo, embora o poder liberado tenha deixado Nordrassil ferida."]},"item:sulfuras":{title:"Sulfuras, a M\xe3o de Ragnaros",summary:"O martelo ardente do Senhor do Fogo, e a c\xf3pia menor que mestres ferreiros aprenderam a forjar \xe0 sua imagem.",body:["Sulfuras \xe9 o colossal martelo de Ragnaros, uma massa de elementium vermelho em chamas que o Senhor do Fogo nunca solta. Nas guerras elementais de um passado distante, ele abateu com ela Thunderaan, o Pr\xedncipe do Ar. Desde a invoca\xe7\xe3o feita por Thaurissan, Ragnaros governa o N\xfacleo Derretido, sob a Montanha Rocha Negra, com o martelo em punho.","A arma verdadeira \xe9 grande demais para m\xe3os mortais, mas \xe9 poss\xedvel fazer uma r\xe9plica. No jogo original, um mestre ferreiro obtinha os planos de um Martelo de Sulfuron com Lokhtos Darkbargainer, da Irmandade do T\xf3rio, no Abismo Rocha Negra, e depois o unia ao raro Olho de Sulfuras tirado do pr\xf3prio Ragnaros, criando uma M\xe3o de Ragnaros do tamanho de um mortal."]},"item:thunderfury":{title:"Thunderfury, Blessed Blade of the Windseeker",summary:"Uma espada forjada em torno da \xfaltima ess\xeancia de Thunderaan, o Pr\xedncipe do Ar, que Ragnaros havia aprisionado.",body:["Numa guerra antiga entre o fogo e o ar, Ragnaros e seus tenentes Garr e Bar\xe3o Geddon derrotaram Thunderaan, o Pr\xedncipe do Ar. O Senhor do Fogo se alimentou de sua ess\xeancia, mas n\xe3o conseguiu devor\xe1-la inteira; por isso selou o restante em um talism\xe3, partiu-o em dois e deu uma metade a cada tenente: as Bindings of the Windseeker.","No jogo original, as raides tomavam as duas metades de Garr e de Geddon no N\xfacleo Derretido e as levavam ao Gr\xe3o-lorde Demitrian, em Silithus. Com a ess\xeancia do pr\xf3prio Senhor do Fogo e barras de elementium encantado, as amarras invocavam o pr\xedncipe enfraquecido; depois que ele era derrotado, Demitrian forjava o poder que lhe restava na Thunderfury, uma l\xe2mina que crepita com uma tempestade viva."]},"item:seal-of-ascension":{title:"Selo da Ascens\xe3o",summary:"Um anel forjado em fogo de drag\xe3o negro que abria a cidadela superior do Pico da Rocha Negra.",body:["Os sal\xf5es superiores do Pico da Rocha Negra, onde Rend M\xe3o Negra e a revoada negra mantinham sua corte, estavam selados contra invasores. No pico inferior, um estranho disfar\xe7ado chamado Vaelan, na verdade o drag\xe3o vermelho Vaelastrasz, que jurara ca\xe7ar Nefarian, ensinava os aventureiros a fazer uma chave: um selo sem adornos cravejado com tr\xeas gemas tiradas dos comandantes Smolderthorn, Spirestone e Bloodaxe do Pico.","Depois, o selo precisava ser forjado em fogo de drag\xe3o negro. Os her\xf3is viajavam at\xe9 o Wyrmbog, no P\xe2ntano Vadeoso, e obrigavam o draco Emberstrife a soprar sobre ele. O anel pronto abria a cidadela superior e, na luta contra Rend, podia chamar uma proje\xe7\xe3o de Vaelastrasz para o lado dos her\xf3is."]},"item:drakefire-amulet":{title:"Drakefire Amulet",summary:"O amuleto partido de Onyxia, refeito com o sangue de um drag\xe3o negro para se tornar a chave de seu pr\xf3prio covil.",body:["Disfar\xe7ada de Lady Katrana Prestor, Onyxia abriu caminho na corte de Ventobravo com um pingente chamado Olho do Drag\xe3o. Ele n\xe3o controlava as mentes diretamente, mas despertava desejos ocultos e desviava dela as suspeitas. Quando o Marechal Windsor desmascarou a farsa, o pingente se despeda\xe7ou, e o drag\xe3o azul Haleh refez seus peda\xe7os, com o sangue do General Drakkisath, transformando-os no Drakefire Amulet.","Os her\xf3is da Horda chegam ao mesmo amuleto por outro caminho, por meio de Rexxar e das prova\xe7\xf5es do antigo draco Emberstrife. Todo membro de raide que entra no Covil da Onyxia precisa us\xe1-lo, e Forever mant\xe9m essa sintoniza\xe7\xe3o como uma s\xe9rie de miss\xf5es separada para cada fac\xe7\xe3o."]},"item:head-of-onyxia":{title:"Cabe\xe7a de Onyxia",summary:"A prova da morte da M\xe3e da Ninhada, erguida sobre os port\xf5es de Ventobravo ou de Orgrimmar como estandarte de uni\xe3o.",body:["Onyxia, filha de Asa da Morte e irm\xe3 mais nova de Nefarian, guarda sua ninhada numa caverna do P\xe2ntano Vadeoso enquanto trama dobrar os reinos mortais de Azeroth \xe0 sua vontade. Derrot\xe1-la p\xf4s fim a uma das mais longas farsas da revoada negra.","No jogo original, sua cabe\xe7a era levada para casa como trof\xe9u: os campe\xf5es da Alian\xe7a a apresentavam em Ventobravo, e os da Horda, a Thrall em Orgrimmar. Erguida sobre os port\xf5es da cidade, ela concedia o Grito de Guerra do Matador de Drag\xf5es a todos que estavam na cidade, e a capital inteira comemorava a vit\xf3ria."]},"item:quel-serrar":{title:"Quel'Serrar",summary:"Uma antiga l\xe2mina dos elfos noturnos guardada pelos Shen'dralar e conclu\xedda apenas no sopro de um drag\xe3o.",body:["Quel'Serrar \xe9 uma das l\xe2minas prism\xe1ticas que os ferreiros elfos noturnos forjaram h\xe1 muito tempo com a ajuda das revoadas; sua g\xeamea, Quel'Delar, foi dada aos altos elfos. Por milhares de anos, os Shen'dralar de Eldre'Thalas a guardaram, \xe0 espera de algu\xe9m forte o bastante para despert\xe1-la.","No jogo original, um guerreiro ou paladino que encontrava um velho comp\xeandio sobre a ca\xe7a a drag\xf5es o levava ao Guardi\xe3o do Saber Lydros, na biblioteca do Gl\xe1dio Cruel, e recebia uma l\xe2mina sem t\xeampera. Aquecido pelo sopro profundo de Onyxia e cravado no drag\xe3o abatido, o a\xe7o se tornava Quel'Serrar quando era devolvido a Lydros."]},"item:rhokdelar":{title:"Rhok'delar e Lok'delar",summary:"Um arco longo e um bord\xe3o vivos, moldados pelos Anci\xf5es corrompidos da Selva Maleva para o ca\xe7ador que os vingou.",body:["Quando a Legi\xe3o Ardente varreu Kalimdor, envenenou o vale que se tornou a Selva Maleva. Seus Anci\xf5es mais poderosos murcharam at\xe9 virar cascas petrificadas, mas seus esp\xedritos permaneceram. Uma folha de um deles, Vartrus, acabou no tesouro do Senhor do Fogo, no N\xfacleo Derretido.","No jogo original, o ca\xe7ador que devolvia a folha a Vartrus era enviado para ca\xe7ar sozinho quatro agentes da Legi\xe3o, sem nem mesmo um ajudante. Em troca, os Anci\xf5es criavam Rhok'delar, um arco longo que floresce sozinho, e seu companheiro Lok'delar, um bord\xe3o que brilha com o poder da natureza."]},"item:taelans-hammer":{title:"O Martelo de Taelan",summary:"O martelo de brinquedo de uma crian\xe7a, que ajudou Tirion Fordring a alcan\xe7ar o filho que a Cruzada Escarlate lhe havia tirado.",body:["No seu s\xe9timo anivers\xe1rio, o pequeno Taelan ganhou do pai, Tirion Fordring, um martelo de guerra em miniatura, c\xf3pia do martelo do pr\xf3prio Tirion. Depois que Tirion foi exilado por defender o orc Eitrigg, a m\xe3e de Taelan disse ao menino que o pai havia morrido e o levou a um t\xfamulo falso no Undercroft, nas Terras Pestilentas Orientais, onde ele enterrou o martelo e, com ele, a lembran\xe7a.","Anos depois, Taelan se tornou Gr\xe3o-lorde da Cruzada Escarlate em Hearthglen. No jogo original, aventureiros recuperavam o martelo para o j\xe1 idoso Tirion e ajudavam Taelan a ver no que a Cruzada havia se transformado. Enquanto fugia de Hearthglen, o Grande Inquisidor Isillien o abateu diante dos olhos do pai; Tirion matou Isillien e jurou forjar novamente a M\xe3o de Prata."]},"item:heart-of-hakkar":{title:"Cora\xe7\xe3o de Hakkar",summary:"O cora\xe7\xe3o ainda em brasa do Deus do Sangue, levado aos Zandalari depois que Hakkar foi morto em Zul'Gurub.",body:["Cerca de quinze s\xe9culos antes do Portal Negro, os famintos trolls Gurubashi recorreram a Hakkar the Soulflayer, um loa do sangue. Ele lhes deu poder e um imp\xe9rio e depois passou a exigir cada vez mais vidas, at\xe9 que as tribos se rebelaram contra ele e exilaram seus sacerdotes Atal'ai. Quando os sacerdotes ergueram um templo para traz\xea-lo de volta, Ysera o destro\xe7ou e o afundou sob os brejos do P\xe2ntano das M\xe1goas.","No jogo original, os sacerdotes Hakkari finalmente atra\xedram o Soulflayer para Zul'Gurub. Her\xf3is reunidos pela tribo Zandalar o mataram ali e levaram seu cora\xe7\xe3o, ainda brilhando, at\xe9 Molthor, na Ilha Yojamba, cujo rito aben\xe7oava com o Esp\xedrito de Zandalar todos que estavam na ilha e em Angra do Butim."]},"item:phylactery-of-kelthuzad":{title:"O Filact\xe9rio de Kel'Thuzad",summary:"O recipiente que guarda a alma do arquilich, levado de Naxxramas depois de sua derrota.",body:["Kel'Thuzad, antes arquimago do Kirin Tor, fundou o Culto dos Malditos e espalhou a praga para o Lich Rei. Morto por Arthas e depois levado \xe0 Nascente do Sol para renascer como lich, ele passou a governar o Flagelo em Lordaeron a partir da necr\xf3pole flutuante de Naxxramas.","Um lich perdura enquanto sobreviver o recipiente que guarda sua alma. No jogo original, as raides que derrotavam Kel'Thuzad recuperavam seu filact\xe9rio e o entregavam \xe0 Aurora Arg\xeantea para que fosse guardado. Hist\xf3rias posteriores revelaram que um de seus sacerdotes, o Padre Inigo Montoy, traiu essa confian\xe7a e o levou para Nort\xfandria, dando ao arquilich tempo para voltar."]}}},1621,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return o}});const o={"term:argent-dawn":{title:"Aurora Arg\xeantea",summary:"Uma ordem que jurou defender Azeroth do Flagelo sem o \xf3dio cego da Cruzada Escarlate.",body:["Quando os sobreviventes da M\xe3o de Prata em Lordaeron se endureceram at\xe9 virar a fan\xe1tica Cruzada Escarlate, alguns se recusaram a segui-los. Liderados por figuras como Lorde Maxwell Tyrosus, eles formaram a Aurora Arg\xeantea, que acolhe qualquer um disposto a lutar contra os mortos-vivos. Da Capela Esperan\xe7a da Luz, nas Terras Pestilentas Orientais, a ordem vigia o Flagelo e recompensa quem ajuda a manter a linha de frente."]},"term:burning-legion":{title:"Legi\xe3o Ardente",summary:"O ex\xe9rcito infinito de dem\xf4nios do tit\xe3 ca\xeddo Sargeras, que jurou queimar toda a cria\xe7\xe3o.",body:["Antes campe\xe3o do Pante\xe3o dos tit\xe3s, Sargeras descobriu que os poderes do Caos queriam corromper as almas-mundo e, em desespero, decidiu queimar a cria\xe7\xe3o em vez de deix\xe1-la cair nas m\xe3os deles. Ele libertou os dem\xf4nios que havia aprisionado e conquistou os senhores eredar Kil'jaeden e Archimonde para comand\xe1-los. A Legi\xe3o invadiu Azeroth na Guerra dos Antigos e de novo na Terceira Guerra, e seus agentes ainda espreitam em lugares como a Selva Maleva e a Barreira do Inferno."]},"term:cenarion-circle":{title:"C\xedrculo Cenariano",summary:"A ordem dru\xeddica de elfos noturnos e taurens que guarda o equil\xedbrio da natureza a partir da Clareira da Lua.",body:["Batizado em homenagem ao semideus Cenarius, que ensinou os primeiros druidas, o C\xedrculo une druidas elfos noturnos e taurens em uma \xfanica ordem. Seu cora\xe7\xe3o \xe9 o vilarejo de Nighthaven, na Clareira da Lua, um santu\xe1rio onde \xe9 proibido lutar, e seus membros tamb\xe9m vigiam os perigos de Silithus a partir do Forte Cenariano."]},"term:cult-of-the-damned":{title:"Culto dos Malditos",summary:"O culto ao Lich Rei fundado por Kel'Thuzad, que prometia a vida eterna e trouxe a praga.",body:["O arquimago Kel'Thuzad deu as costas ao Kirin Tor para estudar necromancia e reuniu os pobres e desesperados de Lordaeron com promessas de uma vida melhor e sem morte. O culto escondeu a praga do Lich Rei em carregamentos de gr\xe3os, transformando vilarejos inteiros em Flagelo. Seus necromantes ainda ensinam em Scholomance, em Caer Darrow, a antiga fortaleza da fam\xedlia Barov."]},"term:dark-portal":{title:"Portal Negro",summary:"A passagem entre Draenor e Azeroth pela qual a Horda dos orcs invadiu.",body:["O bruxo orc Gul'dan e o Guardi\xe3o possu\xeddo Medivh abriram o Portal Negro, ligando Draenor ao Lama\xe7al Negro de Azeroth. Sua abertura deu in\xedcio \xe0 Primeira Guerra, e os anos da hist\xf3ria de Warcraft ainda s\xe3o contados a partir dela. A Alian\xe7a o destruiu depois da Segunda Guerra, Ner'zhul o reabriu \xe0 for\xe7a, e Khadgar o fez desabar do lado de Draenor. Sua estrutura adormecida ainda se ergue sobre a Barreira do Inferno."]},"term:defias-brotherhood":{title:"Irmandade D\xe9fias",summary:"Pedreiros de Ventobravo que nunca foram pagos e viraram bandidos sob o comando de Edwin VanCleef.",body:["A Guilda dos Pedreiros reconstruiu Ventobravo depois da Segunda Guerra, mas os nobres se recusaram a pag\xe1-la. Seu l\xedder, Edwin VanCleef, levou os pedreiros revoltados para o Cerro Oeste e os transformou na Irmandade D\xe9fias, um bando de ladr\xf5es e sabotadores escondido nas Minas Mortas. Em Forever, seus membros tamb\xe9m aparecem dentro da Alcaz Prison, envolvidos numa luta contra os nagas."]},"term:dragon-aspects":{title:"Aspectos Drag\xf4nicos",summary:"Cinco grandes drag\xf5es que receberam poder dos tit\xe3s para proteger Azeroth, cada um \xe0 frente de uma revoada.",body:["Os tit\xe3s escolheram cinco drag\xf5es e deram a cada um parte de seu poder: Alexstrasza, a M\xe3e da Vida, da revoada vermelha; Ysera, a Sonhadora, da verde; Nozdormu, o Atemporal, da bronze; Malygos, o Tecel\xe3o de Feiti\xe7os, da azul; e Neltharion, o Guardi\xe3o da Terra, da negra. A trai\xe7\xe3o de Neltharion o transformou em Asa da Morte, e seus filhos Onyxia e Nefarian ainda tramam em Azeroth."]},"term:elemental-lords":{title:"Senhores Elementais",summary:"Os quatro soberanos do fogo, da terra, do ar e da \xe1gua, antes servos dos Deuses Antigos.",body:["Ragnaros do fogo, Therazane da terra, Al'Akir do ar e Neptulon da \xe1gua lideraram os elementais na guerra dos Deuses Antigos contra os servos dos tit\xe3s. Quando o Imp\xe9rio Negro caiu, os guardi\xf5es os prenderam no Plano Elemental. Os xam\xe3s procuram manter os elementos em equil\xedbrio, enquanto o erro do feiticeiro Ferro Negro Thaurissan trouxe Ragnaros de volta ao mundo, sob a Montanha Rocha Negra."]},"term:elune":{title:"Eluna",summary:"A deusa da lua dos elfos noturnos, cujas sacerdotisas guiam seu povo.",body:["Os elfos noturnos adoram Eluna desde o in\xedcio de sua civiliza\xe7\xe3o, buscando orienta\xe7\xe3o na luz da lua. A Irmandade de Eluna, liderada pela suma sacerdotisa Tyrande Sussurravento, atua ao mesmo tempo como clero e como lideran\xe7a em Darnassus, e os sacerdotes elfos noturnos tiram da deusa seu poder de cura."]},"term:emerald-dream":{title:"Sonho Esmeralda",summary:"Um reflexo on\xedrico das terras selvagens e intocadas de Azeroth, guardado por Ysera e percorrido pelos druidas.",body:["O Sonho Esmeralda reflete o mundo como ele poderia ter sido sem m\xe3os mortais. Ysera e sua revoada verde o guardam, e os druidas entram nele em esp\xedrito, \xe0s vezes dormindo por s\xe9culos. No presente de Azeroth, algo est\xe1 azedando o Sonho: um pesadelo que se alastra distorce os sonhos de Naralex na Caverna Ululante e enlouqueceu os drag\xf5es verdes do Templo Submerso."]},"term:explorers-league":{title:"Liga dos Exploradores",summary:"A sociedade de arque\xf3logos an\xf5es de Altaforja, que escava em busca dos segredos dos tit\xe3s.",body:["Do Sal\xe3o dos Exploradores, em Altaforja, a Liga envia an\xf5es pelo mundo inteiro em busca de rel\xedquias que possam explicar de onde seu povo veio. Seu membro mais famoso \xe9 Brann Barbabronze, o irm\xe3o inquieto do rei. Os escavadores da Liga desenterraram as c\xe2maras dos tit\xe3s de Uldaman, e em Forever as estranhas ru\xednas congeladas no tempo al\xe9m do Whelgar's Excavation Site, no Pantanal, s\xe3o exatamente o tipo de mist\xe9rio que a Liga persegue."]},"term:fel":{title:"Vileza",summary:"A magia ardente e corruptora da Legi\xe3o Ardente.",body:["A vileza \xe9 a magia dos dem\xf4nios: poderosa, viciante e ruinosa para tudo o que toca. Os bruxos de Gul'dan a usaram para drenar a vida de Draenor e prender os orcs \xe0 Legi\xe3o, e sua m\xe1cula deixou a pele deles verde. Os bruxos ainda a empunham hoje, e suas cicatrizes marcam a Selva Maleva, onde a corrup\xe7\xe3o demon\xedaca envenenou uma floresta ancestral."]},"term:guardian-of-tirisfal":{title:"Guardi\xe3o de Tirisfal",summary:"Um mago que recebe o poder somado de um conselho secreto para combater sozinho a Legi\xe3o Ardente.",body:["Magos altos elfos e humanos formaram o secreto Conselho de Tirisfal para impedir que dem\xf4nios entrassem no mundo por meio de magia imprudente. Em cada era, o conselho despejava seu poder num \xfanico campe\xe3o, o Guardi\xe3o. Aegwynn exerceu esse papel por s\xe9culos; seu filho Medivh, o \xfaltimo Guardi\xe3o, estava secretamente possu\xeddo por Sargeras e abriu o caminho para os orcs."]},"term:highborne":{title:"Bem-nascidos",summary:"A aristocracia arcana do antigo imp\xe9rio dos elfos noturnos, cuja fome de magia atraiu a Legi\xe3o.",body:["Os Bem-nascidos serviam \xe0 rainha Azshara como sua corte e seus feiticeiros, bebendo cada vez mais fundo da Nascente da Eternidade at\xe9 que seus feiti\xe7os chamaram a aten\xe7\xe3o de Sargeras. Depois da Grande Cis\xe3o, a maioria dos sobreviventes foi exilada e fundou Quel'Thalas como os altos elfos. Outros, os Shen'dralar, permaneceram escondidos em Eldre'Thalas, a cidade hoje chamada Gl\xe1dio Cruel."]},"term:holy-light":{title:"A Luz Sagrada",summary:"O poder da esperan\xe7a e da virtude que paladinos e sacerdotes canalizam.",body:["Os humanos veneram a Luz por meio da Igreja da Luz Sagrada, cujos cl\xe9rigos curam os feridos e cujas catedrais se erguem em Ventobravo e um dia se ergueram em Lordaeron. Os an\xf5es tamb\xe9m a abra\xe7aram. Durante a Segunda Guerra, o arcebispo Alonsus Faol uniu f\xe9 e a\xe7o ao fundar os paladinos da M\xe3o de Prata, e a Luz continua sendo a ru\xedna dos mortos-vivos."]},"term:kaldorei":{title:"Kaldorei",summary:"Os elfos noturnos, os \u201cfilhos das estrelas\u201d, uma das civiliza\xe7\xf5es mais antigas de Kalimdor.",body:["Descendentes de trolls transformados pela Nascente da Eternidade, os elfos noturnos constru\xedram sob a rainha Azshara um imp\xe9rio deslumbrante antes que ele afundasse na Grande Cis\xe3o. Por dez mil anos viveram como druidas e Sentinelas, sem envelhecer gra\xe7as a Nordrassil, at\xe9 que a Terceira Guerra lhes custou a imortalidade. Hoje governam a partir de Darnassus, no alto de Teldrassil, e est\xe3o ao lado da Alian\xe7a."]},"term:kirin-tor":{title:"Kirin Tor",summary:"O conselho de magos que governa Dalaran e guarda magias perigosas.",body:["Fundado na cidade dos magos, Dalaran, o Kirin Tor supervisiona o estudo da magia arcana e tranca artefatos perigosos demais para o mundo. Archimonde deixou Dalaran em ru\xednas durante a Terceira Guerra, e no jogo original a cidade ficava escondida sob uma c\xfapula violeta. Em Forever, essa barreira caiu e revela uma restaura\xe7\xe3o tomada por um caos arcano descontrolado."]},"term:ley-lines":{title:"Linhas Ley",summary:"Correntes de energia arcana que percorrem Azeroth como veias.",body:["As linhas ley levam poder arcano bruto pelo mundo, e onde elas se cruzam a magia ganha for\xe7a. Os altos elfos ergueram a Nascente do Sol num desses pontos de encontro, e os magos buscam essas correntes h\xe1 muito tempo. Em Forever, os Skyborne da High Order podem aproveit\xe1-las com sua habilidade racial Read Ley Line, que dura muito mais quando usada perto de uma delas."]},"term:lich-king":{title:"Lich Rei",summary:"O senhor imortal do Flagelo, entronado no gelo de Nort\xfandria.",body:["Kil'jaeden arrancou o esp\xedrito do xam\xe3 orc Ner'zhul de seu corpo e o selou num bloco de gelo no alto da Coroa de Gelo, o Trono de Gelo, para preparar Azeroth para a Legi\xe3o. De l\xe1, o Lich Rei ergueu o Flagelo e espalhou a praga. Depois da Terceira Guerra, o pr\xedncipe Arthas subiu ao trono e se fundiu com ele, e o Lich Rei unificado agora aguarda em Nort\xfandria."]},"term:loa":{title:"Loa",summary:"Os poderosos esp\xedritos animais e deuses que os trolls veneram.",body:["Toda tribo troll honra os loas, esp\xedritos antigos que muitas vezes assumem a forma de grandes feras, e barganha com eles em troca de for\xe7a. Alguns s\xe3o vol\xfaveis, mas justos; outros s\xe3o cru\xe9is. Hakkar the Soulflayer, o loa do sangue, quase devorou o Imp\xe9rio Gurubashi, e seus seguidores ainda se agitam na Selva do Espinha\xe7o e no P\xe2ntano das M\xe1goas."]},"term:nathrezim":{title:"Nathrezim",summary:"Os senhores do medo: dem\xf4nios astutos e vampirescos que servem \xe0 Legi\xe3o por meio do engano.",body:["Os nathrezim preferem sussurros \xe0 guerra aberta. A Legi\xe3o encarregou senhores do medo como Mal'Ganis, Tichondrius e Balnazzar de vigiar o Lich Rei e guiar a conquista de Lordaeron pelo Flagelo. Quando o Lich Rei se libertou deles, eles se dispersaram, mas alguns ainda se escondem \xe0 vista de todos: Balnazzar usa o rosto do Gr\xe3o-cruzado da Cruzada Escarlate."]},"term:nordrassil":{title:"Nordrassil",summary:"A \xc1rvore do Mundo do Monte Hyjal, plantada pelos Aspectos para selar a segunda Nascente da Eternidade.",body:["Depois da Grande Cis\xe3o, Illidan derramou em segredo \xe1gua roubada da Nascente da Eternidade num lago do Monte Hyjal. Para selar essa nova nascente, os Aspectos Drag\xf4nicos plantaram uma semente encantada que cresceu e se tornou Nordrassil, e sua b\xean\xe7\xe3o fez com que os elfos noturnos n\xe3o envelhecessem. A queda de Archimonde junto \xe0s suas ra\xedzes feriu a \xe1rvore, e a raide Hyjal Summit de Forever sobe at\xe9 o pico ao lado dela."]},"term:old-gods":{title:"Deuses Antigos",summary:"Seres ancestrais do Caos que se enterraram em Azeroth para corromper sua alma-mundo.",body:["Muito antes de os mortais caminharem pelo mundo, os Deuses Antigos, entre eles C'Thun, Yogg-Saron, N'Zoth e Y'Shaarj, ca\xedram sobre Azeroth e ergueram um Imp\xe9rio Negro. Arrancar Y'Shaarj feriu o pr\xf3prio mundo, por isso os tit\xe3s preferiram aprisionar os outros debaixo da terra. Seus sussurros ainda movem cultos como o Martelo do Crep\xfasculo, e C'Thun se agita sob Ahn'Qiraj, em Silithus."]},"term:silver-hand":{title:"Ordem da M\xe3o de Prata",summary:"A primeira ordem de paladinos, fundada em Lordaeron durante a Segunda Guerra.",body:["O arcebispo Alonsus Faol percebeu que os cl\xe9rigos sozinhos n\xe3o sobreviveriam \xe0 Horda, ent\xe3o treinou guerreiros nos caminhos da Luz. Uther, o Arauto da Luz, tornou-se o primeiro dos Cavaleiros da M\xe3o de Prata. A ordem lutou durante toda a Segunda Guerra, mas a queda de Arthas a destro\xe7ou: Uther morreu pelas m\xe3os de seu antigo aluno, e muitos sobreviventes foram parar na Cruzada Escarlate."]},"term:queldorei":{title:"Quel'dorei",summary:"Os altos elfos de Quel'Thalas, herdeiros dos Bem-nascidos exilados.",body:["Quase sete mil anos antes do Portal Negro, Bem-nascidos exilados cruzaram o mar, fundaram Quel'Thalas e acenderam a Nascente do Sol. Eles se aliaram aos humanos de Arathor nas Guerras Trolls e lhes ensinaram a magia. Quando o Flagelo de Arthas devastou seu reino e profanou a Nascente do Sol, a maioria dos sobreviventes adotou um novo nome em mem\xf3ria de seus mortos: os sin'dorei, ou elfos sangrentos."]},"term:scarlet-crusade":{title:"Cruzada Escarlate",summary:"Fan\xe1ticos que ca\xe7am os mortos-vivos e qualquer um que suspeitem carregar a praga, liderados em segredo por um senhor do medo.",body:["Nascida dos paladinos e soldados sobreviventes de Lordaeron, a Cruzada jurou expurgar o Flagelo, mas ficou t\xe3o fan\xe1tica que ataca tanto os Renegados quanto viajantes vivos. Seu Gr\xe3o-cruzado \xe9, em segredo, o senhor do medo Balnazzar. Entre seus basti\xf5es est\xe3o o Monast\xe9rio Escarlate, nas Clareiras de Tirisfal, Hearthglen e a M\xe3o de Tyr."]},"term:scourge":{title:"Flagelo",summary:"O ex\xe9rcito de mortos-vivos do Lich Rei, espalhado pela praga e pela necromancia.",body:["O Flagelo est\xe1 preso \xe0 vontade do Lich Rei: carni\xe7ais, abomina\xe7\xf5es, liches e cavaleiros da morte erguidos dentre os ca\xeddos. A praga que o criou varreu Lordaeron na Terceira Guerra e deixou para tr\xe1s as Terras Pestilentas. Sob Kel'Thuzad, o Flagelo ainda domina Stratholme e Scholomance, e seu alcance chega at\xe9 Razorfen Downs, nos Sert\xf5es."]},"term:skywall":{title:"Skywall",summary:"O Plano Elemental do ar, reino de Al'Akir, o Senhor dos Ventos.",body:["Quando os servos dos tit\xe3s prenderam os elementais, os senhores do ar foram confinados em Skywall, um reino de c\xe9u sem fim governado por Al'Akir. Em Forever, Skywall tamb\xe9m abriga Zephras Isle, a zona inicial flutuante dos Skyborne. Os elementais do ar da ilha desapareceram h\xe1 s\xe9culos, e a magia que a mant\xe9m no alto est\xe1 enfraquecendo aos poucos."]},"term:sunwell":{title:"Nascente do Sol",summary:"A fonte de poder arcano no cora\xe7\xe3o de Quel'Thalas.",body:["Dath'Remar Andassol derramou um frasco roubado da Nascente da Eternidade num lago onde linhas ley se encontram, e a Nascente do Sol ganhou vida num clar\xe3o. Por mil\xeanios, ela alimentou a magia e a cultura dos altos elfos. Durante a Terceira Guerra, Arthas usou suas \xe1guas para erguer Kel'Thuzad como lich e profanou a fonte; sua perda deixou nos sobreviventes uma fome duradoura de magia."]},"term:titan-forged":{title:"Forjados pelos tit\xe3s",summary:"Os guardi\xf5es e outros servos que os tit\xe3s criaram para levar ordem a Azeroth.",body:["Os tit\xe3s moldaram servos para terminar sua obra: guardi\xf5es imponentes e ra\xe7as de pedra e metal, como os terranos e os mecagnomos. Com o passar das eras, a Maldi\xe7\xe3o da Carne dos Deuses Antigos tornou muitos deles mortais, e os an\xf5es e os gnomos descendem deles. Guardi\xf5es forjados pelos tit\xe3s ainda protegem c\xe2maras como Uldaman, e Forever acrescenta outros locais dos tit\xe3s, da escava\xe7\xe3o no Pantanal \xe0 Shaper's Terrace, na Cratera Un'Goro."]},"term:titans":{title:"Tit\xe3s",summary:"Almas-mundo colossais que buscaram trazer ordem ao cosmos e moldaram Azeroth.",body:["Os tit\xe3s s\xe3o almas-mundo que despertaram como seres divinos. Seu Pante\xe3o, liderado por Aman'Thul, vasculhou o cosmos em busca de almas-mundo adormecidas e encontrou uma muito promissora dentro de Azeroth. Eles arrancaram do mundo o Deus Antigo Y'Shaarj, aprisionaram os outros e deixaram para seus servos a tarefa de moldar a terra. Seu campe\xe3o mais poderoso, Sargeras, mais tarde caiu e fundou a Legi\xe3o Ardente."]},"term:twilights-hammer":{title:"Martelo do Crep\xfasculo",summary:"Antes um cl\xe3 orc, hoje um culto apocal\xedptico a servi\xe7o dos Deuses Antigos.",body:["Liderado pelo mago ogro de duas cabe\xe7as Cho'gall, o Martelo do Crep\xfasculo lutou na Segunda Guerra como cl\xe3 orc antes de se transformar num culto que anseia pelo fim do mundo. Seus membros, vindos de todas as ra\xe7as, re\xfanem-se em lugares como as Profundezas Negras e Silithus. Em Forever, o culto tamb\xe9m ocupa as ru\xednas de Sunnyglade, nos Riverglades."]},"term:well-of-eternity":{title:"Nascente da Eternidade",summary:"O lago de poder arcano bruto no cora\xe7\xe3o da antiga Kalimdor, cuja implos\xe3o partiu o mundo.",body:["A Nascente se formou onde os tit\xe3s arrancaram Y'Shaarj do mundo, e os guardi\xf5es acalmaram a ferida que sangrava at\xe9 ela virar um lago de poder puro. Os elfos noturnos constru\xedram seu imp\xe9rio em suas margens, e os feiti\xe7os imprudentes dos Bem-nascidos atra\xedram a Legi\xe3o atrav\xe9s dela. Seu colapso na Guerra dos Antigos causou a Grande Cis\xe3o, e a Voragem se agita onde ela ficava."]}}},1622,[]);